        public async Task<ReturnModel<StateModel>> GetStateByIdAsync(long stateId)
        {
            try
            {
                var item = await systemRepository.GetStateViewByIdAsync(stateId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to find the state", new { stateId });
                }

                return this.ConvertToItem(item, objectMapperService.StateViewToStateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<StateModel>($"Unexpected error when getting the state", new { stateId }, ex);
            }
        }

        public async Task<ReturnModel<StateModel>> CreateStateAsync(StateCreateModel state)
        {
            try
            {
                if (state == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to create a new State", new ReturnErrorItem("", "State information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<StateModel>("You dont have permission to Create State info");
                }

                var errorList = await IsStateModelValidForCreateAsync(state);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to create a new state", errorList);
                }

                state.IsDeleted = false;

                var item = objectMapperService.StateCreateModelToState(state);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateStateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create a new state");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.StateCreatedAsync(item.StateId);

                var view = await systemRepository.GetStateViewByIdAsync(item.StateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to find the state", new { item.StateId });
                }

                return this.ConvertToItem(view, objectMapperService.StateViewToStateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<StateModel>($"Unexpected error when creating new State", new { state }, ex);
            }
        }

        public async Task<ReturnModel<StateModel>> UpdateStateAsync(StateUpdateModel state)
        {
            try
            {
                if (state == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to update State", new ReturnErrorItem("", "State information is not valid"));
                }

                var existingState = await systemRepository.GetStateViewFromAnyByIdAsync(state.StateId);
                if (existingState == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to find the state", new { state });
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<StateModel>("You dont have permission to Update State info");
                }

                state.CreatedByUserId = existingState.CreatedByUserId;
                state.CreatedDate = existingState.CreatedDate;
                state.IsDeleted = existingState.IsDeleted;

                var errorList = await IsStateModelValidForUpdateAsync(state);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to update state", errorList);
                }

                var item = objectMapperService.StateUpdateModelToState(state);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateStateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update state");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.StateUpdatedAsync(state.StateId, existingState, item);

                var view = await systemRepository.GetStateViewByIdAsync(state.StateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<StateModel>($"Unable to find the state", new { state });
                }

                return this.ConvertToItem(view, objectMapperService.StateViewToStateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<StateModel>($"Unexpected error when updating State", new { state }, ex);
            }
        }

