        public Task<List<ReturnErrorItem>> IsStateModelValidForCreateAsync(StateUpdateModel stateModel)
        {
            return IsStateModelValidForAllAsync(true, stateModel);
        }

        public Task<List<ReturnErrorItem>> IsStateModelValidForUpdateAsync(StateUpdateModel stateModel)
        {
            return IsStateModelValidForAllAsync(false, stateModel);
        }

        public async Task<List<ReturnErrorItem>> IsStateModelValidForAllAsync(bool isCreate, StateUpdateModel stateModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsStateNameAlreadyExistsForOtherStateAsync(stateModel.StateName, stateModel.CountryId))
                {
                    result.Add(new ReturnErrorItem("", "Another State already exists"));
                }

                if (stateModel.StateId > 0)
                {
                    result.Add(new ReturnErrorItem("", "State Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsStateNameAlreadyExistsForOtherStateAsync(stateModel.StateId, stateModel.StateName, stateModel.CountryId))
                {
                    result.Add(new ReturnErrorItem("", "Another State already exists"));
                }

                if (stateModel.StateId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "State Unique Identifier is not valid"));
                }
            }

            if (!ValidationUtils.IsLongValid(stateModel.CountryId))
            {
                result.Add(new ReturnErrorItem("CountryId", $"Country Information is not valid"));
            }
            else
            {
                if (!await systemRepository.DoesCountryByIdExistsAsync(stateModel.CountryId))
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the Country Information"));
                    return result;
                }
            }

            if (stateModel.StateName != null && stateModel.StateName.Length > StateModel.COLUMN_SIZE_StateName)
            {
                result.Add(new ReturnErrorItem("StateName", $"StateName size should not exceed {StateModel.COLUMN_SIZE_StateName}"));
            }

            if (stateModel.StateName == null)
            {
                result.Add(new ReturnErrorItem("StateName", "State Name is required "));
            }

            if (stateModel.StateCode != null && stateModel.StateCode.Length > StateModel.COLUMN_SIZE_StateCode)
            {
                result.Add(new ReturnErrorItem("StateCode", $"State Code size should not exceed {StateModel.COLUMN_SIZE_StateCode}"));
            }

            return result.Count > 0 ? result : null;
        }
