        public async Task<ReturnModel<AuditOperationModel>> CreateAuditOperationAsync(AuditOperationCreateModel auditOperation)
        {
            try
            {
                if (auditOperation == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to create AuditOperation", new ReturnErrorItem("", "AuditOperation information is not valid"));
                }

                //var companyModel = await GetCompanyForReadById(auditOperation.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<AuditOperationModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(auditOperation.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<AuditOperationModel>(movieModel);
                //}

                var errorList = await IsAuditOperationModelValidForCreateAsync(auditOperation);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to create auditOperation", errorList);
                }

                auditOperation.IsDeleted = false;

                var item = objectMapperService.AuditOperationCreateModelToAuditOperation(auditOperation);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateAuditOperationAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create auditOperation");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.AuditOperationCreatedAsync(item.AuditOperationId);

                var view = await systemRepository.GetAuditOperationViewByIdAsync(item.AuditOperationId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to find the auditOperation", new { item.AuditOperationId });
                }

                return this.ConvertToItem(view, objectMapperService.AuditOperationViewToAuditOperationModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<AuditOperationModel>($"Unexpected error when creating AuditOperation", new { auditOperation?.AuditOperationId }, ex);
            }
        }

        public async Task<ReturnModel<AuditOperationModel>> UpdateAuditOperationAsync(AuditOperationUpdateModel auditOperation)
        {
            try
            {
                if (auditOperation == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to update AuditOperation", new ReturnErrorItem("", "AuditOperation information is not valid"));
                }

                var existingAuditOperationModel = await GetAuditOperationByIdForWriteAsync(auditOperation.AuditOperationId);
                if (!existingAuditOperationModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>(existingAuditOperationModel);
                }

                auditOperation.CreatedByUserId = existingAuditOperationModel.Model.CreatedByUserId;
                auditOperation.CreatedDate = existingAuditOperationModel.Model.CreatedDate;
                auditOperation.IsDeleted = existingAuditOperationModel.Model.IsDeleted;

                var errorList = await IsAuditOperationModelValidForUpdateAsync(auditOperation);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to update auditOperation", errorList);
                }

                var item = objectMapperService.AuditOperationUpdateModelToAuditOperation(auditOperation);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateAuditOperationAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update auditOperation");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.AuditOperationUpdatedAsync(auditOperation.AuditOperationId, existingAuditOperationModel.Model, item);

                var view = await systemRepository.GetAuditOperationViewByIdAsync(auditOperation.AuditOperationId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationModel>($"Unable to find the auditOperation", new { auditOperation.AuditOperationId });
                }

                return this.ConvertToItem(view, objectMapperService.AuditOperationViewToAuditOperationModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<AuditOperationModel>($"Unexpected error when updating AuditOperation", new { auditOperation?.AuditOperationId }, ex);
            }
        }

