        public async Task<List<ReturnErrorItem>> IsAuditOperationModelValidForAllAsync(bool isCreate, AuditOperationUpdateModel auditOperationModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (auditOperationModel.AuditOperationId > 0)
                {
                    result.Add(new ReturnErrorItem("", "AuditOperation Identifier is not valid"));
                }
            }
            else
            {
                if (auditOperationModel.AuditOperationId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "AuditOperation Unique Identifier is not valid"));
                }
            }

            if (auditOperationModel.UserId > 0)
            {
                if (!await companyRepository.DoesUserByIdExistsAsync(auditOperationModel.UserId ?? 0))
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                    return result;
                }
            }

            if (!DateUtils.IsValidDate(auditOperationModel.AuditDateTime))
            {
                result.Add(new ReturnErrorItem("AuditDateTime", $"AuditDateTime is not a valid date"));
            }

            if (auditOperationModel.PredefinedAuditOperationTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedAuditOperationTypeId", "PredefinedAuditOperationTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedAuditOperationTypes, long>(auditOperationModel.PredefinedAuditOperationTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedAuditOperationTypeId", "Audit Operation Type is not valid"));
            }

            if (auditOperationModel.IpAddress != null && auditOperationModel.IpAddress.Length > AuditOperationModel.COLUMN_SIZE_IpAddress)
            {
                result.Add(new ReturnErrorItem("IpAddress", $"IpAddress size should not exceed {AuditOperationModel.COLUMN_SIZE_IpAddress}"));
            }

            if (auditOperationModel.Description != null && auditOperationModel.Description.Length > AuditOperationModel.COLUMN_SIZE_Description)
            {
                result.Add(new ReturnErrorItem("Description", $"Description size should not exceed {AuditOperationModel.COLUMN_SIZE_Description}"));
            }

            return result.Count > 0 ? result : null;
        }

