                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.TenantId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"AuditOperationFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.TenantId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for AuditOperation ", new { auditOperationId }, ex);
            }
        }

        public async Task CreateOrUpdateAuditOperationDependentsAsync(AuditOperationModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<AuditOperationXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<AuditOperationXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetAuditOperationXYZZYXsByAuditOperationIdAsync(item.AuditOperationId);
            if (dbExistingXYZZYX.Result != null && dbExistingAuditOperation.TotalRows > 0)
            {
                var dbExistingAuditOperationIds = dbExistingAuditOperation.Result.SelectToList(x => x.AuditOperationXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingAuditOperationIds.Contains(x.AuditOperationXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteAuditOperationXYZZYXByIdAsync(x.AuditOperationXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingAuditOperationIds.Contains(x.AuditOperationXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.AuditOperationId = item.AuditOperationId;
                    var mappedItem = objectMapperService.AuditOperationXYZZYXModelToAuditOperationXYZZYXUpdateModel(x);
                    var result = await UpdateAuditOperationXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.AuditOperationId = item.AuditOperationId;
                var result = await CreateAuditOperationXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

