        public async Task<ReturnModel<bool>> AssociateXYZZYXWithAuditOperationAsync(AuditOperationXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsAuditOperationWithAuditOperationAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("AuditOperation association is invalid", errorLst);
                }

                if (await systemRepository.DoesAuditOperationWithXYZZYXAssociationExistsAsync(model.AuditOperationId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related AuditOperation is already associated with the AuditOperation", new { model.AuditOperationId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateAuditOperationWithXYZZYXAsync(model.AuditOperationId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate AuditOperation with XYZZYX", new { model.AuditOperationId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating AuditOperation with XYZZYX", new { model.AuditOperationId, model.XYZZYXId }, ex);
            }
        }

