        public async Task<List<ReturnErrorItem>> IsAuditOperationWithXYZZYXAssociationValidAsync(AuditOperationXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.AuditOperationId == 0)
            {
                result.Add(new ReturnErrorItem("", "AuditOperation is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related AuditOperation  is not valid"));
                return result;
            }

            var entity = await GetAuditOperationForWriteByIdAsync(model.AuditOperationId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "AuditOperation information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "AuditOperations does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

