        public async Task<ReturnModel<AuditOperationDetailModel>> CreateAuditOperationDetailAsync(AuditOperationDetailCreateModel auditOperationDetail)
        {
            try
            {
                if (auditOperationDetail == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to create Audit Operation Detail", new ReturnErrorItem("", "Audit Operation Detail information is not valid"));
                }

                var errorList = await IsAuditOperationDetailModelValidForCreateAsync(auditOperationDetail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to create Audit Operation Detail", errorList);
                }

                auditOperationDetail.IsDeleted = false;

                var item = objectMapperService.AuditOperationDetailCreateModelToAuditOperationDetail(auditOperationDetail);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateAuditOperationDetailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Audit Operation Detail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.AuditOperationDetailCreatedAsync(item.AuditOperationDetailId);

                var view = await systemRepository.GetAuditOperationDetailViewByIdAsync(item.AuditOperationDetailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to find the Audit Operation Detail", new { item.AuditOperationDetailId });
                }

                return this.ConvertToItem(view, objectMapperService.AuditOperationDetailViewToAuditOperationDetailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<AuditOperationDetailModel>($"Unexpected error when creating Audit Operation Detail", new { auditOperationDetail?.AuditOperationDetailId }, ex);
            }
        }

        public async Task<ReturnModel<AuditOperationDetailModel>> UpdateAuditOperationDetailAsync(AuditOperationDetailUpdateModel auditOperationDetail)
        {
            try
            {
                if (auditOperationDetail == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to update Audit Operation Detail", new ReturnErrorItem("", "Audit Operation Detail information is not valid"));
                }

                var existingAuditOperationDetailModel = await GetAuditOperationDetailByIdForWriteAsync(auditOperationDetail.AuditOperationDetailId);
                if (!existingAuditOperationDetailModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>(existingAuditOperationDetailModel);
                }

                auditOperationDetail.CreatedByUserId = existingAuditOperationDetailModel.Model.CreatedByUserId;
                auditOperationDetail.CreatedDate = existingAuditOperationDetailModel.Model.CreatedDate;
                auditOperationDetail.IsDeleted = existingAuditOperationDetailModel.Model.IsDeleted;
                //auditOperationDetail.MovieId = existingAuditOperationDetailModel.Model.MovieId;

                var errorList = await IsAuditOperationDetailModelValidForUpdateAsync(auditOperationDetail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to update Audit Operation Detail", errorList);
                }

                var item = objectMapperService.AuditOperationDetailUpdateModelToAuditOperationDetail(auditOperationDetail);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateAuditOperationDetailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Audit Operation Detail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.AuditOperationDetailUpdatedAsync(auditOperationDetail.AuditOperationDetailId);

                var view = await systemRepository.GetAuditOperationDetailViewByIdAsync(auditOperationDetail.AuditOperationDetailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unable to find the Audit Operation Detail", new { auditOperationDetail.AuditOperationDetailId });
                }

                return this.ConvertToItem(view, objectMapperService.AuditOperationDetailViewToAuditOperationDetailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<AuditOperationDetailModel>($"Unexpected error when updating Audit Operation Detail", new { auditOperationDetail?.AuditOperationDetailId }, ex);
            }
        }

