        public async Task<List<ReturnErrorItem>> IsAuditOperationDetailModelValidForAllAsync(bool isCreate, AuditOperationDetailUpdateModel auditOperationDetailModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (auditOperationDetailModel.AuditOperationDetailId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Audit Operation Detail Identifier is not valid"));
                }
            }
            else
            {
                if (auditOperationDetailModel.AuditOperationDetailId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Audit Operation Detail Unique Identifier is not valid"));
                }
            }

            if (!await systemRepository.DoesAuditOperationByIdExistsAsync(auditOperationDetailModel.AuditOperationId))
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the AuditOperation Information"));
                return result;
            }

            if (!ValidationUtils.IsLongValid(auditOperationDetailModel.AuditOperationId))
            {
                result.Add(new ReturnErrorItem("AuditOperationId", "AuditOperation cannot be empty"));
            }

            if (!await systemRepository.DoesAuditOperationByIdExistsAsync(auditOperationDetailModel.AuditOperationId))
            {
                result.Add(new ReturnErrorItem("AuditOperationId", "AuditOperation is not available"));
            }

            return result.Count > 0 ? result : null;
        }

