        public async Task<ReturnModel<ConfigurationGroupModel>> GetConfigurationGroupByIdInternalAsync(bool forWrite, long configurationGroupId)
        {
            try
            {
                var item = await systemRepository.GetConfigurationGroupViewByIdAsync(configurationGroupId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to find the configurationGroup", new { configurationGroupId });
                }

                if (forWrite && await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>("You need to be a Super Admin to make this change");
                }

                return this.ConvertToItem(item, objectMapperService.ConfigurationGroupViewToConfigurationGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unexpected error when getting configurationGroup", new { configurationGroupId }, ex);
            }
        }

        public async Task<ReturnModel<ConfigurationGroupModel>> CreateConfigurationGroupAsync(ConfigurationGroupCreateModel configurationGroup)
        {
            try
            {
                if (configurationGroup == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to create ConfigurationGroup", new ReturnErrorItem("", "ConfigurationGroup information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to create ConfigurationGroup", new ReturnErrorItem("", "You need to be a Super Admin to Create this Resource"));
                }

                var errorList = IsConfigurationGroupModelValidForCreateAsync(configurationGroup);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to create configurationGroup", errorList);
                }

                configurationGroup.IsDeleted = false;

                var item = objectMapperService.ConfigurationGroupCreateModelToConfigurationGroup(configurationGroup);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateConfigurationGroupAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create configurationGroup");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ConfigurationGroupCreatedAsync(item.ConfigurationGroupId);

                var view = await systemRepository.GetConfigurationGroupViewByIdAsync(item.ConfigurationGroupId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to find the configurationGroup", new { item.ConfigurationGroupId });
                }

                return this.ConvertToItem(view, objectMapperService.ConfigurationGroupViewToConfigurationGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<ConfigurationGroupModel>($"Unexpected error when creating ConfigurationGroup", new { configurationGroup?.ConfigurationGroupId }, ex);
            }
        }

        public async Task<ReturnModel<ConfigurationGroupModel>> UpdateConfigurationGroupAsync(ConfigurationGroupUpdateModel configurationGroup)
        {
            try
            {
                if (configurationGroup == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to update ConfigurationGroup", new ReturnErrorItem("", "ConfigurationGroup information is not valid"));
                }

                var existingConfigurationGroupModel = await GetConfigurationGroupByIdForWriteAsync(configurationGroup.ConfigurationGroupId);
                if (!existingConfigurationGroupModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>(existingConfigurationGroupModel);
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to create ConfigurationGroup", new ReturnErrorItem("", "You need to be a Super Admin to Update this Resource"));
                }

                configurationGroup.CreatedByUserId = existingConfigurationGroupModel.Model.CreatedByUserId;
                configurationGroup.CreatedDate = existingConfigurationGroupModel.Model.CreatedDate;
                configurationGroup.IsDeleted = existingConfigurationGroupModel.Model.IsDeleted;

                var errorList = IsConfigurationGroupModelValidForUpdateAsync(configurationGroup);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to update configurationGroup", errorList);
                }

                var item = objectMapperService.ConfigurationGroupUpdateModelToConfigurationGroup(configurationGroup);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateConfigurationGroupAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update configurationGroup");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ConfigurationGroupUpdatedAsync(configurationGroup.ConfigurationGroupId, existingConfigurationGroupModel.Model, item);

                var view = await systemRepository.GetConfigurationGroupViewByIdAsync(configurationGroup.ConfigurationGroupId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unable to find the configurationGroup", new { configurationGroup.ConfigurationGroupId });
                }

                return this.ConvertToItem(view, objectMapperService.ConfigurationGroupViewToConfigurationGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<ConfigurationGroupModel>($"Unexpected error when updating ConfigurationGroup", new { configurationGroup?.ConfigurationGroupId }, ex);
            }
        }

