        }

        public List<ReturnErrorItem> IsConfigurationGroupModelValidForUpdateAsync(ConfigurationGroupUpdateModel configurationGroupModel)
        {
            return IsConfigurationGroupModelValidForAllAsync(false, configurationGroupModel);
        }

        public List<ReturnErrorItem> IsConfigurationGroupModelValidForAllAsync(bool isCreate, ConfigurationGroupUpdateModel configurationGroupModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (configurationGroupModel.ConfigurationGroupId > 0)
                {
                    result.Add(new ReturnErrorItem("", "ConfigurationGroup Identifier is not valid"));
                }
            }
            else
            {
                if (configurationGroupModel.ConfigurationGroupId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "ConfigurationGroup Unique Identifier is not valid"));
                }
            }

            if (configurationGroupModel.GroupName != null && configurationGroupModel.GroupName.Length > ConfigurationGroupModel.COLUMN_SIZE_GroupName)
            {
                result.Add(new ReturnErrorItem("GroupName", $"GroupName size should not exceed {ConfigurationGroupModel.COLUMN_SIZE_GroupName}"));
            }

            if (configurationGroupModel.GroupName == null)
            {
                result.Add(new ReturnErrorItem("GroupName", "GroupName is required "));
            }

            return result.Count > 0 ? result : null;
        }

