        public async Task CreateOrUpdateConfigurationGroupDependentsAsync(ConfigurationGroupModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<ConfigurationGroupXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<ConfigurationGroupXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetConfigurationGroupXYZZYXsByConfigurationGroupIdAsync(item.ConfigurationGroupId);
            if (dbExistingXYZZYX.Result != null && dbExistingConfigurationGroup.TotalRows > 0)
            {
                var dbExistingConfigurationGroupIds = dbExistingConfigurationGroup.Result.SelectToList(x => x.ConfigurationGroupXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingConfigurationGroupIds.Contains(x.ConfigurationGroupXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteConfigurationGroupXYZZYXByIdAsync(x.ConfigurationGroupXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingConfigurationGroupIds.Contains(x.ConfigurationGroupXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.ConfigurationGroupId = item.ConfigurationGroupId;
                    var mappedItem = objectMapperService.ConfigurationGroupXYZZYXModelToConfigurationGroupXYZZYXUpdateModel(x);
                    var result = await UpdateConfigurationGroupXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.ConfigurationGroupId = item.ConfigurationGroupId;
                var result = await CreateConfigurationGroupXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

