        public async Task<ReturnModel<bool>> AssociateXYZZYXWithConfigurationGroupAsync(ConfigurationGroupXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsConfigurationGroupWithConfigurationGroupAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ConfigurationGroup association is invalid", errorLst);
                }

                if (await systemRepository.DoesConfigurationGroupWithXYZZYXAssociationExistsAsync(model.ConfigurationGroupId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ConfigurationGroup is already associated with the ConfigurationGroup", new { model.ConfigurationGroupId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateConfigurationGroupWithXYZZYXAsync(model.ConfigurationGroupId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate ConfigurationGroup with XYZZYX", new { model.ConfigurationGroupId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating ConfigurationGroup with XYZZYX", new { model.ConfigurationGroupId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithConfigurationGroupAsync(ConfigurationGroupXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsConfigurationGroupWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ConfigurationGroup association is not valid", errorLst);
                }

                if (!await systemRepository.DoesConfigurationGroupWithXYZZYXAssociationExistsAsync(model.ConfigurationGroupId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ConfigurationGroup is not associated with the ConfigurationGroup", new { model.ConfigurationGroupId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateConfigurationGroupWithConfigurationGroupAsync(model.ConfigurationGroupId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related ConfigurationGroup with the ConfigurationGroup", new { model.ConfigurationGroupId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related ConfigurationGroup with the ConfigurationGroup", new { model.ConfigurationGroupId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsConfigurationGroupWithXYZZYXAssociationValidAsync(ConfigurationGroupXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.ConfigurationGroupId == 0)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationGroup is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related ConfigurationGroup  is not valid"));
                return result;
            }

            var entity = await GetConfigurationGroupForWriteByIdAsync(model.ConfigurationGroupId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationGroup information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationGroups does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

