        public async Task<ReturnModel<ConfigurationItemModel>> CreateConfigurationItemAsync(ConfigurationItemCreateModel configurationItem)
        {
            try
            {
                if (configurationItem == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to create ConfigurationItem", new ReturnErrorItem("", "ConfigurationItem information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(configurationItem.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ConfigurationItemModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(configurationItem.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ConfigurationItemModel>(movieModel);
                //}

                var errorList = await IsConfigurationItemModelValidForCreateAsync(configurationItem);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to create configurationItem", errorList);
                }

                configurationItem.IsDeleted = false;

                var item = objectMapperService.ConfigurationItemCreateModelToConfigurationItem(configurationItem);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateConfigurationItemAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create configurationItem");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ConfigurationItemCreatedAsync(item.ConfigurationItemId);

                var view = await systemRepository.GetConfigurationItemViewByIdAsync(item.ConfigurationItemId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to find the configurationItem", new { item.ConfigurationItemId });
                }

                return this.ConvertToItem(view, objectMapperService.ConfigurationItemViewToConfigurationItemModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<ConfigurationItemModel>($"Unexpected error when creating ConfigurationItem", new { configurationItem?.ConfigurationItemId }, ex);
            }
        }

        public async Task<ReturnModel<ConfigurationItemModel>> UpdateConfigurationItemAsync(ConfigurationItemUpdateModel configurationItem)
        {
            try
            {
                if (configurationItem == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to update ConfigurationItem", new ReturnErrorItem("", "ConfigurationItem information is not valid"));
                }

                var existingConfigurationItemModel = await GetConfigurationItemByIdForWriteAsync(configurationItem.ConfigurationItemId);
                if (!existingConfigurationItemModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>(existingConfigurationItemModel);
                }

                configurationItem.CreatedByUserId = existingConfigurationItemModel.Model.CreatedByUserId;
                configurationItem.CreatedDate = existingConfigurationItemModel.Model.CreatedDate;
                configurationItem.IsDeleted = existingConfigurationItemModel.Model.IsDeleted;

                var errorList = await IsConfigurationItemModelValidForUpdateAsync(configurationItem);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to update configurationItem", errorList);
                }

                var item = objectMapperService.ConfigurationItemUpdateModelToConfigurationItem(configurationItem);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateConfigurationItemAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update configurationItem");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ConfigurationItemUpdatedAsync(configurationItem.ConfigurationItemId, existingConfigurationItemModel.Model, item);

                var view = await systemRepository.GetConfigurationItemViewByIdAsync(configurationItem.ConfigurationItemId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unable to find the configurationItem", new { configurationItem.ConfigurationItemId });
                }

                return this.ConvertToItem(view, objectMapperService.ConfigurationItemViewToConfigurationItemModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<ConfigurationItemModel>($"Unexpected error when updating ConfigurationItem", new { configurationItem?.ConfigurationItemId }, ex);
            }
        }

