        }

        public async Task<List<ReturnErrorItem>> IsConfigurationItemModelValidForAllAsync(bool isCreate, ConfigurationItemUpdateModel configurationItemModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (configurationItemModel.ConfigurationItemId > 0)
                {
                    result.Add(new ReturnErrorItem("", "ConfigurationItem Identifier is not valid"));
                }
            }
            else
            {
                if (configurationItemModel.ConfigurationItemId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "ConfigurationItem Unique Identifier is not valid"));
                }
            }

            if (!await systemRepository.DoesConfigurationGroupByIdExistsAsync(configurationItemModel.ConfigurationGroupId))
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the ConfigurationGroup Information"));
                return result;
            }

            if (!ValidationUtils.IsLongValid(configurationItemModel.ConfigurationGroupId))
            {
                result.Add(new ReturnErrorItem("ConfigurationGroupId", "ConfigurationGroup cannot be empty"));
            }

            if (configurationItemModel.Key != null && configurationItemModel.Key.Length > ConfigurationItemModel.COLUMN_SIZE_Key)
            {
                result.Add(new ReturnErrorItem("Key", $"Key size should not exceed {ConfigurationItemModel.COLUMN_SIZE_Key}"));
            }

            if (configurationItemModel.Key == null)
            {
                result.Add(new ReturnErrorItem("Key", "Key is required "));
            }

            if (configurationItemModel.Value != null && configurationItemModel.Value.Length > ConfigurationItemModel.COLUMN_SIZE_Value)
            {
                result.Add(new ReturnErrorItem("Value", $"Value size should not exceed {ConfigurationItemModel.COLUMN_SIZE_Value}"));
            }

            if (configurationItemModel.Value == null)
            {
                result.Add(new ReturnErrorItem("Value", "Value is required "));
            }

            if (configurationItemModel.DefaultValue != null && configurationItemModel.DefaultValue.Length > ConfigurationItemModel.COLUMN_SIZE_DefaultValue)
            {
                result.Add(new ReturnErrorItem("DefaultValue", $"DefaultValue size should not exceed {ConfigurationItemModel.COLUMN_SIZE_DefaultValue}"));
            }

            return result.Count > 0 ? result : null;
        }

