        public async Task CreateOrUpdateConfigurationItemDependentsAsync(ConfigurationItemModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<ConfigurationItemXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<ConfigurationItemXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetConfigurationItemXYZZYXsByConfigurationItemIdAsync(item.ConfigurationItemId);
            if (dbExistingXYZZYX.Result != null && dbExistingConfigurationItem.TotalRows > 0)
            {
                var dbExistingConfigurationItemIds = dbExistingConfigurationItem.Result.SelectToList(x => x.ConfigurationItemXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingConfigurationItemIds.Contains(x.ConfigurationItemXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteConfigurationItemXYZZYXByIdAsync(x.ConfigurationItemXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingConfigurationItemIds.Contains(x.ConfigurationItemXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.ConfigurationItemId = item.ConfigurationItemId;
                    var mappedItem = objectMapperService.ConfigurationItemXYZZYXModelToConfigurationItemXYZZYXUpdateModel(x);
                    var result = await UpdateConfigurationItemXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.ConfigurationItemId = item.ConfigurationItemId;
                var result = await CreateConfigurationItemXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

