        public async Task<ReturnModel<bool>> AssociateXYZZYXWithConfigurationItemAsync(ConfigurationItemXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsConfigurationItemWithConfigurationItemAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ConfigurationItem association is invalid", errorLst);
                }

                if (await systemRepository.DoesConfigurationItemWithXYZZYXAssociationExistsAsync(model.ConfigurationItemId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ConfigurationItem is already associated with the ConfigurationItem", new { model.ConfigurationItemId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateConfigurationItemWithXYZZYXAsync(model.ConfigurationItemId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate ConfigurationItem with XYZZYX", new { model.ConfigurationItemId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating ConfigurationItem with XYZZYX", new { model.ConfigurationItemId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithConfigurationItemAsync(ConfigurationItemXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsConfigurationItemWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ConfigurationItem association is not valid", errorLst);
                }

                if (!await systemRepository.DoesConfigurationItemWithXYZZYXAssociationExistsAsync(model.ConfigurationItemId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ConfigurationItem is not associated with the ConfigurationItem", new { model.ConfigurationItemId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateConfigurationItemWithConfigurationItemAsync(model.ConfigurationItemId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related ConfigurationItem with the ConfigurationItem", new { model.ConfigurationItemId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related ConfigurationItem with the ConfigurationItem", new { model.ConfigurationItemId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsConfigurationItemWithXYZZYXAssociationValidAsync(ConfigurationItemXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.ConfigurationItemId == 0)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationItem is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related ConfigurationItem  is not valid"));
                return result;
            }

            var entity = await GetConfigurationItemForWriteByIdAsync(model.ConfigurationItemId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationItem information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "ConfigurationItems does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportConfigurationItemAsync(ConfigurationItemImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("ConfigurationItem Info is not provided");
                }

                if (model.ConfigurationItems == null || model.ConfigurationItems.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("ConfigurationItems Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.ConfigurationItems)
                {
                    var prod = await wipService.GetConfigurationItemByExternalIdentifierAsync(item.ConfigurationItemIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        ConfigurationItemCreateModel configurationItemCreateModel = new ConfigurationItemCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedConfigurationItem = await CreateConfigurationItemAsync(configurationItemCreateModel);
                        if (!newlyCreatedConfigurationItem.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedConfigurationItem.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedConfigurationItem.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        ConfigurationItemUpdateModel configurationItemUpdateModel = new ConfigurationItemUpdateModel
                        {
                        };

                        //update product
                        var updatedConfigurationItemModel = await wipService.UpdateConfigurationItemAsync(configurationItemUpdateModel);
                        if (!updatedConfigurationItemModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModel<ImportStatusModel>("Unexpected error occured when importing ConfigurationItem Info", ex);
            }
        }

        public async Task<ReturnListModel<ConfigurationItemExportModel>> ExportConfigurationItemAsync(ConfigurationItemExportParameter filter, bool isTest)
        {
            try
            {
                var configurationItemCount = await systemRepository.GetConfigurationItemCountAsync(filter);
                if (configurationItemCount == 0)
                {
                    return log.ErrorAndReturnListModel<ConfigurationItemExportModel>("No ConfigurationItem available for export.");
                }

                var itemsToReturn = new List<ConfigurationItemExportModel>();
                var numberOfLoops = (configurationItemCount / pageSize) + 1;
                for (var i = 0; i < numberOfLoops; ++i)
                {
