        public async Task<ReturnModel<EnumGroupModel>> GetEnumGroupByIdInternalAsync(bool forWrite, long enumGroupId)
        {
            try
            {
                var item = await systemRepository.GetEnumGroupViewByIdAsync(enumGroupId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to find the enumGroup", new { enumGroupId });
                }

                if (forWrite && await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>("You need to be a Super Admin to make this change");
                }

                return this.ConvertToItem(item, objectMapperService.EnumGroupViewToEnumGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<EnumGroupModel>($"Unexpected error when getting enumGroup", new { enumGroupId }, ex);
            }
        }

        public async Task<ReturnModel<EnumGroupModel>> CreateEnumGroupAsync(EnumGroupCreateModel enumGroup)
        {
            try
            {
                if (enumGroup == null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to create EnumGroup", new ReturnErrorItem("", "EnumGroup information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>("You need to be a Super Admin to make this change");
                }

                var errorList = IsEnumGroupModelValidForCreateAsync(enumGroup);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to create enumGroup", errorList);
                }

                enumGroup.IsDeleted = false;

                var item = objectMapperService.EnumGroupCreateModelToEnumGroup(enumGroup);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateEnumGroupAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create enumGroup");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.EnumGroupCreatedAsync(item.EnumGroupId);

                var view = await systemRepository.GetEnumGroupViewByIdAsync(item.EnumGroupId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to find the enumGroup", new { item.EnumGroupId });
                }

                return this.ConvertToItem(view, objectMapperService.EnumGroupViewToEnumGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<EnumGroupModel>($"Unexpected error when creating EnumGroup", new { enumGroup?.EnumGroupId }, ex);
            }
        }

        public async Task<ReturnModel<EnumGroupModel>> UpdateEnumGroupAsync(EnumGroupUpdateModel enumGroup)
        {
            try
            {
                if (enumGroup == null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to update EnumGroup", new ReturnErrorItem("", "EnumGroup information is not valid"));
                }

                var existingEnumGroupModel = await GetEnumGroupByIdForWriteAsync(enumGroup.EnumGroupId);
                if (!existingEnumGroupModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>(existingEnumGroupModel);
                }

                enumGroup.CreatedByUserId = existingEnumGroupModel.Model.CreatedByUserId;
                enumGroup.CreatedDate = existingEnumGroupModel.Model.CreatedDate;
                enumGroup.IsDeleted = existingEnumGroupModel.Model.IsDeleted;

                var errorList = IsEnumGroupModelValidForUpdateAsync(enumGroup);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to update enumGroup", errorList);
                }

                var item = objectMapperService.EnumGroupUpdateModelToEnumGroup(enumGroup);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateEnumGroupAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update enumGroup");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.EnumGroupUpdatedAsync(enumGroup.EnumGroupId, existingEnumGroupModel.Model, item);

                var view = await systemRepository.GetEnumGroupViewByIdAsync(enumGroup.EnumGroupId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<EnumGroupModel>($"Unable to find the enumGroup", new { enumGroup.EnumGroupId });
                }

                return this.ConvertToItem(view, objectMapperService.EnumGroupViewToEnumGroupModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<EnumGroupModel>($"Unexpected error when updating EnumGroup", new { enumGroup?.EnumGroupId }, ex);
            }
        }

