        public List<ReturnErrorItem> IsEnumGroupModelValidForAllAsync(bool isCreate, EnumGroupUpdateModel enumGroupModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (enumGroupModel.EnumGroupId > 0)
                {
                    result.Add(new ReturnErrorItem("", "EnumGroup Identifier is not valid"));
                }
            }
            else
            {
                if (enumGroupModel.EnumGroupId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "EnumGroup Unique Identifier is not valid"));
                }
            }

            if (enumGroupModel.EnumGroupName != null && enumGroupModel.EnumGroupName.Length > EnumGroupModel.COLUMN_SIZE_EnumGroupName)
            {
                result.Add(new ReturnErrorItem("EnumGroupName", $"EnumGroupName size should not exceed {EnumGroupModel.COLUMN_SIZE_EnumGroupName}"));
            }

            if (enumGroupModel.EnumGroupName == null)
            {
                result.Add(new ReturnErrorItem("EnumGroupName", "EnumGroupName is required "));
            }

            return result.Count > 0 ? result : null;
        }

