        public async Task<ReturnModel<bool>> AssociateXYZZYXWithEnumGroupAsync(EnumGroupXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsEnumGroupWithEnumGroupAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("EnumGroup association is invalid", errorLst);
                }

                if (await systemRepository.DoesEnumGroupWithXYZZYXAssociationExistsAsync(model.EnumGroupId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related EnumGroup is already associated with the EnumGroup", new { model.EnumGroupId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateEnumGroupWithXYZZYXAsync(model.EnumGroupId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate EnumGroup with XYZZYX", new { model.EnumGroupId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating EnumGroup with XYZZYX", new { model.EnumGroupId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithEnumGroupAsync(EnumGroupXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsEnumGroupWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("EnumGroup association is not valid", errorLst);
                }

                if (!await systemRepository.DoesEnumGroupWithXYZZYXAssociationExistsAsync(model.EnumGroupId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related EnumGroup is not associated with the EnumGroup", new { model.EnumGroupId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateEnumGroupWithEnumGroupAsync(model.EnumGroupId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related EnumGroup with the EnumGroup", new { model.EnumGroupId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related EnumGroup with the EnumGroup", new { model.EnumGroupId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsEnumGroupWithXYZZYXAssociationValidAsync(EnumGroupXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.EnumGroupId == 0)
            {
                result.Add(new ReturnErrorItem("", "EnumGroup is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related EnumGroup  is not valid"));
                return result;
            }

            var entity = await GetEnumGroupForWriteByIdAsync(model.EnumGroupId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "EnumGroup information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "EnumGroups does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportEnumGroupAsync(EnumGroupImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("EnumGroup Info is not provided");
                }

                if (model.EnumGroups == null || model.EnumGroups.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("EnumGroups Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.EnumGroups)
                {
                    var prod = await wipService.GetEnumGroupByExternalIdentifierAsync(item.EnumGroupIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        EnumGroupCreateModel enumGroupCreateModel = new EnumGroupCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedEnumGroup = await CreateEnumGroupAsync(enumGroupCreateModel);
                        if (!newlyCreatedEnumGroup.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedEnumGroup.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedEnumGroup.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        EnumGroupUpdateModel enumGroupUpdateModel = new EnumGroupUpdateModel
                        {
                        };

                        //update product
                        var updatedEnumGroupModel = await wipService.UpdateEnumGroupAsync(enumGroupUpdateModel);
                        if (!updatedEnumGroupModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModel<ImportStatusModel>("Unexpected error occured when importing EnumGroup Info", ex);
            }
        }

        public async Task<ReturnListModel<EnumGroupExportModel>> ExportEnumGroupAsync(EnumGroupExportParameter filter, bool isTest)
        {
            try
            {
                var enumGroupCount = await systemRepository.GetEnumGroupCountAsync(filter);
                if (enumGroupCount == 0)
                {
                    return log.ErrorAndReturnListModel<EnumGroupExportModel>("No EnumGroup available for export.");
                }

                var itemsToReturn = new List<EnumGroupExportModel>();
                var numberOfLoops = (enumGroupCount / pageSize) + 1;
                for (var i = 0; i < numberOfLoops; ++i)
                {
                    var dataResult = await wipService.GetUserViewListAsync(new EnumGroupSearchCriteria { Page = i, PageSize = pageSize, Keyword = filter.Keyword });
                    if (dataResult.IsSuccess)
                    {
