        public async Task<ReturnModel<EnumTypeModel>> CreateEnumTypeAsync(EnumTypeCreateModel enumType)
        {
            try
            {
                if (enumType == null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to create EnumType", new ReturnErrorItem("", "EnumType information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(enumType.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<EnumTypeModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(enumType.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<EnumTypeModel>(movieModel);
                //}

                var errorList = await IsEnumTypeModelValidForCreateAsync(enumType);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to create enumType", errorList);
                }

                enumType.IsDeleted = false;

                var item = objectMapperService.EnumTypeCreateModelToEnumType(enumType);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateEnumTypeAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create enumType");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.EnumTypeCreatedAsync(item.EnumTypeId);

                var view = await systemRepository.GetEnumTypeViewByIdAsync(item.EnumTypeId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to find the enumType", new { item.EnumTypeId });
                }

                return this.ConvertToItem(view, objectMapperService.EnumTypeViewToEnumTypeModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<EnumTypeModel>($"Unexpected error when creating EnumType", new { enumType?.EnumTypeId }, ex);
            }
        }

        public async Task<ReturnModel<EnumTypeModel>> UpdateEnumTypeAsync(EnumTypeUpdateModel enumType)
        {
            try
            {
                if (enumType == null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to update EnumType", new ReturnErrorItem("", "EnumType information is not valid"));
                }

                var existingEnumTypeModel = await GetEnumTypeByIdForWriteAsync(enumType.EnumTypeId);
                if (!existingEnumTypeModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>(existingEnumTypeModel);
                }

                enumType.CreatedByUserId = existingEnumTypeModel.Model.CreatedByUserId;
                enumType.CreatedDate = existingEnumTypeModel.Model.CreatedDate;
                enumType.IsDeleted = existingEnumTypeModel.Model.IsDeleted;

                var errorList = await IsEnumTypeModelValidForUpdateAsync(enumType);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to update enumType", errorList);
                }

                var item = objectMapperService.EnumTypeUpdateModelToEnumType(enumType);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateEnumTypeAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update enumType");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.EnumTypeUpdatedAsync(enumType.EnumTypeId, existingEnumTypeModel.Model, item);

                var view = await systemRepository.GetEnumTypeViewByIdAsync(enumType.EnumTypeId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<EnumTypeModel>($"Unable to find the enumType", new { enumType.EnumTypeId });
                }

                return this.ConvertToItem(view, objectMapperService.EnumTypeViewToEnumTypeModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<EnumTypeModel>($"Unexpected error when updating EnumType", new { enumType?.EnumTypeId }, ex);
            }
        }

