        public async Task<List<ReturnErrorItem>> IsEnumTypeModelValidForAllAsync(bool isCreate, EnumTypeUpdateModel enumTypeModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsEnumTypeNameAlreadyExistsForOtherEnumTypeAsync(enumTypeModel.EnumTypeName))
                {
                    result.Add(new ReturnErrorItem("", "Another EnumType already exists"));
                }

                if (enumTypeModel.EnumTypeId > 0)
                {
                    result.Add(new ReturnErrorItem("", "EnumType Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsEnumTypeNameAlreadyExistsForOtherEnumTypeAsync(enumTypeModel.EnumTypeId, enumTypeModel.EnumTypeName))
                {
                    result.Add(new ReturnErrorItem("", "Another EnumType already exists"));
                }

                if (enumTypeModel.EnumTypeId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "EnumType Unique Identifier is not valid"));
                }
            }

            if (!await systemRepository.DoesEnumGroupByIdExistsAsync(enumTypeModel.EnumGroupId))
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the EnumGroup Information"));
                return result;
            }

            if (!ValidationUtils.IsLongValid(enumTypeModel.EnumGroupId))
            {
                result.Add(new ReturnErrorItem("EnumGroupId", "EnumGroup cannot be empty"));
            }

            if (enumTypeModel.EnumTypeName != null && enumTypeModel.EnumTypeName.Length > EnumTypeModel.COLUMN_SIZE_EnumTypeName)
            {
                result.Add(new ReturnErrorItem("EnumTypeName", $"EnumTypeName size should not exceed {EnumTypeModel.COLUMN_SIZE_EnumTypeName}"));
            }

            if (enumTypeModel.EnumTypeName == null)
            {
                result.Add(new ReturnErrorItem("EnumTypeName", "EnumTypeName is required "));
            }

            return result.Count > 0 ? result : null;
        }

