        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<EnumTypeXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<EnumTypeXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetEnumTypeXYZZYXsByEnumTypeIdAsync(item.EnumTypeId);
            if (dbExistingXYZZYX.Result != null && dbExistingEnumType.TotalRows > 0)
            {
                var dbExistingEnumTypeIds = dbExistingEnumType.Result.SelectToList(x => x.EnumTypeXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingEnumTypeIds.Contains(x.EnumTypeXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteEnumTypeXYZZYXByIdAsync(x.EnumTypeXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingEnumTypeIds.Contains(x.EnumTypeXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.EnumTypeId = item.EnumTypeId;
