            foreach (var x in item.NewXYZZYXs)
            {
                x.EnumTypeId = item.EnumTypeId;
                var result = await CreateEnumTypeXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

