        public async Task<ReturnModel<bool>> AssociateXYZZYXWithEnumTypeAsync(EnumTypeXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsEnumTypeWithEnumTypeAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("EnumType association is invalid", errorLst);
                }

                if (await systemRepository.DoesEnumTypeWithXYZZYXAssociationExistsAsync(model.EnumTypeId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related EnumType is already associated with the EnumType", new { model.EnumTypeId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateEnumTypeWithXYZZYXAsync(model.EnumTypeId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate EnumType with XYZZYX", new { model.EnumTypeId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating EnumType with XYZZYX", new { model.EnumTypeId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithEnumTypeAsync(EnumTypeXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsEnumTypeWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("EnumType association is not valid", errorLst);
                }

                if (!await systemRepository.DoesEnumTypeWithXYZZYXAssociationExistsAsync(model.EnumTypeId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related EnumType is not associated with the EnumType", new { model.EnumTypeId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateEnumTypeWithEnumTypeAsync(model.EnumTypeId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related EnumType with the EnumType", new { model.EnumTypeId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related EnumType with the EnumType", new { model.EnumTypeId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsEnumTypeWithXYZZYXAssociationValidAsync(EnumTypeXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.EnumTypeId == 0)
            {
                result.Add(new ReturnErrorItem("", "EnumType is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related EnumType  is not valid"));
                return result;
            }

            var entity = await GetEnumTypeForWriteByIdAsync(model.EnumTypeId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "EnumType information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "EnumTypes does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportEnumTypeAsync(EnumTypeImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("EnumType Info is not provided");
                }

                if (model.EnumTypes == null || model.EnumTypes.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("EnumTypes Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.EnumTypes)
                {
                    var prod = await wipService.GetEnumTypeByExternalIdentifierAsync(item.EnumTypeIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        EnumTypeCreateModel enumTypeCreateModel = new EnumTypeCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedEnumType = await CreateEnumTypeAsync(enumTypeCreateModel);
                        if (!newlyCreatedEnumType.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedEnumType.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedEnumType.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        EnumTypeUpdateModel enumTypeUpdateModel = new EnumTypeUpdateModel
                        {
                        };

                        //update product
                        var updatedEnumTypeModel = await wipService.UpdateEnumTypeAsync(enumTypeUpdateModel);
                        if (!updatedEnumTypeModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
