        public Task<ReturnModel<JobModel>> GetJobByIdForReadAsync(long jobId)
        {
            return GetJobByIdInternalAsync(forWrite: false, jobId);
        }

        public Task<ReturnModel<JobModel>> GetJobByIdForWriteAsync(long jobId)
        {
            return GetJobByIdInternalAsync(forWrite: true, jobId);
        }

        public async Task<ReturnModel<JobModel>> GetJobByIdInternalAsync(bool forWrite, long jobId)
        {
            try
            {
                var item = await systemRepository.GetJobViewByIdAsync(jobId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to find the job", new { jobId });
                }

                if (forWrite && await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobModel>("You need to be a Super Admin to make this change");
                }

                return this.ConvertToItem(item, objectMapperService.JobViewToJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobModel>($"Unexpected error when getting job", new { jobId }, ex);
            }
        }

        public async Task<ReturnModel<JobModel>> CreateJobAsync(JobCreateModel job)
        {
            try
            {
                if (job == null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to create Job", new ReturnErrorItem("", "Job information is not valid"));
                }

                //var companyModel = await GetCompanyForReadById(job.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(job.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobModel>(movieModel);
                //}

                var errorList = await IsJobModelValidForCreateAsync(job);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to create job", errorList);
                }

                job.IsDeleted = false;

                var item = objectMapperService.JobCreateModelToJob(job);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create job");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobCreatedAsync(item.JobId);

                var view = await systemRepository.GetJobViewByIdAsync(item.JobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to find the job", new { item.JobId });
                }

                return this.ConvertToItem(view, objectMapperService.JobViewToJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobModel>($"Unexpected error when creating Job", new { job?.JobId }, ex);
            }
        }

        public async Task<ReturnModel<JobModel>> UpdateJobAsync(JobUpdateModel job)
        {
            try
            {
                if (job == null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to update Job", new ReturnErrorItem("", "Job information is not valid"));
                }

                var existingJobModel = await GetJobByIdForWriteAsync(job.JobId);
                if (!existingJobModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobModel>(existingJobModel);
                }

                job.CreatedByUserId = existingJobModel.Model.CreatedByUserId;
                job.CreatedDate = existingJobModel.Model.CreatedDate;
                job.IsDeleted = existingJobModel.Model.IsDeleted;

                var errorList = await IsJobModelValidForUpdateAsync(job);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to update job", errorList);
                }

                var item = objectMapperService.JobUpdateModelToJob(job);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update job");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobUpdatedAsync(job.JobId, existingJobModel.Model, item);

                var view = await systemRepository.GetJobViewByIdAsync(job.JobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobModel>($"Unable to find the job", new { job.JobId });
                }

                return this.ConvertToItem(view, objectMapperService.JobViewToJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobModel>($"Unexpected error when updating Job", new { job?.JobId }, ex);
            }
        }

