        public Task<List<ReturnErrorItem>> IsJobModelValidForCreateAsync(JobUpdateModel jobModel)
        {
            return IsJobModelValidForAllAsync(true, jobModel);
        }

        public Task<List<ReturnErrorItem>> IsJobModelValidForUpdateAsync(JobUpdateModel jobModel)
        {
            return IsJobModelValidForAllAsync(false, jobModel);
        }

        public async Task<List<ReturnErrorItem>> IsJobModelValidForAllAsync(bool isCreate, JobUpdateModel jobModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (jobModel.JobId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Job Identifier is not valid"));
                }
            }
            else
            {
                if (jobModel.JobId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Job Unique Identifier is not valid"));
                }
            }

            if (await systemRepository.GetJobTemplateByIdAsync(jobModel.JobTemplateId) == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the JobTemplate Information"));
                return result;
            }

            if (jobModel.SubmittedByUserId > 0)
            {
                var submittedByUserItem = await companyRepository.GetUserViewByIdAsync(jobModel.SubmittedByUserId ?? 0);
                if (submittedByUserItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the SubmittedByUser Information"));
                    return result;
                }
            }

            if (jobModel.PredefinedJobTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedJobTypeId", "PredefinedJobTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedJobTypes, long>(jobModel.PredefinedJobTypeId ?? 0))
            {
                result.Add(new ReturnErrorItem("PredefinedJobTypeId", "Job Type is not valid"));
            }

            if (!ValidationUtils.IsLongValid(jobModel.JobTemplateId))
            {
                result.Add(new ReturnErrorItem("JobTemplateId", "JobTemplate cannot be empty"));
            }

            if (jobModel.CompletedDate != null && !DateUtils.IsValidDate(jobModel.CompletedDate.Value))
            {
                result.Add(new ReturnErrorItem("CompletedDate", $"CompletedDate is not a valid date"));
            }

            if (!DateUtils.IsValidDate(jobModel.SubmittedDate))
            {
                result.Add(new ReturnErrorItem("SubmittedDate", $"SubmittedDate is not a valid date"));
            }

            if (jobModel.Message != null && jobModel.Message.Length > JobModel.COLUMN_SIZE_Message)
            {
                result.Add(new ReturnErrorItem("Message", $"Message size should not exceed {JobModel.COLUMN_SIZE_Message}"));
            }

            if (jobModel.PredefinedJobStatusTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedJobStatusTypeId", "PredefinedJobStatusTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedJobStatusTypes, long>(jobModel.PredefinedJobStatusTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedCompanyTypeId", "CompanyType is not valid"));
            }

            if (jobModel.ExecutableFolder != null && jobModel.ExecutableFolder.Length > JobModel.COLUMN_SIZE_ExecutableFolder)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", $"ExecutableFolder size should not exceed {JobModel.COLUMN_SIZE_ExecutableFolder}"));
            }

            if (jobModel.ExecutableFolder == null)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", "ExecutableFolder is required "));
            }

            if (jobModel.ExecutableName != null && jobModel.ExecutableName.Length > JobModel.COLUMN_SIZE_ExecutableName)
            {
                result.Add(new ReturnErrorItem("ExecutableName", $"ExecutableName size should not exceed {JobModel.COLUMN_SIZE_ExecutableName}"));
            }

            if (jobModel.ExecutableName == null)
            {
                result.Add(new ReturnErrorItem("ExecutableName", "ExecutableName is required "));
            }

            if (jobModel.ExecutableParameter != null && jobModel.ExecutableParameter.Length > JobModel.COLUMN_SIZE_ExecutableParameter)
            {
                result.Add(new ReturnErrorItem("ExecutableParameter", $"ExecutableParameter size should not exceed {JobModel.COLUMN_SIZE_ExecutableParameter}"));
            }

            if (jobModel.SerializedJobParameter != null && jobModel.SerializedJobParameter.Length > JobModel.COLUMN_SIZE_SerializedJobParameter)
            {
                result.Add(new ReturnErrorItem("SerializedJobParameter", $"SerializedJobParameter size should not exceed {JobModel.COLUMN_SIZE_SerializedJobParameter}"));
            }

            if (jobModel.ReportTemplateFile != null && jobModel.ReportTemplateFile.Length > JobModel.COLUMN_SIZE_ReportTemplateFile)
            {
                result.Add(new ReturnErrorItem("ReportTemplateFile", $"ReportTemplateFile size should not exceed {JobModel.COLUMN_SIZE_ReportTemplateFile}"));
            }

            if (jobModel.CustomExportName != null && jobModel.CustomExportName.Length > JobModel.COLUMN_SIZE_CustomExportName)
            {
                result.Add(new ReturnErrorItem("CustomExportName", $"CustomExportName size should not exceed {JobModel.COLUMN_SIZE_CustomExportName}"));
            }

            if (jobModel.PickupDate != null && !DateUtils.IsValidDate(jobModel.PickupDate.Value))
            {
                result.Add(new ReturnErrorItem("PickupDate", $"PickupDate is not a valid date"));
            }

            if (jobModel.JobName != null && jobModel.JobName.Length > JobModel.COLUMN_SIZE_JobName)
            {
                result.Add(new ReturnErrorItem("JobName", $"JobName size should not exceed {JobModel.COLUMN_SIZE_JobName}"));
            }

            if (jobModel.ExecutionAppName != null && jobModel.ExecutionAppName.Length > JobModel.COLUMN_SIZE_ExecutionAppName)
            {
                result.Add(new ReturnErrorItem("ExecutionAppName", $"ExecutionAppName size should not exceed {JobModel.COLUMN_SIZE_ExecutionAppName}"));
            }

            if (jobModel.ExecutionAppId != null && jobModel.ExecutionAppId.Length > JobModel.COLUMN_SIZE_ExecutionAppId)
            {
                result.Add(new ReturnErrorItem("ExecutionAppId", $"ExecutionAppId size should not exceed {JobModel.COLUMN_SIZE_ExecutionAppId}"));
            }

            if (jobModel.ExecutionHostName != null && jobModel.ExecutionHostName.Length > JobModel.COLUMN_SIZE_ExecutionHostName)
            {
                result.Add(new ReturnErrorItem("ExecutionHostName", $"ExecutionHostName size should not exceed {JobModel.COLUMN_SIZE_ExecutionHostName}"));
            }

            return result.Count > 0 ? result : null;
        }

