        public async Task CreateOrUpdateJobDependentsAsync(JobModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobXYZZYXsByJobIdAsync(item.JobId);
            if (dbExistingXYZZYX.Result != null && dbExistingJob.TotalRows > 0)
            {
                var dbExistingJobIds = dbExistingJob.Result.SelectToList(x => x.JobXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobIds.Contains(x.JobXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobXYZZYXByIdAsync(x.JobXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobIds.Contains(x.JobXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.JobId = item.JobId;
                    var mappedItem = objectMapperService.JobXYZZYXModelToJobXYZZYXUpdateModel(x);
                    var result = await UpdateJobXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.JobId = item.JobId;
                var result = await CreateJobXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

