        public async Task<ReturnModel<bool>> AssociateXYZZYXWithJobAsync(JobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobWithJobAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Job association is invalid", errorLst);
                }

                if (await systemRepository.DoesJobWithXYZZYXAssociationExistsAsync(model.JobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Job is already associated with the Job", new { model.JobId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateJobWithXYZZYXAsync(model.JobId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Job with XYZZYX", new { model.JobId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Job with XYZZYX", new { model.JobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithJobAsync(JobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Job association is not valid", errorLst);
                }

                if (!await systemRepository.DoesJobWithXYZZYXAssociationExistsAsync(model.JobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Job is not associated with the Job", new { model.JobId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateJobWithJobAsync(model.JobId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Job with the Job", new { model.JobId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Job with the Job", new { model.JobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsJobWithXYZZYXAssociationValidAsync(JobXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.JobId == 0)
            {
                result.Add(new ReturnErrorItem("", "Job is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Job  is not valid"));
                return result;
            }

            var entity = await GetJobForWriteByIdAsync(model.JobId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Job information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Jobs does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportJobAsync(JobImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Job Info is not provided");
                }

                if (model.Jobs == null || model.Jobs.Count == 0)
