                            var errorStr = string.Empty;
                            if (newlyCreatedJob.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedJob.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
