        public async Task<ReturnModel<JobAttachmentModel>> CreateJobAttachmentAsync(JobAttachmentCreateModel jobAttachment)
        {
            try
            {
                if (jobAttachment == null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to create JobAttachment", new ReturnErrorItem("", "JobAttachment information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(jobAttachment.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobAttachmentModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(jobAttachment.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobAttachmentModel>(movieModel);
                //}

                var errorList = await IsJobAttachmentModelValidForCreateAsync(jobAttachment);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to create jobAttachment", errorList);
                }

                jobAttachment.IsDeleted = false;

                var item = objectMapperService.JobAttachmentCreateModelToJobAttachment(jobAttachment);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobAttachmentAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create jobAttachment");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobAttachmentCreatedAsync(item.JobAttachmentId);

                var view = await systemRepository.GetJobAttachmentViewByIdAsync(item.JobAttachmentId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to find the jobAttachment", new { item.JobAttachmentId });
                }

                return this.ConvertToItem(view, objectMapperService.JobAttachmentViewToJobAttachmentModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobAttachmentModel>($"Unexpected error when creating JobAttachment", new { jobAttachment?.JobAttachmentId }, ex);
            }
        }

        public async Task<ReturnModel<JobAttachmentModel>> UpdateJobAttachmentAsync(JobAttachmentUpdateModel jobAttachment)
        {
            try
            {
                if (jobAttachment == null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to update JobAttachment", new ReturnErrorItem("", "JobAttachment information is not valid"));
                }

                var existingJobAttachmentModel = await GetJobAttachmentByIdForWriteAsync(jobAttachment.JobAttachmentId);
                if (!existingJobAttachmentModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>(existingJobAttachmentModel);
                }

                jobAttachment.CreatedByUserId = existingJobAttachmentModel.Model.CreatedByUserId;
                jobAttachment.CreatedDate = existingJobAttachmentModel.Model.CreatedDate;
                jobAttachment.IsDeleted = existingJobAttachmentModel.Model.IsDeleted;

                var errorList = await IsJobAttachmentModelValidForUpdateAsync(jobAttachment);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to update jobAttachment", errorList);
                }

                var item = objectMapperService.JobAttachmentUpdateModelToJobAttachment(jobAttachment);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobAttachmentAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update jobAttachment");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobAttachmentUpdatedAsync(jobAttachment.JobAttachmentId, existingJobAttachmentModel.Model, item);

                var view = await systemRepository.GetJobAttachmentViewByIdAsync(jobAttachment.JobAttachmentId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobAttachmentModel>($"Unable to find the jobAttachment", new { jobAttachment.JobAttachmentId });
                }

                return this.ConvertToItem(view, objectMapperService.JobAttachmentViewToJobAttachmentModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobAttachmentModel>($"Unexpected error when updating JobAttachment", new { jobAttachment?.JobAttachmentId }, ex);
            }
        }

