        public async Task CreateOrUpdateJobAttachmentDependentsAsync(JobAttachmentModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobAttachmentXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobAttachmentXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobAttachmentXYZZYXsByJobAttachmentIdAsync(item.JobAttachmentId);
            if (dbExistingXYZZYX.Result != null && dbExistingJobAttachment.TotalRows > 0)
            {
                var dbExistingJobAttachmentIds = dbExistingJobAttachment.Result.SelectToList(x => x.JobAttachmentXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobAttachmentIds.Contains(x.JobAttachmentXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobAttachmentXYZZYXByIdAsync(x.JobAttachmentXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobAttachmentIds.Contains(x.JobAttachmentXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.JobAttachmentId = item.JobAttachmentId;
                    var mappedItem = objectMapperService.JobAttachmentXYZZYXModelToJobAttachmentXYZZYXUpdateModel(x);
                    var result = await UpdateJobAttachmentXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.JobAttachmentId = item.JobAttachmentId;
                var result = await CreateJobAttachmentXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

