        public async Task<ReturnModel<bool>> AssociateXYZZYXWithJobAttachmentAsync(JobAttachmentXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobAttachmentWithJobAttachmentAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobAttachment association is invalid", errorLst);
                }

                if (await systemRepository.DoesJobAttachmentWithXYZZYXAssociationExistsAsync(model.JobAttachmentId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobAttachment is already associated with the JobAttachment", new { model.JobAttachmentId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateJobAttachmentWithXYZZYXAsync(model.JobAttachmentId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate JobAttachment with XYZZYX", new { model.JobAttachmentId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating JobAttachment with XYZZYX", new { model.JobAttachmentId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithJobAttachmentAsync(JobAttachmentXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobAttachmentWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobAttachment association is not valid", errorLst);
                }

                if (!await systemRepository.DoesJobAttachmentWithXYZZYXAssociationExistsAsync(model.JobAttachmentId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobAttachment is not associated with the JobAttachment", new { model.JobAttachmentId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateJobAttachmentWithJobAttachmentAsync(model.JobAttachmentId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related JobAttachment with the JobAttachment", new { model.JobAttachmentId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related JobAttachment with the JobAttachment", new { model.JobAttachmentId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsJobAttachmentWithXYZZYXAssociationValidAsync(JobAttachmentXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.JobAttachmentId == 0)
            {
                result.Add(new ReturnErrorItem("", "JobAttachment is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related JobAttachment  is not valid"));
                return result;
            }

            var entity = await GetJobAttachmentForWriteByIdAsync(model.JobAttachmentId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "JobAttachment information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "JobAttachments does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

