        public async Task<ReturnModel<JobNotificationEmailModel>> CreateJobNotificationEmailAsync(JobNotificationEmailCreateModel jobNotificationEmail)
        {
            try
            {
                if (jobNotificationEmail == null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to create JobNotificationEmail", new ReturnErrorItem("", "JobNotificationEmail information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(jobNotificationEmail.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobNotificationEmailModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(jobNotificationEmail.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobNotificationEmailModel>(movieModel);
                //}

                var errorList = await IsJobNotificationEmailModelValidForCreateAsync(jobNotificationEmail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to create jobNotificationEmail", errorList);
                }

                jobNotificationEmail.IsDeleted = false;

                var item = objectMapperService.JobNotificationEmailCreateModelToJobNotificationEmail(jobNotificationEmail);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobNotificationEmailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create jobNotificationEmail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobNotificationEmailCreatedAsync(item.JobNotificationEmailId);

                var view = await systemRepository.GetJobNotificationEmailViewByIdAsync(item.JobNotificationEmailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to find the jobNotificationEmail", new { item.JobNotificationEmailId });
                }

                return this.ConvertToItem(view, objectMapperService.JobNotificationEmailViewToJobNotificationEmailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobNotificationEmailModel>($"Unexpected error when creating JobNotificationEmail", new { jobNotificationEmail?.JobNotificationEmailId }, ex);
            }
        }

        public async Task<ReturnModel<JobNotificationEmailModel>> UpdateJobNotificationEmailAsync(JobNotificationEmailUpdateModel jobNotificationEmail)
        {
            try
            {
                if (jobNotificationEmail == null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to update JobNotificationEmail", new ReturnErrorItem("", "JobNotificationEmail information is not valid"));
                }

                var existingJobNotificationEmailModel = await GetJobNotificationEmailByIdForWriteAsync(jobNotificationEmail.JobNotificationEmailId);
                if (!existingJobNotificationEmailModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>(existingJobNotificationEmailModel);
                }

                jobNotificationEmail.CreatedByUserId = existingJobNotificationEmailModel.Model.CreatedByUserId;
                jobNotificationEmail.CreatedDate = existingJobNotificationEmailModel.Model.CreatedDate;
                jobNotificationEmail.IsDeleted = existingJobNotificationEmailModel.Model.IsDeleted;

                var errorList = await IsJobNotificationEmailModelValidForUpdateAsync(jobNotificationEmail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to update jobNotificationEmail", errorList);
                }

                var item = objectMapperService.JobNotificationEmailUpdateModelToJobNotificationEmail(jobNotificationEmail);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobNotificationEmailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update jobNotificationEmail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobNotificationEmailUpdatedAsync(jobNotificationEmail.JobNotificationEmailId, existingJobNotificationEmailModel.Model, item);

                var view = await systemRepository.GetJobNotificationEmailViewByIdAsync(jobNotificationEmail.JobNotificationEmailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unable to find the jobNotificationEmail", new { jobNotificationEmail.JobNotificationEmailId });
                }

                return this.ConvertToItem(view, objectMapperService.JobNotificationEmailViewToJobNotificationEmailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobNotificationEmailModel>($"Unexpected error when updating JobNotificationEmail", new { jobNotificationEmail?.JobNotificationEmailId }, ex);
            }
        }

