        public async Task CreateOrUpdateJobNotificationEmailDependentsAsync(JobNotificationEmailModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobNotificationEmailXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobNotificationEmailXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobNotificationEmailXYZZYXsByJobNotificationEmailIdAsync(item.JobNotificationEmailId);
            if (dbExistingXYZZYX.Result != null && dbExistingJobNotificationEmail.TotalRows > 0)
            {
                var dbExistingJobNotificationEmailIds = dbExistingJobNotificationEmail.Result.SelectToList(x => x.JobNotificationEmailXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobNotificationEmailIds.Contains(x.JobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobNotificationEmailXYZZYXByIdAsync(x.JobNotificationEmailXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobNotificationEmailIds.Contains(x.JobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.JobNotificationEmailId = item.JobNotificationEmailId;
                    var mappedItem = objectMapperService.JobNotificationEmailXYZZYXModelToJobNotificationEmailXYZZYXUpdateModel(x);
                    var result = await UpdateJobNotificationEmailXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.JobNotificationEmailId = item.JobNotificationEmailId;
                var result = await CreateJobNotificationEmailXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

