                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.DisableJobNotificationEmailByIdAsync(existingJobNotificationEmailModel.Model.JobNotificationEmailId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.JobNotificationEmailDisabledAsync(existingJobNotificationEmailModel.Model.JobNotificationEmailId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when deleting jobNotificationEmail",new { jobNotificationEmailId }, ex);
            }
        }


