        public async Task<ReturnModel<bool>> AssociateXYZZYXWithJobNotificationEmailAsync(JobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobNotificationEmailWithJobNotificationEmailAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobNotificationEmail association is invalid", errorLst);
                }

                if (await systemRepository.DoesJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.JobNotificationEmailId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobNotificationEmail is already associated with the JobNotificationEmail", new { model.JobNotificationEmailId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateJobNotificationEmailWithXYZZYXAsync(model.JobNotificationEmailId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate JobNotificationEmail with XYZZYX", new { model.JobNotificationEmailId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating JobNotificationEmail with XYZZYX", new { model.JobNotificationEmailId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithJobNotificationEmailAsync(JobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobNotificationEmailWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobNotificationEmail association is not valid", errorLst);
                }

                if (!await systemRepository.DoesJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.JobNotificationEmailId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobNotificationEmail is not associated with the JobNotificationEmail", new { model.JobNotificationEmailId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateJobNotificationEmailWithJobNotificationEmailAsync(model.JobNotificationEmailId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related JobNotificationEmail with the JobNotificationEmail", new { model.JobNotificationEmailId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related JobNotificationEmail with the JobNotificationEmail", new { model.JobNotificationEmailId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsJobNotificationEmailWithXYZZYXAssociationValidAsync(JobNotificationEmailXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.JobNotificationEmailId == 0)
            {
                result.Add(new ReturnErrorItem("", "JobNotificationEmail is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related JobNotificationEmail  is not valid"));
                return result;
            }

            var entity = await GetJobNotificationEmailForWriteByIdAsync(model.JobNotificationEmailId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "JobNotificationEmail information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "JobNotificationEmails does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

