        public async Task<ReturnModel<JobTemplateModel>> GetJobTemplateByIdInternalAsync(bool forWrite, long jobTemplateId)
        {
            try
            {
                var item = await systemRepository.GetJobTemplateViewByIdAsync(jobTemplateId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to find the jobTemplate", new { jobTemplateId });
                }

                if (forWrite && await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>("You need to be a Super Admin to make this change");
                }

                return this.ConvertToItem(item, objectMapperService.JobTemplateViewToJobTemplateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobTemplateModel>($"Unexpected error when getting jobTemplate", new { jobTemplateId }, ex);
            }
        }

        public async Task<ReturnModel<JobTemplateModel>> CreateJobTemplateAsync(JobTemplateCreateModel jobTemplate)
        {
            try
            {
                if (jobTemplate == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to create JobTemplate", new ReturnErrorItem("", "JobTemplate information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(jobTemplate.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(jobTemplate.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateModel>(movieModel);
                //}

                var errorList = await IsJobTemplateModelValidForCreateAsync(jobTemplate);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to create jobTemplate", errorList);
                }

                jobTemplate.IsDeleted = false;

                var item = objectMapperService.JobTemplateCreateModelToJobTemplate(jobTemplate);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobTemplateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create jobTemplate");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateCreatedAsync(item.JobTemplateId);

                var view = await systemRepository.GetJobTemplateViewByIdAsync(item.JobTemplateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to find the jobTemplate", new { item.JobTemplateId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateViewToJobTemplateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobTemplateModel>($"Unexpected error when creating JobTemplate ", new { jobTemplate?.JobTemplateId }, ex);
            }
        }

        public async Task<ReturnModel<JobTemplateModel>> UpdateJobTemplateAsync(JobTemplateUpdateModel jobTemplate)
        {
            try
            {
                if (jobTemplate == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to update JobTemplate", new ReturnErrorItem("", "JobTemplate information is not valid"));
                }

                var existingJobTemplateModel = await GetJobTemplateByIdForWriteAsync(jobTemplate.JobTemplateId);
                if (!existingJobTemplateModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>(existingJobTemplateModel);
                }

                jobTemplate.CreatedByUserId = existingJobTemplateModel.Model.CreatedByUserId;
                jobTemplate.CreatedDate = existingJobTemplateModel.Model.CreatedDate;
                jobTemplate.IsDeleted = existingJobTemplateModel.Model.IsDeleted;

                var errorList = await IsJobTemplateModelValidForUpdateAsync(jobTemplate);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to update jobTemplate", errorList);
                }

                var item = objectMapperService.JobTemplateUpdateModelToJobTemplate(jobTemplate);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobTemplateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update jobTemplate");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateUpdatedAsync(jobTemplate.JobTemplateId, existingJobTemplateModel.Model, item);

                var view = await systemRepository.GetJobTemplateViewByIdAsync(jobTemplate.JobTemplateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateModel>($"Unable to find the jobTemplate", new { jobTemplate.JobTemplateId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateViewToJobTemplateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobTemplateModel>($"Unexpected error when updating JobTemplate", new { jobTemplate?.JobTemplateId }, ex);
            }
        }

