            try
            {
                var view = await GetJobTemplateByIdForReadAsync(jobTemplateId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the JobTemplate", new { jobTemplateId });
                }

                var fileName = view.Model.SourceStoredFilePath;

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.TenantId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"JobTemplateFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.TenantId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for JobTemplate ", new { jobTemplateId }, ex);
            }
        }

        public async Task CreateOrUpdateJobTemplateDependentsAsync(JobTemplateModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobTemplateXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobTemplateXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobTemplateXYZZYXsByJobTemplateIdAsync(item.JobTemplateId);
            if (dbExistingXYZZYX.Result != null && dbExistingJobTemplate.TotalRows > 0)
            {
                var dbExistingJobTemplateIds = dbExistingJobTemplate.Result.SelectToList(x => x.JobTemplateXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobTemplateIds.Contains(x.JobTemplateXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobTemplateXYZZYXByIdAsync(x.JobTemplateXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobTemplateIds.Contains(x.JobTemplateXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.JobTemplateId = item.JobTemplateId;
                    var mappedItem = objectMapperService.JobTemplateXYZZYXModelToJobTemplateXYZZYXUpdateModel(x);
                    var result = await UpdateJobTemplateXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.JobTemplateId = item.JobTemplateId;
                var result = await CreateJobTemplateXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

