        public async Task<ReturnModel<bool>> AssociateXYZZYXWithJobTemplateAsync(JobTemplateXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobTemplateWithJobTemplateAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobTemplate association is invalid", errorLst);
                }

                if (await systemRepository.DoesJobTemplateWithXYZZYXAssociationExistsAsync(model.JobTemplateId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobTemplate is already associated with the JobTemplate", new { model.JobTemplateId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateJobTemplateWithXYZZYXAsync(model.JobTemplateId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate JobTemplate with XYZZYX", new { model.JobTemplateId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating JobTemplate with XYZZYX", new { model.JobTemplateId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithJobTemplateAsync(JobTemplateXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobTemplateWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobTemplate association is not valid", errorLst);
                }

                if (!await systemRepository.DoesJobTemplateWithXYZZYXAssociationExistsAsync(model.JobTemplateId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobTemplate is not associated with the JobTemplate", new { model.JobTemplateId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateJobTemplateWithJobTemplateAsync(model.JobTemplateId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related JobTemplate with the JobTemplate", new { model.JobTemplateId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related JobTemplate with the JobTemplate", new { model.JobTemplateId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsJobTemplateWithXYZZYXAssociationValidAsync(JobTemplateXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.JobTemplateId == 0)
            {
                result.Add(new ReturnErrorItem("", "JobTemplate is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related JobTemplate  is not valid"));
                return result;
            }

            var entity = await GetJobTemplateForWriteByIdAsync(model.JobTemplateId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "JobTemplate information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "JobTemplates does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

