                        }
                    }
                    else
                    {
                        JobTemplateUpdateModel jobTemplateUpdateModel = new JobTemplateUpdateModel
                        {
                        };

                        //update product
                        var updatedJobTemplateModel = await wipService.UpdateJobTemplateAsync(jobTemplateUpdateModel);
                        if (!updatedJobTemplateModel.IsSuccess)
