        public async Task<ReturnModel<JobTemplateCategoryModel>> CreateJobTemplateCategoryAsync(JobTemplateCategoryCreateModel jobTemplateCategory)
        {
            try
            {
                if (jobTemplateCategory == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to create JobTemplateCategory", new ReturnErrorItem("", "JobTemplateCategory information is not valid"));
                }

                //var companyModel = await GetCompanyForReadById(jobTemplateCategory.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateCategoryModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(jobTemplateCategory.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateCategoryModel>(movieModel);
                //}

                var errorList = await IsJobTemplateCategoryModelValidForCreateAsync(jobTemplateCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to create jobTemplateCategory", errorList);
                }

                jobTemplateCategory.IsDeleted = false;

                var item = objectMapperService.JobTemplateCategoryCreateModelToJobTemplateCategory(jobTemplateCategory);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobTemplateCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create jobTemplateCategory");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateCategoryCreatedAsync(item.JobTemplateCategoryId);

                var view = await systemRepository.GetJobTemplateCategoryViewByIdAsync(item.JobTemplateCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to find the jobTemplateCategory", new { item.JobTemplateCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateCategoryViewToJobTemplateCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobTemplateCategoryModel>($"Unexpected error when creating JobTemplateCategory", new { jobTemplateCategory?.JobTemplateCategoryId }, ex);
            }
        }

        public async Task<ReturnModel<JobTemplateCategoryModel>> UpdateJobTemplateCategoryAsync(JobTemplateCategoryUpdateModel jobTemplateCategory)
        {
            try
            {
                if (jobTemplateCategory == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to update JobTemplateCategory", new ReturnErrorItem("", "JobTemplateCategory information is not valid"));
                }

                var existingJobTemplateCategoryModel = await GetJobTemplateCategoryByIdForWriteAsync(jobTemplateCategory.JobTemplateCategoryId);
                if (!existingJobTemplateCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>(existingJobTemplateCategoryModel);
                }

                jobTemplateCategory.CreatedByUserId = existingJobTemplateCategoryModel.Model.CreatedByUserId;
                jobTemplateCategory.CreatedDate = existingJobTemplateCategoryModel.Model.CreatedDate;
                jobTemplateCategory.IsDeleted = existingJobTemplateCategoryModel.Model.IsDeleted;

                var errorList = await IsJobTemplateCategoryModelValidForUpdateAsync(jobTemplateCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to update jobTemplateCategory", errorList);
                }

                var item = objectMapperService.JobTemplateCategoryUpdateModelToJobTemplateCategory(jobTemplateCategory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobTemplateCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update jobTemplateCategory");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateCategoryUpdatedAsync(jobTemplateCategory.JobTemplateCategoryId, existingJobTemplateCategoryModel.Model, item);

                var view = await systemRepository.GetJobTemplateCategoryViewByIdAsync(jobTemplateCategory.JobTemplateCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unable to find the jobTemplateCategory", new { jobTemplateCategory.JobTemplateCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateCategoryViewToJobTemplateCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobTemplateCategoryModel>($"Unexpected error when updating JobTemplateCategory ", new { jobTemplateCategory?.JobTemplateCategoryId }, ex);
            }
        }

