        public async Task<ReturnModel<FileStreamModel>> GetJobTemplateCategoryFileAsync(long jobTemplateCategoryId)
        {
            try
            {
                var view = await GetJobTemplateCategoryByIdForReadAsync(jobTemplateCategoryId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the JobTemplateCategory", new { jobTemplateCategoryId });
                }

                var fileName = view.Model.SourceStoredFilePath;

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.TenantId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"JobTemplateCategoryFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.TenantId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for JobTemplateCategory ", new { jobTemplateCategoryId }, ex);
            }
        }

        public async Task CreateOrUpdateJobTemplateCategoryDependentsAsync(JobTemplateCategoryModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobTemplateCategoryXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobTemplateCategoryXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobTemplateCategoryXYZZYXsByJobTemplateCategoryIdAsync(item.JobTemplateCategoryId);
            if (dbExistingXYZZYX.Result != null && dbExistingJobTemplateCategory.TotalRows > 0)
            {
                var dbExistingJobTemplateCategoryIds = dbExistingJobTemplateCategory.Result.SelectToList(x => x.JobTemplateCategoryXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobTemplateCategoryIds.Contains(x.JobTemplateCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobTemplateCategoryXYZZYXByIdAsync(x.JobTemplateCategoryXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobTemplateCategoryIds.Contains(x.JobTemplateCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.JobTemplateCategoryId = item.JobTemplateCategoryId;
                    var mappedItem = objectMapperService.JobTemplateCategoryXYZZYXModelToJobTemplateCategoryXYZZYXUpdateModel(x);
                    var result = await UpdateJobTemplateCategoryXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.JobTemplateCategoryId = item.JobTemplateCategoryId;
                var result = await CreateJobTemplateCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

