        public async Task<ReturnModel<JobTemplateParameterModel>> CreateJobTemplateParameterAsync(JobTemplateParameterCreateModel jobTemplateParameter)
        {
            try
            {
                if (jobTemplateParameter == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to create JobTemplateParameter", new ReturnErrorItem("", "JobTemplateParameter information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(jobTemplateParameter.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateParameterModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(jobTemplateParameter.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<JobTemplateParameterModel>(movieModel);
                //}

                var errorList = await IsJobTemplateParameterModelValidForCreateAsync(jobTemplateParameter);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to create jobTemplateParameter", errorList);
                }

                jobTemplateParameter.IsDeleted = false;

                var item = objectMapperService.JobTemplateParameterCreateModelToJobTemplateParameter(jobTemplateParameter);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateJobTemplateParameterAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create jobTemplateParameter");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateParameterCreatedAsync(item.JobTemplateParameterId);

                var view = await systemRepository.GetJobTemplateParameterViewByIdAsync(item.JobTemplateParameterId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to find the jobTemplateParameter", new { item.JobTemplateParameterId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateParameterViewToJobTemplateParameterModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<JobTemplateParameterModel>($"Unexpected error when creating JobTemplateParameter", new { jobTemplateParameter?.JobTemplateParameterId }, ex);
            }
        }

        public async Task<ReturnModel<JobTemplateParameterModel>> UpdateJobTemplateParameterAsync(JobTemplateParameterUpdateModel jobTemplateParameter)
        {
            try
            {
                if (jobTemplateParameter == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to update JobTemplateParameter", new ReturnErrorItem("", "JobTemplateParameter information is not valid"));
                }

                var existingJobTemplateParameterModel = await GetJobTemplateParameterByIdForWriteAsync(jobTemplateParameter.JobTemplateParameterId);
                if (!existingJobTemplateParameterModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>(existingJobTemplateParameterModel);
                }

                jobTemplateParameter.CreatedByUserId = existingJobTemplateParameterModel.Model.CreatedByUserId;
                jobTemplateParameter.CreatedDate = existingJobTemplateParameterModel.Model.CreatedDate;
                jobTemplateParameter.IsDeleted = existingJobTemplateParameterModel.Model.IsDeleted;

                var errorList = await IsJobTemplateParameterModelValidForUpdateAsync(jobTemplateParameter);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to update jobTemplateParameter", errorList);
                }

                var item = objectMapperService.JobTemplateParameterUpdateModelToJobTemplateParameter(jobTemplateParameter);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateJobTemplateParameterAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update jobTemplateParameter");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.JobTemplateParameterUpdatedAsync(jobTemplateParameter.JobTemplateParameterId, existingJobTemplateParameterModel.Model, item);

                var view = await systemRepository.GetJobTemplateParameterViewByIdAsync(jobTemplateParameter.JobTemplateParameterId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unable to find the jobTemplateParameter", new { jobTemplateParameter.JobTemplateParameterId });
                }

                return this.ConvertToItem(view, objectMapperService.JobTemplateParameterViewToJobTemplateParameterModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<JobTemplateParameterModel>($"Unexpected error when updating JobTemplateParameter", new { jobTemplateParameter?.JobTemplateParameterId }, ex);
            }
        }

