        public async Task CreateOrUpdateJobTemplateParameterDependentsAsync(JobTemplateParameterModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<JobTemplateParameterXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<JobTemplateParameterXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetJobTemplateParameterXYZZYXsByJobTemplateParameterIdAsync(item.JobTemplateParameterId);
            if (dbExistingXYZZYX.Result != null && dbExistingJobTemplateParameter.TotalRows > 0)
            {
                var dbExistingJobTemplateParameterIds = dbExistingJobTemplateParameter.Result.SelectToList(x => x.JobTemplateParameterXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingJobTemplateParameterIds.Contains(x.JobTemplateParameterXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteJobTemplateParameterXYZZYXByIdAsync(x.JobTemplateParameterXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingJobTemplateParameterIds.Contains(x.JobTemplateParameterXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
