        public async Task<ReturnModel<bool>> AssociateXYZZYXWithJobTemplateParameterAsync(JobTemplateParameterXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobTemplateParameterWithJobTemplateParameterAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobTemplateParameter association is invalid", errorLst);
                }

                if (await systemRepository.DoesJobTemplateParameterWithXYZZYXAssociationExistsAsync(model.JobTemplateParameterId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobTemplateParameter is already associated with the JobTemplateParameter", new { model.JobTemplateParameterId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateJobTemplateParameterWithXYZZYXAsync(model.JobTemplateParameterId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate JobTemplateParameter with XYZZYX", new { model.JobTemplateParameterId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating JobTemplateParameter with XYZZYX", new { model.JobTemplateParameterId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithJobTemplateParameterAsync(JobTemplateParameterXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsJobTemplateParameterWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("JobTemplateParameter association is not valid", errorLst);
                }

                if (!await systemRepository.DoesJobTemplateParameterWithXYZZYXAssociationExistsAsync(model.JobTemplateParameterId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related JobTemplateParameter is not associated with the JobTemplateParameter", new { model.JobTemplateParameterId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateJobTemplateParameterWithJobTemplateParameterAsync(model.JobTemplateParameterId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related JobTemplateParameter with the JobTemplateParameter", new { model.JobTemplateParameterId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related JobTemplateParameter with the JobTemplateParameter", new { model.JobTemplateParameterId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsJobTemplateParameterWithXYZZYXAssociationValidAsync(JobTemplateParameterXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.JobTemplateParameterId == 0)
            {
                result.Add(new ReturnErrorItem("", "JobTemplateParameter is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related JobTemplateParameter  is not valid"));
                return result;
            }

            var entity = await GetJobTemplateParameterForWriteByIdAsync(model.JobTemplateParameterId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "JobTemplateParameter information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "JobTemplateParameters does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

