        public async Task<ReturnModel<MessageToSendModel>> CreateMessageToSendAsync(MessageToSendCreateModel messageToSend)
        {
            try
            {
                if (messageToSend == null)
                {
                    return log.ErrorAndReturnModel<MessageToSendModel>($"Unable to create MessageToSend", new ReturnErrorItem("", "MessageToSend information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<MessageToSendModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(messageToSend.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MessageToSendModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(messageToSend.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MessageToSendModel>(movieModel);
                //}

                var errorList = await IsMessageToSendModelValidForCreateAsync(messageToSend);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MessageToSendModel>($"Unable to create messageToSend", errorList);
                }

                messageToSend.IsDeleted = false;

                var item = objectMapperService.MessageToSendCreateModelToMessageToSend(messageToSend);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateMessageToSendAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create messageToSend");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.MessageToSendCreatedAsync(item.MessageToSendId);

                var view = await systemRepository.GetMessageToSendByIdAsync(item.MessageToSendId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MessageToSendModel>($"Unable to find the messageToSend", new { item.MessageToSendId });
                }

                return this.ConvertToItem(view, objectMapperService.MessageToSendToMessageToSendModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<MessageToSendModel>($"Unexpected error when creating MessageToSend", new { messageToSend?.MessageToSendId }, ex);
            }
        }

        public Task<List<ReturnErrorItem>> IsMessageToSendModelValidForCreateAsync(MessageToSendUpdateModel messageToSendModel)
