        public Task<List<ReturnErrorItem>> IsMessageToSendModelValidForUpdateAsync(MessageToSendUpdateModel messageToSendModel)
        {
            return IsMessageToSendModelValidForAllAsync(false, messageToSendModel);
        }

        public async Task<List<ReturnErrorItem>> IsMessageToSendModelValidForAllAsync(bool isCreate, MessageToSendUpdateModel messageToSendModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (messageToSendModel.MessageToSendId > 0)
                {
                    result.Add(new ReturnErrorItem("", "MessageToSend Identifier is not valid"));
                }
            }
            else
            {
                if (messageToSendModel.MessageToSendId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "MessageToSend Unique Identifier is not valid"));
                }
            }

            if (messageToSendModel.RealtimeMessageId > 0)
            {
                var realtimeMessageItem = await systemRepository.GetRealtimeMessageViewByIdAsync(messageToSendModel.RealtimeMessageId ?? 0);
                if (realtimeMessageItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the RealtimeMessage Information"));
                    return result;
                }
            }

            if (messageToSendModel.PredefinedMessageToSendTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedMessageToSendTypeId", "PredefinedMessageToSendTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedMessageToSendTypes, long>(messageToSendModel.PredefinedMessageToSendTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedMessageToSendTypeId", "Message To Send Type is not valid"));
            }

            if (messageToSendModel.MessageFrom != null && messageToSendModel.MessageFrom.Length > MessageToSendModel.COLUMN_SIZE_MessageFrom)
            {
                result.Add(new ReturnErrorItem("MessageFrom", $"MessageFrom size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageFrom}"));
            }

            if (messageToSendModel.MessageFrom == null)
            {
                result.Add(new ReturnErrorItem("MessageFrom", "MessageFrom is required "));
            }

            if (messageToSendModel.MessageTo != null && messageToSendModel.MessageTo.Length > MessageToSendModel.COLUMN_SIZE_MessageTo)
            {
                result.Add(new ReturnErrorItem("MessageTo", $"MessageTo size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageTo}"));
            }

            if (messageToSendModel.MessageTo == null)
            {
                result.Add(new ReturnErrorItem("MessageTo", "MessageTo is required "));
            }

            if (messageToSendModel.MessageFromName != null && messageToSendModel.MessageFromName.Length > MessageToSendModel.COLUMN_SIZE_MessageFromName)
            {
                result.Add(new ReturnErrorItem("MessageFromName", $"MessageFromName size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageFromName}"));
            }

            if (messageToSendModel.MessageFromName == null)
            {
                result.Add(new ReturnErrorItem("MessageFromName", "MessageFromName is required "));
            }

            if (messageToSendModel.MessageToName != null && messageToSendModel.MessageToName.Length > MessageToSendModel.COLUMN_SIZE_MessageToName)
            {
                result.Add(new ReturnErrorItem("MessageToName", $"MessageToName size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageToName}"));
            }

            if (messageToSendModel.MessageToName == null)
            {
                result.Add(new ReturnErrorItem("MessageToName", "MessageToName is required "));
            }

            if (messageToSendModel.MessageSubject != null && messageToSendModel.MessageSubject.Length > MessageToSendModel.COLUMN_SIZE_MessageSubject)
            {
                result.Add(new ReturnErrorItem("MessageSubject", $"MessageSubject size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageSubject}"));
            }

            if (messageToSendModel.MessageBody != null && messageToSendModel.MessageBody.Length > MessageToSendModel.COLUMN_SIZE_MessageBody)
            {
                result.Add(new ReturnErrorItem("MessageBody", $"MessageBody size should not exceed {MessageToSendModel.COLUMN_SIZE_MessageBody}"));
            }

            if (messageToSendModel.MessageBody == null)
            {
                result.Add(new ReturnErrorItem("MessageBody", "MessageBody is required "));
            }

            if (messageToSendModel.SentDate != null && !DateUtils.IsValidDate(messageToSendModel.SentDate.Value))
            {
                result.Add(new ReturnErrorItem("SentDate", $"SentDate is not a valid date"));
            }

            if (messageToSendModel.SentErrorMessage != null && messageToSendModel.SentErrorMessage.Length > MessageToSendModel.COLUMN_SIZE_SentErrorMessage)
            {
                result.Add(new ReturnErrorItem("SentErrorMessage", $"SentErrorMessage size should not exceed {MessageToSendModel.COLUMN_SIZE_SentErrorMessage}"));
            }

            if (messageToSendModel.SentErrorDate != null && !DateUtils.IsValidDate(messageToSendModel.SentErrorDate.Value))
            {
                result.Add(new ReturnErrorItem("SentErrorDate", $"SentErrorDate is not a valid date"));
            }

            return result.Count > 0 ? result : null;
        }

