        public async Task CreateOrUpdateMessageToSendDependentsAsync(MessageToSendModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<MessageToSendXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<MessageToSendXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetMessageToSendXYZZYXsByMessageToSendIdAsync(item.MessageToSendId);
            if (dbExistingXYZZYX.Result != null && dbExistingMessageToSend.TotalRows > 0)
            {
                var dbExistingMessageToSendIds = dbExistingMessageToSend.Result.SelectToList(x => x.MessageToSendXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingMessageToSendIds.Contains(x.MessageToSendXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteMessageToSendXYZZYXByIdAsync(x.MessageToSendXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingMessageToSendIds.Contains(x.MessageToSendXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.MessageToSendId = item.MessageToSendId;
                    var mappedItem = objectMapperService.MessageToSendXYZZYXModelToMessageToSendXYZZYXUpdateModel(x);
                    var result = await UpdateMessageToSendXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.MessageToSendId = item.MessageToSendId;
                var result = await CreateMessageToSendXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableMessageToSendByIdAsync(long messageToSendId)
        {
            try
            {
                var existingMessageToSendModel = await GetMessageToSendByIdForWriteAsync(messageToSendId);
                if (!existingMessageToSendModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MessageToSendModel>(existingMessageToSendModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(existingMessageToSendModel.Model.CompanyId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.EnableMessageToSendByIdAsync(existingMessageToSendModel.Model.MessageToSendId, await currentSessionService.GetCurrentUserIdAsync());
