        public async Task<ReturnModel<bool>> AssociateXYZZYXWithMessageToSendAsync(MessageToSendXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMessageToSendWithMessageToSendAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("MessageToSend association is invalid", errorLst);
                }

                if (await systemRepository.DoesMessageToSendWithXYZZYXAssociationExistsAsync(model.MessageToSendId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related MessageToSend is already associated with the MessageToSend", new { model.MessageToSendId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateMessageToSendWithXYZZYXAsync(model.MessageToSendId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate MessageToSend with XYZZYX", new { model.MessageToSendId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating MessageToSend with XYZZYX", new { model.MessageToSendId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithMessageToSendAsync(MessageToSendXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMessageToSendWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("MessageToSend association is not valid", errorLst);
                }

                if (!await systemRepository.DoesMessageToSendWithXYZZYXAssociationExistsAsync(model.MessageToSendId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related MessageToSend is not associated with the MessageToSend", new { model.MessageToSendId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateMessageToSendWithMessageToSendAsync(model.MessageToSendId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related MessageToSend with the MessageToSend", new { model.MessageToSendId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related MessageToSend with the MessageToSend", new { model.MessageToSendId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsMessageToSendWithXYZZYXAssociationValidAsync(MessageToSendXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.MessageToSendId == 0)
            {
                result.Add(new ReturnErrorItem("", "MessageToSend is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related MessageToSend  is not valid"));
                return result;
            }

            var entity = await GetMessageToSendForWriteByIdAsync(model.MessageToSendId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "MessageToSend information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "MessageToSends does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

