        public async Task<ReturnModel<RealtimeMessageModel>> GetRealtimeMessageByIdInternalAsync(bool forWrite, long realtimeMessageId)
        {
            try
            {
                var item = await systemRepository.GetRealtimeMessageViewByIdAsync(realtimeMessageId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to find the realtimeMessage", new { realtimeMessageId });
                }

                if (forWrite && await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>("You need to be a Super Admin to make this change");
                }

                return this.ConvertToItem(item, objectMapperService.RealtimeMessageViewToRealtimeMessageModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unexpected error when getting realtimeMessage", new { realtimeMessageId }, ex);
            }
        }

        public async Task<ReturnModel<RealtimeMessageModel>> CreateRealtimeMessageAsync(RealtimeMessageCreateModel realtimeMessage)
        {
            try
            {
                if (realtimeMessage == null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to create RealtimeMessage", new ReturnErrorItem("", "RealtimeMessage information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(realtimeMessage.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<RealtimeMessageModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(realtimeMessage.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<RealtimeMessageModel>(movieModel);
                //}

                var errorList = await IsRealtimeMessageModelValidForCreateAsync(realtimeMessage);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to create realtimeMessage", errorList);
                }

                realtimeMessage.IsDeleted = false;

                var item = objectMapperService.RealtimeMessageCreateModelToRealtimeMessage(realtimeMessage);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateRealtimeMessageAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create realtimeMessage");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.RealtimeMessageCreatedAsync(item.RealtimeMessageId);

                var view = await systemRepository.GetRealtimeMessageViewByIdAsync(item.RealtimeMessageId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to find the realtimeMessage", new { item.RealtimeMessageId });
                }

                return this.ConvertToItem(view, objectMapperService.RealtimeMessageViewToRealtimeMessageModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<RealtimeMessageModel>($"Unexpected error when creating RealtimeMessage", new { realtimeMessage?.RealtimeMessageId }, ex);
            }
        }

        public async Task<ReturnModel<RealtimeMessageModel>> UpdateRealtimeMessageAsync(RealtimeMessageUpdateModel realtimeMessage)
        {
            try
            {
                if (realtimeMessage == null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to update RealtimeMessage", new ReturnErrorItem("", "RealtimeMessage information is not valid"));
                }

                var existingRealtimeMessageModel = await GetRealtimeMessageByIdForWriteAsync(realtimeMessage.RealtimeMessageId);
                if (!existingRealtimeMessageModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>(existingRealtimeMessageModel);
                }

                realtimeMessage.CreatedByUserId = existingRealtimeMessageModel.Model.CreatedByUserId;
                realtimeMessage.CreatedDate = existingRealtimeMessageModel.Model.CreatedDate;
                realtimeMessage.IsDeleted = existingRealtimeMessageModel.Model.IsDeleted;

                var errorList = await IsRealtimeMessageModelValidForUpdateAsync(realtimeMessage);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to update realtimeMessage", errorList);
                }

                var item = objectMapperService.RealtimeMessageUpdateModelToRealtimeMessage(realtimeMessage);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateRealtimeMessageAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update realtimeMessage");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.RealtimeMessageUpdatedAsync(realtimeMessage.RealtimeMessageId, existingRealtimeMessageModel.Model, item);

                var view = await systemRepository.GetRealtimeMessageViewByIdAsync(realtimeMessage.RealtimeMessageId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unable to find the Realtime Message", new { realtimeMessage.RealtimeMessageId });
                }

                return this.ConvertToItem(view, objectMapperService.RealtimeMessageViewToRealtimeMessageModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<RealtimeMessageModel>($"Unexpected error when updating Realtime Message", new { realtimeMessage?.RealtimeMessageId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> HardDeleteRealtimeMessageByAsync(long realtimeMessageId)
        {
            try
            {
                var existingRealtimeMessageModel = await GetRealtimeMessageByIdForWriteAsync(realtimeMessageId);
                if (!existingRealtimeMessageModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(existingRealtimeMessageModel);
                }

                bool result;

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.HardDeleteRealtimeMessageByIdAsync(realtimeMessageId);
                    await trx.CompleteAsync();
                }

                await auditService.HardDeleteRealtimeMessageAsync(realtimeMessageId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when deleting realtimeMessage", new { realtimeMessageId }, ex);
            }
        }

