        public Task<List<ReturnErrorItem>> IsRealtimeMessageModelValidForUpdateAsync(RealtimeMessageUpdateModel realtimeMessageModel)
        {
            return IsRealtimeMessageModelValidForAllAsync(false, realtimeMessageModel);
