        public async Task<List<ReturnErrorItem>> IsRealtimeMessageModelValidForAllAsync(bool isCreate, RealtimeMessageUpdateModel realtimeMessageModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (realtimeMessageModel.RealtimeMessageId > 0)
                {
                    result.Add(new ReturnErrorItem("", "RealtimeMessage Identifier is not valid"));
                }
            }
            else
            {
                if (realtimeMessageModel.RealtimeMessageId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "RealtimeMessage Unique Identifier is not valid"));
                }
            }

            if (await companyRepository.GetUserByIdAsync(realtimeMessageModel.UserId) == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (realtimeMessageModel.PredefinedMessagePriorityTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedMessagePriorityTypeId", "PredefinedMessagePriorityTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedMessagePriorityTypes, long>(realtimeMessageModel.PredefinedMessagePriorityTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedMessagePriorityTypeId", "Message Priority Type is not valid"));
            }

            if (!DateUtils.IsValidDate(realtimeMessageModel.MessageDateTime))
            {
                result.Add(new ReturnErrorItem("MessageDateTime", $"MessageDateTime is not a valid date"));
            }

            if (realtimeMessageModel.MessageSubject != null && realtimeMessageModel.MessageSubject.Length > RealtimeMessageModel.COLUMN_SIZE_MessageSubject)
            {
                result.Add(new ReturnErrorItem("MessageSubject", $"MessageSubject size should not exceed {RealtimeMessageModel.COLUMN_SIZE_MessageSubject}"));
            }

            if (realtimeMessageModel.MessageSubject == null)
            {
                result.Add(new ReturnErrorItem("MessageSubject", "MessageSubject is required "));
            }

            if (realtimeMessageModel.MessageContent != null && realtimeMessageModel.MessageContent.Length > RealtimeMessageModel.COLUMN_SIZE_MessageContent)
            {
                result.Add(new ReturnErrorItem("MessageContent", $"MessageContent size should not exceed {RealtimeMessageModel.COLUMN_SIZE_MessageContent}"));
            }

            if (realtimeMessageModel.MessageContent == null)
            {
                result.Add(new ReturnErrorItem("MessageContent", "MessageContent is required "));
            }

            if (realtimeMessageModel.MessageSentDateTime != null && !DateUtils.IsValidDate(realtimeMessageModel.MessageSentDateTime.Value))
            {
                result.Add(new ReturnErrorItem("MessageSentDateTime", $"MessageSentDateTime is not a valid date"));
            }

            if (realtimeMessageModel.MessageViewedDateTime != null && !DateUtils.IsValidDate(realtimeMessageModel.MessageViewedDateTime.Value))
            {
                result.Add(new ReturnErrorItem("MessageViewedDateTime", $"MessageViewedDateTime is not a valid date"));
            }

            if (realtimeMessageModel.PredefinedRealtimeMessageStatusTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedRealtimeMessageStatusTypeId", "PredefinedRealtimeMessageStatusTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedRealtimeMessageStatusTypes, long>(realtimeMessageModel.PredefinedRealtimeMessageStatusTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedRealtimeMessageStatusTypeId", "realtimeMessageModel.Realtime Message Status Type is not valid"));
            }

            if (realtimeMessageModel.PredefinedNotificationMessageTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedNotificationMessageTypeId", "PredefinedNotificationMessageTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedNotificationMessageTypes, long>(realtimeMessageModel.PredefinedNotificationMessageTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedNotificationMessageTypeId", "Notification Message Type is not valid"));
            }

            if (realtimeMessageModel.ResourceName != null && realtimeMessageModel.ResourceName.Length > RealtimeMessageModel.COLUMN_SIZE_ResourceName)
            {
                result.Add(new ReturnErrorItem("ResourceName", $"ResourceName size should not exceed {RealtimeMessageModel.COLUMN_SIZE_ResourceName}"));
            }

            if (realtimeMessageModel.ErrorMessage != null && realtimeMessageModel.ErrorMessage.Length > RealtimeMessageModel.COLUMN_SIZE_ErrorMessage)
            {
                result.Add(new ReturnErrorItem("ErrorMessage", $"ErrorMessage size should not exceed {RealtimeMessageModel.COLUMN_SIZE_ErrorMessage}"));
            }

            if (realtimeMessageModel.ErrorOccurredOn != null && !DateUtils.IsValidDate(realtimeMessageModel.ErrorOccurredOn.Value))
            {
                result.Add(new ReturnErrorItem("ErrorOccurredOn", $"Error Occurred On is not a valid date"));
            }

            if (!ValidationUtils.IsLongValid(realtimeMessageModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }

            return result.Count > 0 ? result : null;
        }

