        public async Task CreateOrUpdateRealtimeMessageDependentsAsync(RealtimeMessageModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<RealtimeMessageXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<RealtimeMessageXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetRealtimeMessageXYZZYXsByRealtimeMessageIdAsync(item.RealtimeMessageId);
            if (dbExistingXYZZYX.Result != null && dbExistingRealtimeMessage.TotalRows > 0)
            {
                var dbExistingRealtimeMessageIds = dbExistingRealtimeMessage.Result.SelectToList(x => x.RealtimeMessageXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingRealtimeMessageIds.Contains(x.RealtimeMessageXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteRealtimeMessageXYZZYXByIdAsync(x.RealtimeMessageXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingRealtimeMessageIds.Contains(x.RealtimeMessageXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.RealtimeMessageId = item.RealtimeMessageId;
                    var mappedItem = objectMapperService.RealtimeMessageXYZZYXModelToRealtimeMessageXYZZYXUpdateModel(x);
                    var result = await UpdateRealtimeMessageXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.RealtimeMessageId = item.RealtimeMessageId;
                var result = await CreateRealtimeMessageXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

