        public async Task<ReturnModel<bool>> AssociateXYZZYXWithRealtimeMessageAsync(RealtimeMessageXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsRealtimeMessageWithRealtimeMessageAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("RealtimeMessage association is invalid", errorLst);
                }

                if (await systemRepository.DoesRealtimeMessageWithXYZZYXAssociationExistsAsync(model.RealtimeMessageId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related RealtimeMessage is already associated with the RealtimeMessage", new { model.RealtimeMessageId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateRealtimeMessageWithXYZZYXAsync(model.RealtimeMessageId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate RealtimeMessage with XYZZYX", new { model.RealtimeMessageId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating RealtimeMessage with XYZZYX", new { model.RealtimeMessageId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithRealtimeMessageAsync(RealtimeMessageXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsRealtimeMessageWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("RealtimeMessage association is not valid", errorLst);
                }

                if (!await systemRepository.DoesRealtimeMessageWithXYZZYXAssociationExistsAsync(model.RealtimeMessageId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related RealtimeMessage is not associated with the RealtimeMessage", new { model.RealtimeMessageId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateRealtimeMessageWithRealtimeMessageAsync(model.RealtimeMessageId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related RealtimeMessage with the RealtimeMessage", new { model.RealtimeMessageId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related RealtimeMessage with the RealtimeMessage", new { model.RealtimeMessageId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsRealtimeMessageWithXYZZYXAssociationValidAsync(RealtimeMessageXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.RealtimeMessageId == 0)
            {
                result.Add(new ReturnErrorItem("", "RealtimeMessage is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related RealtimeMessage  is not valid"));
                return result;
            }

            var entity = await GetRealtimeMessageForWriteByIdAsync(model.RealtimeMessageId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "RealtimeMessage information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "RealtimeMessages does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

