        public async Task<ReturnModel<SavedJobModel>> CreateSavedJobAsync(SavedJobCreateModel savedJob)
        {
            try
            {
                if (savedJob == null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to create SavedJob", new ReturnErrorItem("", "SavedJob information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(savedJob.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SavedJobModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(savedJob.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SavedJobModel>(movieModel);
                //}

                var errorList = await IsSavedJobModelValidForCreateAsync(savedJob);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to create savedJob", errorList);
                }

                savedJob.IsDeleted = false;

                var item = objectMapperService.SavedJobCreateModelToSavedJob(savedJob);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateSavedJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create savedJob");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SavedJobCreatedAsync(item.SavedJobId);

                var view = await systemRepository.GetSavedJobViewByIdAsync(item.SavedJobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to find the savedJob", new { item.SavedJobId });
                }

                return this.ConvertToItem(view, objectMapperService.SavedJobViewToSavedJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<SavedJobModel>($"Unexpected error when creating SavedJob", new { savedJob?.SavedJobId }, ex);
            }
        }

        public async Task<ReturnModel<SavedJobModel>> UpdateSavedJobAsync(SavedJobUpdateModel savedJob)
        {
            try
            {
                if (savedJob == null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to update SavedJob", new ReturnErrorItem("", "SavedJob information is not valid"));
                }

                var existingSavedJobModel = await GetSavedJobByIdForWriteAsync(savedJob.SavedJobId);
                if (!existingSavedJobModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>(existingSavedJobModel);
                }

                savedJob.CreatedByUserId = existingSavedJobModel.Model.CreatedByUserId;
                savedJob.CreatedDate = existingSavedJobModel.Model.CreatedDate;
                savedJob.IsDeleted = existingSavedJobModel.Model.IsDeleted;

                var errorList = await IsSavedJobModelValidForUpdateAsync(savedJob);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to update savedJob", errorList);
                }

                var item = objectMapperService.SavedJobUpdateModelToSavedJob(savedJob);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateSavedJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update savedJob");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SavedJobUpdatedAsync(savedJob.SavedJobId, existingSavedJobModel.Model, item);

                var view = await systemRepository.GetSavedJobViewByIdAsync(savedJob.SavedJobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SavedJobModel>($"Unable to find the savedJob", new { savedJob.SavedJobId });
                }

                return this.ConvertToItem(view, objectMapperService.SavedJobViewToSavedJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<SavedJobModel>($"Unexpected error when updating SavedJob", new { savedJob?.SavedJobId }, ex);
            }
        }

