        public async Task<List<ReturnErrorItem>> IsSavedJobModelValidForAllAsync(bool isCreate, SavedJobUpdateModel savedJobModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (savedJobModel.SavedJobId > 0)
                {
                    result.Add(new ReturnErrorItem("", "SavedJob Identifier is not valid"));
                }
            }
            else
            {
                if (savedJobModel.SavedJobId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "SavedJob Unique Identifier is not valid"));
                }
            }

            if (await systemRepository.GetJobTemplateByIdAsync(savedJobModel.JobTemplateId) == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the JobTemplate Information"));
                return result;
            }

            if (savedJobModel.SubmittedByUserId > 0)
            {
                var submittedByUserItem = await companyRepository.GetUserViewByIdAsync(savedJobModel.SubmittedByUserId ?? 0);
                if (submittedByUserItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the SubmittedByUser Information"));
                    return result;
                }
            }

            if (savedJobModel.UserId > 0)
            {
                var userItem = await companyRepository.GetUserViewByIdAsync(savedJobModel.UserId ?? 0);
                if (userItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                    return result;
                }
            }

            if (savedJobModel.PredefinedJobTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedJobTypeId", "PredefinedJobTypeId cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedJobTypes, long>(savedJobModel.PredefinedJobTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedJobTypeId", "Job Type is not valid"));
            }

            if (!ValidationUtils.IsLongValid(savedJobModel.JobTemplateId))
            {
                result.Add(new ReturnErrorItem("JobTemplateId", "JobTemplate cannot be empty"));
            }

            if (savedJobModel.CompletedDate != null && !DateUtils.IsValidDate(savedJobModel.CompletedDate.Value))
            {
                result.Add(new ReturnErrorItem("CompletedDate", $"CompletedDate is not a valid date"));
            }

            if (!DateUtils.IsValidDate(savedJobModel.SubmittedDate))
            {
                result.Add(new ReturnErrorItem("SubmittedDate", $"SubmittedDate is not a valid date"));
            }

            if (savedJobModel.ExecutableFolder != null && savedJobModel.ExecutableFolder.Length > SavedJobModel.COLUMN_SIZE_ExecutableFolder)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", $"ExecutableFolder size should not exceed {SavedJobModel.COLUMN_SIZE_ExecutableFolder}"));
            }

            if (savedJobModel.ExecutableFolder == null)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", "ExecutableFolder is required "));
            }

            if (savedJobModel.ExecutableName != null && savedJobModel.ExecutableName.Length > SavedJobModel.COLUMN_SIZE_ExecutableName)
            {
                result.Add(new ReturnErrorItem("ExecutableName", $"ExecutableName size should not exceed {SavedJobModel.COLUMN_SIZE_ExecutableName}"));
            }

            if (savedJobModel.ExecutableName == null)
            {
                result.Add(new ReturnErrorItem("ExecutableName", "ExecutableName is required "));
            }

            if (savedJobModel.ExecutableParameter != null && savedJobModel.ExecutableParameter.Length > SavedJobModel.COLUMN_SIZE_ExecutableParameter)
            {
                result.Add(new ReturnErrorItem("ExecutableParameter", $"ExecutableParameter size should not exceed {SavedJobModel.COLUMN_SIZE_ExecutableParameter}"));
            }

            if (savedJobModel.SerializedJobParameter != null && savedJobModel.SerializedJobParameter.Length > SavedJobModel.COLUMN_SIZE_SerializedJobParameter)
            {
                result.Add(new ReturnErrorItem("SerializedJobParameter", $"SerializedJobParameter size should not exceed {SavedJobModel.COLUMN_SIZE_SerializedJobParameter}"));
            }

            if (savedJobModel.ReportTemplateFile != null && savedJobModel.ReportTemplateFile.Length > SavedJobModel.COLUMN_SIZE_ReportTemplateFile)
            {
                result.Add(new ReturnErrorItem("ReportTemplateFile", $"ReportTemplateFile size should not exceed {SavedJobModel.COLUMN_SIZE_ReportTemplateFile}"));
            }

            if (savedJobModel.CustomExportName != null && savedJobModel.CustomExportName.Length > SavedJobModel.COLUMN_SIZE_CustomExportName)
            {
                result.Add(new ReturnErrorItem("CustomExportName", $"CustomExportName size should not exceed {SavedJobModel.COLUMN_SIZE_CustomExportName}"));
            }

            if (savedJobModel.PickupDate != null && !DateUtils.IsValidDate(savedJobModel.PickupDate.Value))
            {
                result.Add(new ReturnErrorItem("PickupDate", $"PickupDate is not a valid date"));
            }

            if (savedJobModel.JobName != null && savedJobModel.JobName.Length > SavedJobModel.COLUMN_SIZE_JobName)
            {
                result.Add(new ReturnErrorItem("JobName", $"JobName size should not exceed {SavedJobModel.COLUMN_SIZE_JobName}"));
            }

            return result.Count > 0 ? result : null;
        }

