        public async Task CreateOrUpdateSavedJobDependentsAsync(SavedJobModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<SavedJobXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<SavedJobXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetSavedJobXYZZYXsBySavedJobIdAsync(item.SavedJobId);
            if (dbExistingXYZZYX.Result != null && dbExistingSavedJob.TotalRows > 0)
            {
                var dbExistingSavedJobIds = dbExistingSavedJob.Result.SelectToList(x => x.SavedJobXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingSavedJobIds.Contains(x.SavedJobXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteSavedJobXYZZYXByIdAsync(x.SavedJobXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingSavedJobIds.Contains(x.SavedJobXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.SavedJobId = item.SavedJobId;
                    var mappedItem = objectMapperService.SavedJobXYZZYXModelToSavedJobXYZZYXUpdateModel(x);
                    var result = await UpdateSavedJobXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.SavedJobId = item.SavedJobId;
                var result = await CreateSavedJobXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

