        public async Task<ReturnModel<bool>> AssociateXYZZYXWithSavedJobAsync(SavedJobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSavedJobWithSavedJobAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SavedJob association is invalid", errorLst);
                }

                if (await systemRepository.DoesSavedJobWithXYZZYXAssociationExistsAsync(model.SavedJobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related SavedJob is already associated with the SavedJob", new { model.SavedJobId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateSavedJobWithXYZZYXAsync(model.SavedJobId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate SavedJob with XYZZYX", new { model.SavedJobId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating SavedJob with XYZZYX", new { model.SavedJobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithSavedJobAsync(SavedJobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSavedJobWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SavedJob association is not valid", errorLst);
                }

                if (!await systemRepository.DoesSavedJobWithXYZZYXAssociationExistsAsync(model.SavedJobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related SavedJob is not associated with the SavedJob", new { model.SavedJobId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateSavedJobWithSavedJobAsync(model.SavedJobId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related SavedJob with the SavedJob", new { model.SavedJobId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related SavedJob with the SavedJob", new { model.SavedJobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsSavedJobWithXYZZYXAssociationValidAsync(SavedJobXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.SavedJobId == 0)
            {
                result.Add(new ReturnErrorItem("", "SavedJob is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related SavedJob  is not valid"));
                return result;
            }

            var entity = await GetSavedJobForWriteByIdAsync(model.SavedJobId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "SavedJob information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "SavedJobs does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportSavedJobAsync(SavedJobImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("SavedJob Info is not provided");
                }

                if (model.SavedJobs == null || model.SavedJobs.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("SavedJobs Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.SavedJobs)
                {
                    var prod = await wipService.GetSavedJobByExternalIdentifierAsync(item.SavedJobIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        SavedJobCreateModel savedJobCreateModel = new SavedJobCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedSavedJob = await CreateSavedJobAsync(savedJobCreateModel);
                        if (!newlyCreatedSavedJob.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedSavedJob.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedSavedJob.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        SavedJobUpdateModel savedJobUpdateModel = new SavedJobUpdateModel
                        {
                        };

                        //update product
                        var updatedSavedJobModel = await wipService.UpdateSavedJobAsync(savedJobUpdateModel);
                        if (!updatedSavedJobModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
