        public async Task<ReturnModel<ScheduledJobModel>> CreateScheduledJobAsync(ScheduledJobCreateModel scheduledJob)
        {
            try
            {
                if (scheduledJob == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to create ScheduledJob", new ReturnErrorItem("", "ScheduledJob information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(scheduledJob.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ScheduledJobModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(scheduledJob.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ScheduledJobModel>(movieModel);
                //}

                var errorList = await IsScheduledJobModelValidForCreateAsync(scheduledJob);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to create scheduledJob", errorList);
                }

                scheduledJob.IsDeleted = false;

                var item = objectMapperService.ScheduledJobCreateModelToScheduledJob(scheduledJob);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateScheduledJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create scheduledJob");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ScheduledJobCreatedAsync(item.ScheduledJobId);

                var view = await systemRepository.GetScheduledJobViewByIdAsync(item.ScheduledJobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to find the scheduledJob", new { item.ScheduledJobId });
                }

                return this.ConvertToItem(view,objectMapperService.ScheduledJobViewToScheduledJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<ScheduledJobModel>($"Unexpected error when creating ScheduledJob", new { scheduledJob?.ScheduledJobId }, ex);
            }
        }

        public async Task<ReturnModel<ScheduledJobModel>> UpdateScheduledJobAsync(ScheduledJobUpdateModel scheduledJob)
        {
            try
            {
                if (scheduledJob == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to update ScheduledJob", new ReturnErrorItem("", "ScheduledJob information is not valid"));
                }

                var existingScheduledJobModel = await GetScheduledJobByIdForWriteAsync(scheduledJob.ScheduledJobId);
                if (!existingScheduledJobModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>(existingScheduledJobModel);
                }

                scheduledJob.CreatedByUserId = existingScheduledJobModel.Model.CreatedByUserId;
                scheduledJob.CreatedDate = existingScheduledJobModel.Model.CreatedDate;
                scheduledJob.IsDeleted = existingScheduledJobModel.Model.IsDeleted;

                var errorList = await IsScheduledJobModelValidForUpdateAsync(scheduledJob);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to update scheduledJob", errorList);
                }

                var item = objectMapperService.ScheduledJobUpdateModelToScheduledJob(scheduledJob);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateScheduledJobAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update scheduledJob");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ScheduledJobUpdatedAsync(scheduledJob.ScheduledJobId, existingScheduledJobModel.Model, item);

                var view = await systemRepository.GetScheduledJobViewByIdAsync(scheduledJob.ScheduledJobId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobModel>($"Unable to find the scheduledJob", new { scheduledJob.ScheduledJobId });
                }

                return this.ConvertToItem(view, objectMapperService.ScheduledJobViewToScheduledJobModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<ScheduledJobModel>($"Unexpected error when updating ScheduledJob", new { scheduledJob?.ScheduledJobId }, ex);
            }
        }

