        public Task<List<ReturnErrorItem>> IsScheduledJobModelValidForCreateAsync(ScheduledJobUpdateModel scheduledJobModel)
        {
            return IsScheduledJobModelValidForAllAsync(true, scheduledJobModel);
        }

        public Task<List<ReturnErrorItem>> IsScheduledJobModelValidForUpdateAsync(ScheduledJobUpdateModel scheduledJobModel)
        {
            return IsScheduledJobModelValidForAllAsync(false, scheduledJobModel);
        }

        public async Task<List<ReturnErrorItem>> IsScheduledJobModelValidForAllAsync(bool isCreate, ScheduledJobUpdateModel scheduledJobModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (scheduledJobModel.ScheduledJobId > 0)
                {
                    result.Add(new ReturnErrorItem("", "ScheduledJob Identifier is not valid"));
                }
            }
            else
            {
                if (scheduledJobModel.ScheduledJobId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "ScheduledJob Unique Identifier is not valid"));
                }
            }

            if (await systemRepository.GetJobTemplateByIdAsync(scheduledJobModel.JobTemplateId) == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the JobTemplate Information"));
                return result;
            }

            if (scheduledJobModel.SubmittedByUserId > 0)
            {
                var submittedByUserItem = await companyRepository.GetUserViewByIdAsync(scheduledJobModel.SubmittedByUserId ?? 0);
                if (submittedByUserItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the SubmittedByUser Information"));
                    return result;
                }
            }

            if (scheduledJobModel.RunAsUserId > 0)
            {
                var runAsUserItem = await companyRepository.GetUserViewByIdAsync(scheduledJobModel.RunAsUserId ?? 0);
                if (runAsUserItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the RunAsUser Information"));
                    return result;
                }
            }

            if (!ValidationUtils.IsLongValid(scheduledJobModel.JobTemplateId))
            {
                result.Add(new ReturnErrorItem("JobTemplateId", "JobTemplate cannot be empty"));
            }

            if (scheduledJobModel.ExecutableFolder != null && scheduledJobModel.ExecutableFolder.Length > ScheduledJobModel.COLUMN_SIZE_ExecutableFolder)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", $"ExecutableFolder size should not exceed {ScheduledJobModel.COLUMN_SIZE_ExecutableFolder}"));
            }

            if (scheduledJobModel.ExecutableFolder == null)
            {
                result.Add(new ReturnErrorItem("ExecutableFolder", "ExecutableFolder is required "));
            }

            if (scheduledJobModel.ExecutableName != null && scheduledJobModel.ExecutableName.Length > ScheduledJobModel.COLUMN_SIZE_ExecutableName)
            {
                result.Add(new ReturnErrorItem("ExecutableName", $"ExecutableName size should not exceed {ScheduledJobModel.COLUMN_SIZE_ExecutableName}"));
            }

            if (scheduledJobModel.ExecutableName == null)
            {
                result.Add(new ReturnErrorItem("ExecutableName", "ExecutableName is required "));
            }

            if (scheduledJobModel.ExecutableParameter != null && scheduledJobModel.ExecutableParameter.Length > ScheduledJobModel.COLUMN_SIZE_ExecutableParameter)
            {
                result.Add(new ReturnErrorItem("ExecutableParameter", $"ExecutableParameter size should not exceed {ScheduledJobModel.COLUMN_SIZE_ExecutableParameter}"));
            }

            if (scheduledJobModel.SerializedJobParameter != null && scheduledJobModel.SerializedJobParameter.Length > ScheduledJobModel.COLUMN_SIZE_SerializedJobParameter)
            {
                result.Add(new ReturnErrorItem("SerializedJobParameter", $"SerializedJobParameter size should not exceed {ScheduledJobModel.COLUMN_SIZE_SerializedJobParameter}"));
            }

            if (scheduledJobModel.ReportTemplateFile != null && scheduledJobModel.ReportTemplateFile.Length > ScheduledJobModel.COLUMN_SIZE_ReportTemplateFile)
            {
                result.Add(new ReturnErrorItem("ReportTemplateFile", $"ReportTemplateFile size should not exceed {ScheduledJobModel.COLUMN_SIZE_ReportTemplateFile}"));
            }

            if (scheduledJobModel.CustomExportName != null && scheduledJobModel.CustomExportName.Length > ScheduledJobModel.COLUMN_SIZE_CustomExportName)
            {
                result.Add(new ReturnErrorItem("CustomExportName", $"CustomExportName size should not exceed {ScheduledJobModel.COLUMN_SIZE_CustomExportName}"));
            }

            if (scheduledJobModel.PickupDate != null && !DateUtils.IsValidDate(scheduledJobModel.PickupDate.Value))
            {
                result.Add(new ReturnErrorItem("PickupDate", $"PickupDate is not a valid date"));
            }

            if (scheduledJobModel.JobName != null && scheduledJobModel.JobName.Length > ScheduledJobModel.COLUMN_SIZE_JobName)
            {
                result.Add(new ReturnErrorItem("JobName", $"JobName size should not exceed {ScheduledJobModel.COLUMN_SIZE_JobName}"));
            }

            if (scheduledJobModel.StartDate != null && !DateUtils.IsValidDate(scheduledJobModel.StartDate.Value))
            {
                result.Add(new ReturnErrorItem("StartDate", $"StartDate is not a valid date"));
            }

            if (scheduledJobModel.EndDate != null && !DateUtils.IsValidDate(scheduledJobModel.EndDate.Value))
            {
                result.Add(new ReturnErrorItem("EndDate", $"EndDate is not a valid date"));
            }

            if (scheduledJobModel.StartTime != null && !DateUtils.IsValidDate(scheduledJobModel.StartTime.Value))
            {
                result.Add(new ReturnErrorItem("StartTime", $"StartTime is not a valid date"));
            }

            if (scheduledJobModel.RunMonthlyTime != null && !DateUtils.IsValidDate(scheduledJobModel.RunMonthlyTime.Value))
            {
                result.Add(new ReturnErrorItem("RunMonthlyTime", $"RunMonthlyTime is not a valid date"));
            }

            if (scheduledJobModel.RunDailyTime != null && !DateUtils.IsValidDate(scheduledJobModel.RunDailyTime.Value))
            {
                result.Add(new ReturnErrorItem("RunDailyTime", $"RunDailyTime is not a valid date"));
            }

            return result.Count > 0 ? result : null;
        }

