        public async Task CreateOrUpdateScheduledJobDependentsAsync(ScheduledJobModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<ScheduledJobXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<ScheduledJobXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetScheduledJobXYZZYXsByScheduledJobIdAsync(item.ScheduledJobId);
            if (dbExistingXYZZYX.Result != null && dbExistingScheduledJob.TotalRows > 0)
            {
                var dbExistingScheduledJobIds = dbExistingScheduledJob.Result.SelectToList(x => x.ScheduledJobXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingScheduledJobIds.Contains(x.ScheduledJobXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteScheduledJobXYZZYXByIdAsync(x.ScheduledJobXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingScheduledJobIds.Contains(x.ScheduledJobXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.ScheduledJobId = item.ScheduledJobId;
                    var mappedItem = objectMapperService.ScheduledJobXYZZYXModelToScheduledJobXYZZYXUpdateModel(x);
                    var result = await UpdateScheduledJobXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.ScheduledJobId = item.ScheduledJobId;
                var result = await CreateScheduledJobXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

