        public async Task<ReturnModel<bool>> AssociateXYZZYXWithScheduledJobAsync(ScheduledJobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsScheduledJobWithScheduledJobAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ScheduledJob association is invalid", errorLst);
                }

                if (await systemRepository.DoesScheduledJobWithXYZZYXAssociationExistsAsync(model.ScheduledJobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ScheduledJob is already associated with the ScheduledJob", new { model.ScheduledJobId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateScheduledJobWithXYZZYXAsync(model.ScheduledJobId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate ScheduledJob with XYZZYX", new { model.ScheduledJobId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating ScheduledJob with XYZZYX", new { model.ScheduledJobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithScheduledJobAsync(ScheduledJobXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsScheduledJobWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ScheduledJob association is not valid", errorLst);
                }

                if (!await systemRepository.DoesScheduledJobWithXYZZYXAssociationExistsAsync(model.ScheduledJobId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ScheduledJob is not associated with the ScheduledJob", new { model.ScheduledJobId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateScheduledJobWithScheduledJobAsync(model.ScheduledJobId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related ScheduledJob with the ScheduledJob", new { model.ScheduledJobId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related ScheduledJob with the ScheduledJob", new { model.ScheduledJobId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsScheduledJobWithXYZZYXAssociationValidAsync(ScheduledJobXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.ScheduledJobId == 0)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJob is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related ScheduledJob  is not valid"));
                return result;
            }

            var entity = await GetScheduledJobForWriteByIdAsync(model.ScheduledJobId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJob information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobs does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

