        public async Task<ReturnModel<SavedJobNotificationEmailModel>> CreateSavedJobNotificationEmailAsync(SavedJobNotificationEmailCreateModel savedJobNotificationEmail)
        {
            try
            {
                if (savedJobNotificationEmail == null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to create SavedJobNotificationEmail", new ReturnErrorItem("", "SavedJobNotificationEmail information is not valid"));
                }

                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>("You need to be a Super Admin to make this change");
                }

                //var companyModel = await GetCompanyForReadById(savedJobNotificationEmail.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(savedJobNotificationEmail.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>(movieModel);
                //}

                var errorList = await IsSavedJobNotificationEmailModelValidForCreateAsync(savedJobNotificationEmail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to create savedJobNotificationEmail", errorList);
                }

                savedJobNotificationEmail.IsDeleted = false;

                var item = objectMapperService.SavedJobNotificationEmailCreateModelToSavedJobNotificationEmail(savedJobNotificationEmail);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateSavedJobNotificationEmailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create savedJobNotificationEmail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SavedJobNotificationEmailCreatedAsync(item.SavedJobNotificationEmailId);

                var view = await systemRepository.GetSavedJobNotificationEmailViewByIdAsync(item.SavedJobNotificationEmailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to find the savedJobNotificationEmail", new { item.SavedJobNotificationEmailId });
                }

                return this.ConvertToItem(view, objectMapperService.SavedJobNotificationEmailViewToSavedJobNotificationEmailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<SavedJobNotificationEmailModel>($"Unexpected error when creating SavedJobNotificationEmail", new { savedJobNotificationEmail?.SavedJobNotificationEmailId }, ex);
            }
        }

        public async Task<ReturnModel<SavedJobNotificationEmailModel>> UpdateSavedJobNotificationEmailAsync(SavedJobNotificationEmailUpdateModel savedJobNotificationEmail)
        {
            try
            {
                if (savedJobNotificationEmail == null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to update SavedJobNotificationEmail", new ReturnErrorItem("", "SavedJobNotificationEmail information is not valid"));
                }

                var existingSavedJobNotificationEmailModel = await GetSavedJobNotificationEmailByIdForWriteAsync(savedJobNotificationEmail.SavedJobNotificationEmailId);
                if (!existingSavedJobNotificationEmailModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>(existingSavedJobNotificationEmailModel);
                }

                savedJobNotificationEmail.CreatedByUserId = existingSavedJobNotificationEmailModel.Model.CreatedByUserId;
                savedJobNotificationEmail.CreatedDate = existingSavedJobNotificationEmailModel.Model.CreatedDate;
                savedJobNotificationEmail.IsDeleted = existingSavedJobNotificationEmailModel.Model.IsDeleted;

                var errorList = await IsSavedJobNotificationEmailModelValidForUpdateAsync(savedJobNotificationEmail);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to update savedJobNotificationEmail", errorList);
                }

                var item = objectMapperService.SavedJobNotificationEmailUpdateModelToSavedJobNotificationEmail(savedJobNotificationEmail);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateSavedJobNotificationEmailAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update savedJobNotificationEmail");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SavedJobNotificationEmailUpdatedAsync(savedJobNotificationEmail.SavedJobNotificationEmailId, existingSavedJobNotificationEmailModel.Model, item);

                var view = await systemRepository.GetSavedJobNotificationEmailViewByIdAsync(savedJobNotificationEmail.SavedJobNotificationEmailId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unable to find the savedJobNotificationEmail", new { savedJobNotificationEmail.SavedJobNotificationEmailId });
                }

                return this.ConvertToItem(view, objectMapperService.SavedJobNotificationEmailViewToSavedJobNotificationEmailModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<SavedJobNotificationEmailModel>($"Unexpected error when updating SavedJobNotificationEmail {savedJobNotificationEmail?.SavedJobNotificationEmailId}", ex);
            }
        }

