        public async Task CreateOrUpdateSavedJobNotificationEmailDependentsAsync(SavedJobNotificationEmailModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<SavedJobNotificationEmailXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<SavedJobNotificationEmailXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetSavedJobNotificationEmailXYZZYXsBySavedJobNotificationEmailIdAsync(item.SavedJobNotificationEmailId);
            if (dbExistingXYZZYX.Result != null && dbExistingSavedJobNotificationEmail.TotalRows > 0)
            {
                var dbExistingSavedJobNotificationEmailIds = dbExistingSavedJobNotificationEmail.Result.SelectToList(x => x.SavedJobNotificationEmailXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingSavedJobNotificationEmailIds.Contains(x.SavedJobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteSavedJobNotificationEmailXYZZYXByIdAsync(x.SavedJobNotificationEmailXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingSavedJobNotificationEmailIds.Contains(x.SavedJobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.SavedJobNotificationEmailId = item.SavedJobNotificationEmailId;
                    var mappedItem = objectMapperService.SavedJobNotificationEmailXYZZYXModelToSavedJobNotificationEmailXYZZYXUpdateModel(x);
                    var result = await UpdateSavedJobNotificationEmailXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.SavedJobNotificationEmailId = item.SavedJobNotificationEmailId;
                var result = await CreateSavedJobNotificationEmailXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableSavedJobNotificationEmailByIdAsync(long savedJobNotificationEmailId)
        {
            try
