        public async Task<ReturnModel<bool>> AssociateXYZZYXWithSavedJobNotificationEmailAsync(SavedJobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSavedJobNotificationEmailWithSavedJobNotificationEmailAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SavedJobNotificationEmail association is invalid", errorLst);
                }

                if (await systemRepository.DoesSavedJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.SavedJobNotificationEmailId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related SavedJobNotificationEmail is already associated with the SavedJobNotificationEmail", new { model.SavedJobNotificationEmailId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateSavedJobNotificationEmailWithXYZZYXAsync(model.SavedJobNotificationEmailId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate SavedJobNotificationEmail with XYZZYX", new { model.SavedJobNotificationEmailId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating SavedJobNotificationEmail with XYZZYX", new { model.SavedJobNotificationEmailId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithSavedJobNotificationEmailAsync(SavedJobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSavedJobNotificationEmailWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SavedJobNotificationEmail association is not valid", errorLst);
                }

                if (!await systemRepository.DoesSavedJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.SavedJobNotificationEmailId, model.XYZZYXId))
                {
