        public async Task<List<ReturnErrorItem>> IsSavedJobNotificationEmailWithXYZZYXAssociationValidAsync(SavedJobNotificationEmailXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.SavedJobNotificationEmailId == 0)
            {
                result.Add(new ReturnErrorItem("", "SavedJobNotificationEmail is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related SavedJobNotificationEmail  is not valid"));
                return result;
            }

            var entity = await GetSavedJobNotificationEmailForWriteByIdAsync(model.SavedJobNotificationEmailId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "SavedJobNotificationEmail information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "SavedJobNotificationEmails does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

