        public async Task<ReturnModel<ScheduledJobHistoryModel>> CreateScheduledJobHistoryAsync(ScheduledJobHistoryCreateModel scheduledJobHistory)
        {
            try
            {
                if (scheduledJobHistory == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to create ScheduledJobHistory", new ReturnErrorItem("", "ScheduledJobHistory information is not valid"));
                }

                //var companyModel = await GetCompanyForReadById(scheduledJobHistory.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(scheduledJobHistory.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>(movieModel);
                //}

                var errorList = await IsScheduledJobHistoryModelValidForCreateAsync(scheduledJobHistory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to create scheduledJobHistory", errorList);
                }

                scheduledJobHistory.IsDeleted = false;

                var item = objectMapperService.ScheduledJobHistoryCreateModelToScheduledJobHistory(scheduledJobHistory);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateScheduledJobHistoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create scheduledJobHistory");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ScheduledJobHistoryCreatedAsync(item.ScheduledJobHistoryId);

                var view = await systemRepository.GetScheduledJobHistoryViewByIdAsync(item.ScheduledJobHistoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to find the scheduledJobHistory", new { item.ScheduledJobHistoryId });
                }

                return this.ConvertToItem(view, objectMapperService.ScheduledJobHistoryViewToScheduledJobHistoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<ScheduledJobHistoryModel>($"Unexpected error when creating ScheduledJobHistory", new { scheduledJobHistory?.ScheduledJobHistoryId }, ex);
            }
        }

        public async Task<ReturnModel<ScheduledJobHistoryModel>> UpdateScheduledJobHistoryAsync(ScheduledJobHistoryUpdateModel scheduledJobHistory)
        {
            try
            {
                if (scheduledJobHistory == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to update ScheduledJobHistory", new ReturnErrorItem("", "ScheduledJobHistory information is not valid"));
                }

                var existingScheduledJobHistoryModel = await GetScheduledJobHistoryByIdForWriteAsync(scheduledJobHistory.ScheduledJobHistoryId);
                if (!existingScheduledJobHistoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>(existingScheduledJobHistoryModel);
                }

                scheduledJobHistory.CreatedByUserId = existingScheduledJobHistoryModel.Model.CreatedByUserId;
                scheduledJobHistory.CreatedDate = existingScheduledJobHistoryModel.Model.CreatedDate;
                scheduledJobHistory.IsDeleted = existingScheduledJobHistoryModel.Model.IsDeleted;

                var errorList = await IsScheduledJobHistoryModelValidForUpdateAsync(scheduledJobHistory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to update scheduledJobHistory", errorList);
                }

                var item = objectMapperService.ScheduledJobHistoryUpdateModelToScheduledJobHistory(scheduledJobHistory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateScheduledJobHistoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update scheduledJobHistory");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.ScheduledJobHistoryUpdatedAsync(scheduledJobHistory.ScheduledJobHistoryId, existingScheduledJobHistoryModel.Model, item);

                var view = await systemRepository.GetScheduledJobHistoryViewByIdAsync(scheduledJobHistory.ScheduledJobHistoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unable to find the scheduledJobHistory", new { scheduledJobHistory.ScheduledJobHistoryId });
                }

                return this.ConvertToItem(view, objectMapperService.ScheduledJobHistoryViewToScheduledJobHistoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<ScheduledJobHistoryModel>($"Unexpected error when updating ScheduledJobHistory {scheduledJobHistory?.ScheduledJobHistoryId}", ex);
            }
        }

