        public async Task<ReturnModel<FileStreamModel>> GetScheduledJobHistoryFileAsync(long scheduledJobHistoryId)
        {
            try
            {
                var view = await GetScheduledJobHistoryByIdForReadAsync(scheduledJobHistoryId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the ScheduledJobHistory", new { scheduledJobHistoryId });
                }

                var fileName = view.Model.SourceStoredFilePath;

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.TenantId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"ScheduledJobHistoryFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.TenantId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for ScheduledJobHistory ", new { scheduledJobHistoryId }, ex);
            }
        }

        public async Task CreateOrUpdateScheduledJobHistoryDependentsAsync(ScheduledJobHistoryModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<ScheduledJobHistoryXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<ScheduledJobHistoryXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetScheduledJobHistoryXYZZYXsByScheduledJobHistoryIdAsync(item.ScheduledJobHistoryId);
            if (dbExistingXYZZYX.Result != null && dbExistingScheduledJobHistory.TotalRows > 0)
            {
                var dbExistingScheduledJobHistoryIds = dbExistingScheduledJobHistory.Result.SelectToList(x => x.ScheduledJobHistoryXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingScheduledJobHistoryIds.Contains(x.ScheduledJobHistoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteScheduledJobHistoryXYZZYXByIdAsync(x.ScheduledJobHistoryXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingScheduledJobHistoryIds.Contains(x.ScheduledJobHistoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.ScheduledJobHistoryId = item.ScheduledJobHistoryId;
                    var mappedItem = objectMapperService.ScheduledJobHistoryXYZZYXModelToScheduledJobHistoryXYZZYXUpdateModel(x);
                    var result = await UpdateScheduledJobHistoryXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.ScheduledJobHistoryId = item.ScheduledJobHistoryId;
                var result = await CreateScheduledJobHistoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

