        public async Task<ReturnModel<bool>> AssociateXYZZYXWithScheduledJobHistoryAsync(ScheduledJobHistoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsScheduledJobHistoryWithScheduledJobHistoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ScheduledJobHistory association is invalid", errorLst);
                }

                if (await systemRepository.DoesScheduledJobHistoryWithXYZZYXAssociationExistsAsync(model.ScheduledJobHistoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ScheduledJobHistory is already associated with the ScheduledJobHistory", new { model.ScheduledJobHistoryId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateScheduledJobHistoryWithXYZZYXAsync(model.ScheduledJobHistoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate ScheduledJobHistory with XYZZYX", new { model.ScheduledJobHistoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating ScheduledJobHistory with XYZZYX", new { model.ScheduledJobHistoryId, model.XYZZYXId }, ex);
            }
        }

