        public async Task<List<ReturnErrorItem>> IsScheduledJobHistoryWithXYZZYXAssociationValidAsync(ScheduledJobHistoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.ScheduledJobHistoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobHistory is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related ScheduledJobHistory  is not valid"));
                return result;
            }

            var entity = await GetScheduledJobHistoryForWriteByIdAsync(model.ScheduledJobHistoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobHistory information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobHistorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

