        public async Task CreateOrUpdateScheduledJobNotificationEmailDependentsAsync(ScheduledJobNotificationEmailModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<ScheduledJobNotificationEmailXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<ScheduledJobNotificationEmailXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetScheduledJobNotificationEmailXYZZYXsByScheduledJobNotificationEmailIdAsync(item.ScheduledJobNotificationEmailId);
            if (dbExistingXYZZYX.Result != null && dbExistingScheduledJobNotificationEmail.TotalRows > 0)
            {
                var dbExistingScheduledJobNotificationEmailIds = dbExistingScheduledJobNotificationEmail.Result.SelectToList(x => x.ScheduledJobNotificationEmailXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingScheduledJobNotificationEmailIds.Contains(x.ScheduledJobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteScheduledJobNotificationEmailXYZZYXByIdAsync(x.ScheduledJobNotificationEmailXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingScheduledJobNotificationEmailIds.Contains(x.ScheduledJobNotificationEmailXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.ScheduledJobNotificationEmailId = item.ScheduledJobNotificationEmailId;
                    var mappedItem = objectMapperService.ScheduledJobNotificationEmailXYZZYXModelToScheduledJobNotificationEmailXYZZYXUpdateModel(x);
                    var result = await UpdateScheduledJobNotificationEmailXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.ScheduledJobNotificationEmailId = item.ScheduledJobNotificationEmailId;
                var result = await CreateScheduledJobNotificationEmailXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableScheduledJobNotificationEmailByIdAsync(long scheduledJobNotificationEmailId)
        {
            try
            {
                var existingScheduledJobNotificationEmailModel = await GetScheduledJobNotificationEmailByIdForWriteAsync(scheduledJobNotificationEmailId);
                if (!existingScheduledJobNotificationEmailModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<ScheduledJobNotificationEmailModel>(existingScheduledJobNotificationEmailModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(existingScheduledJobNotificationEmailModel.Model.CompanyId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.EnableScheduledJobNotificationEmailByIdAsync(existingScheduledJobNotificationEmailModel.Model.ScheduledJobNotificationEmailId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.ScheduledJobNotificationEmailEnabledAsync(scheduledJobNotificationEmailId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when marking scheduledJobNotificationEmail as deleted", new { scheduledJobNotificationEmailId }, ex);
            }
        }

