        public async Task<ReturnModel<bool>> AssociateXYZZYXWithScheduledJobNotificationEmailAsync(ScheduledJobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsScheduledJobNotificationEmailWithScheduledJobNotificationEmailAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ScheduledJobNotificationEmail association is invalid", errorLst);
                }

                if (await systemRepository.DoesScheduledJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.ScheduledJobNotificationEmailId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ScheduledJobNotificationEmail is already associated with the ScheduledJobNotificationEmail", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateScheduledJobNotificationEmailWithXYZZYXAsync(model.ScheduledJobNotificationEmailId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate ScheduledJobNotificationEmail with XYZZYX", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating ScheduledJobNotificationEmail with XYZZYX", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithScheduledJobNotificationEmailAsync(ScheduledJobNotificationEmailXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsScheduledJobNotificationEmailWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("ScheduledJobNotificationEmail association is not valid", errorLst);
                }

                if (!await systemRepository.DoesScheduledJobNotificationEmailWithXYZZYXAssociationExistsAsync(model.ScheduledJobNotificationEmailId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related ScheduledJobNotificationEmail is not associated with the ScheduledJobNotificationEmail", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateScheduledJobNotificationEmailWithScheduledJobNotificationEmailAsync(model.ScheduledJobNotificationEmailId, model.XYZZYXId);
                if (rValue)
