                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related ScheduledJobNotificationEmail with the ScheduledJobNotificationEmail", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related ScheduledJobNotificationEmail with the ScheduledJobNotificationEmail", new { model.ScheduledJobNotificationEmailId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsScheduledJobNotificationEmailWithXYZZYXAssociationValidAsync(ScheduledJobNotificationEmailXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.ScheduledJobNotificationEmailId == 0)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobNotificationEmail is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related ScheduledJobNotificationEmail  is not valid"));
                return result;
            }

            var entity = await GetScheduledJobNotificationEmailForWriteByIdAsync(model.ScheduledJobNotificationEmailId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobNotificationEmail information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "ScheduledJobNotificationEmails does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

