        public async Task<ReturnModel<CompanyStorageConfigurationModel>> CreateCompanyStorageConfigurationAsync(CompanyStorageConfigurationCreateModel companyStorageConfiguration)
        {
            try
            {
                if (companyStorageConfiguration == null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to create CompanyStorageConfiguration", new ReturnErrorItem("", "CompanyStorageConfiguration information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Only Superadmins can create Storage Configuration", new ReturnErrorItem("", "Only Superadmins can create Storage Configuration"));
                }

                //var companyModel = await GetCompanyForReadById(companyStorageConfiguration.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(companyStorageConfiguration.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>(movieModel);
                //}

                var errorList = await IsCompanyStorageConfigurationModelValidForCreateAsync(companyStorageConfiguration);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to create companyStorageConfiguration", errorList);
                }

                companyStorageConfiguration.IsDeleted = false;

                var item = objectMapperService.CompanyStorageConfigurationCreateModelToCompanyStorageConfiguration(companyStorageConfiguration);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateCompanyStorageConfigurationAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create companyStorageConfiguration");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.CompanyStorageConfigurationCreatedAsync(item.CompanyStorageConfigurationId);

                var view = await systemRepository.GetCompanyStorageConfigurationViewByIdAsync(item.CompanyStorageConfigurationId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to find the companyStorageConfiguration", new { item.CompanyStorageConfigurationId });
                }

                return this.ConvertToItem(view, objectMapperService.CompanyStorageConfigurationViewToCompanyStorageConfigurationModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<CompanyStorageConfigurationModel>($"Unexpected error when creating CompanyStorageConfiguration", new { companyStorageConfiguration?.CompanyStorageConfigurationId }, ex);
            }
        }

        public async Task<ReturnModel<CompanyStorageConfigurationModel>> UpdateCompanyStorageConfigurationAsync(CompanyStorageConfigurationUpdateModel companyStorageConfiguration)
        {
            try
            {
                if (companyStorageConfiguration == null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to update CompanyStorageConfiguration", new ReturnErrorItem("", "CompanyStorageConfiguration information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Only Superadmins can create Storage Configuration", new ReturnErrorItem("", "Only Superadmins can create Storage Configuration"));
                }

                var existingCompanyStorageConfigurationModel = await GetCompanyStorageConfigurationByIdForWriteAsync(companyStorageConfiguration.CompanyStorageConfigurationId);
                if (!existingCompanyStorageConfigurationModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>(existingCompanyStorageConfigurationModel);
                }

                companyStorageConfiguration.CreatedByUserId = existingCompanyStorageConfigurationModel.Model.CreatedByUserId;
                companyStorageConfiguration.CreatedDate = existingCompanyStorageConfigurationModel.Model.CreatedDate;
                companyStorageConfiguration.IsDeleted = existingCompanyStorageConfigurationModel.Model.IsDeleted;
                //companyStorageConfiguration.MovieId = existingCompanyStorageConfigurationModel.Model.MovieId;

                var errorList = await IsCompanyStorageConfigurationModelValidForUpdateAsync(companyStorageConfiguration);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to update companyStorageConfiguration", errorList);
                }

                var item = objectMapperService.CompanyStorageConfigurationUpdateModelToCompanyStorageConfiguration(companyStorageConfiguration);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateCompanyStorageConfigurationAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update companyStorageConfiguration");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.CompanyStorageConfigurationUpdatedAsync(companyStorageConfiguration.CompanyStorageConfigurationId, existingCompanyStorageConfigurationModel.Model, item);

                var view = await systemRepository.GetCompanyStorageConfigurationViewByIdAsync(companyStorageConfiguration.CompanyStorageConfigurationId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unable to find the companyStorageConfiguration", new { companyStorageConfiguration.CompanyStorageConfigurationId });
                }

                return this.ConvertToItem(view, objectMapperService.CompanyStorageConfigurationViewToCompanyStorageConfigurationModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<CompanyStorageConfigurationModel>($"Unexpected error when updating CompanyStorageConfiguration {companyStorageConfiguration?.CompanyStorageConfigurationId}", ex);
            }
        }

