        public async Task<List<ReturnErrorItem>> IsCompanyStorageConfigurationModelValidForAllAsync(bool isCreate, CompanyStorageConfigurationUpdateModel companyStorageConfigurationModel)
        {
            var result = new List<ReturnErrorItem>();

            await currentSessionService.GetCurrentUserIdAsync();

            if (isCreate)
            {
                if (companyStorageConfigurationModel.CompanyStorageConfigurationId > 0)
                {
                    result.Add(new ReturnErrorItem("", "CompanyStorageConfiguration Identifier is not valid"));
                }
            }
            else
            {
                if (companyStorageConfigurationModel.CompanyStorageConfigurationId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "CompanyStorageConfiguration Unique Identifier is not valid"));
                }
            }

            if (companyStorageConfigurationModel.ProfilePictureFileStorageConnectionString != null && companyStorageConfigurationModel.ProfilePictureFileStorageConnectionString.Length > CompanyStorageConfigurationModel.COLUMN_SIZE_ProfilePictureFileStorageConnectionString)
            {
                result.Add(new ReturnErrorItem("ProfilePictureFileStorageConnectionString", $"ProfilePictureFileStorageConnectionString size should not exceed {CompanyStorageConfigurationModel.COLUMN_SIZE_ProfilePictureFileStorageConnectionString}"));
            }

            if (companyStorageConfigurationModel.ReportServerFileStorageConnectionString != null && companyStorageConfigurationModel.ReportServerFileStorageConnectionString.Length > CompanyStorageConfigurationModel.COLUMN_SIZE_ReportServerFileStorageConnectionString)
            {
                result.Add(new ReturnErrorItem("ReportServerFileStorageConnectionString", $"ReportServerFileStorageConnectionString size should not exceed {CompanyStorageConfigurationModel.COLUMN_SIZE_ReportServerFileStorageConnectionString}"));
            }

            if (companyStorageConfigurationModel.FileAttachmentFileStorageConnectionString != null && companyStorageConfigurationModel.FileAttachmentFileStorageConnectionString.Length > CompanyStorageConfigurationModel.COLUMN_SIZE_FileAttachmentFileStorageConnectionString)
            {
                result.Add(new ReturnErrorItem("FileAttachmentFileStorageConnectionString", $"FileAttachmentFileStorageConnectionString size should not exceed {CompanyStorageConfigurationModel.COLUMN_SIZE_FileAttachmentFileStorageConnectionString}"));
            }

            return result.Count > 0 ? result : null;
        }

