        public async Task CreateOrUpdateCompanyStorageConfigurationDependentsAsync(CompanyStorageConfigurationModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<CompanyStorageConfigurationXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<CompanyStorageConfigurationXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetCompanyStorageConfigurationXYZZYXsByCompanyStorageConfigurationIdAsync(item.CompanyStorageConfigurationId);
            if (dbExistingXYZZYX.Result != null && dbExistingCompanyStorageConfiguration.TotalRows > 0)
            {
                var dbExistingCompanyStorageConfigurationIds = dbExistingCompanyStorageConfiguration.Result.SelectToList(x => x.CompanyStorageConfigurationXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingCompanyStorageConfigurationIds.Contains(x.CompanyStorageConfigurationXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteCompanyStorageConfigurationXYZZYXByIdAsync(x.CompanyStorageConfigurationXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingCompanyStorageConfigurationIds.Contains(x.CompanyStorageConfigurationXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.CompanyStorageConfigurationId = item.CompanyStorageConfigurationId;
                    var mappedItem = objectMapperService.CompanyStorageConfigurationXYZZYXModelToCompanyStorageConfigurationXYZZYXUpdateModel(x);
                    var result = await UpdateCompanyStorageConfigurationXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.CompanyStorageConfigurationId = item.CompanyStorageConfigurationId;
                var result = await CreateCompanyStorageConfigurationXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

