        public async Task<ReturnModel<bool>> AssociateXYZZYXWithCompanyStorageConfigurationAsync(CompanyStorageConfigurationXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsCompanyStorageConfigurationWithCompanyStorageConfigurationAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("CompanyStorageConfiguration association is invalid", errorLst);
                }

                if (await systemRepository.DoesCompanyStorageConfigurationWithXYZZYXAssociationExistsAsync(model.CompanyStorageConfigurationId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related CompanyStorageConfiguration is already associated with the CompanyStorageConfiguration", new { model.CompanyStorageConfigurationId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateCompanyStorageConfigurationWithXYZZYXAsync(model.CompanyStorageConfigurationId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate CompanyStorageConfiguration with XYZZYX", new { model.CompanyStorageConfigurationId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating CompanyStorageConfiguration with XYZZYX", new { model.CompanyStorageConfigurationId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithCompanyStorageConfigurationAsync(CompanyStorageConfigurationXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsCompanyStorageConfigurationWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("CompanyStorageConfiguration association is not valid", errorLst);
                }

                if (!await systemRepository.DoesCompanyStorageConfigurationWithXYZZYXAssociationExistsAsync(model.CompanyStorageConfigurationId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related CompanyStorageConfiguration is not associated with the CompanyStorageConfiguration", new { model.CompanyStorageConfigurationId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateCompanyStorageConfigurationWithCompanyStorageConfigurationAsync(model.CompanyStorageConfigurationId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related CompanyStorageConfiguration with the CompanyStorageConfiguration", new { model.CompanyStorageConfigurationId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related CompanyStorageConfiguration with the CompanyStorageConfiguration", new { model.CompanyStorageConfigurationId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsCompanyStorageConfigurationWithXYZZYXAssociationValidAsync(CompanyStorageConfigurationXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.CompanyStorageConfigurationId == 0)
            {
                result.Add(new ReturnErrorItem("", "CompanyStorageConfiguration is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related CompanyStorageConfiguration  is not valid"));
                return result;
            }

            var entity = await GetCompanyStorageConfigurationForWriteByIdAsync(model.CompanyStorageConfigurationId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "CompanyStorageConfiguration information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "CompanyStorageConfigurations does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

