            try
            {
                if (mailServer == null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to create Mail Server", new ReturnErrorItem("", "Mail Server information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to create Mail Server", new ReturnErrorItem("", "Only super admin can create the Mail Server Configuration"));
                }

                var ignoreCode = false;
                if (mailServer.MailServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    mailServer.MailServerCode = StringConstants.PrefixForCode.MailServer + Guid.NewGuid().ToString();
                }

                //var companyModel = await GetCompanyForReadById(mailServer.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MailServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(mailServer.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MailServerModel>(movieModel);
                //}

                var errorList = await IsMailServerModelValidForCreateAsync(mailServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to create Mail Server", errorList);
                }

                mailServer.IsDeleted = false;

                var item = objectMapperService.MailServerCreateModelToMailServer(mailServer);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateMailServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create mailServer");
                    }

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdateMailServerCodeAsync(item.MailServerId, StringConstants.PrefixForCode.MailServer + item.MailServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Mail Server Code", item);
                        }
                    }

                    await trx.CompleteAsync();
                }

                await auditService.MailServerCreatedAsync(item.MailServerId);

                var view = await systemRepository.GetMailServerByIdAsync(item.MailServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to find the Mail Server", new { item.MailServerId });
                }

                return this.ConvertToItem(view, objectMapperService.MailServerToMailServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<MailServerModel>($"Unexpected error when creating Mail Server", new { mailServer?.MailServerId }, ex);
            }
        }

        public async Task<ReturnModel<MailServerModel>> UpdateMailServerAsync(MailServerUpdateModel mailServer)
        {
            try
            {
                if (mailServer == null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to update Mail Server", new ReturnErrorItem("", "Mail Server information is not valid"));
                }

                var existingMailServerModel = await GetMailServerByIdForWriteAsync(mailServer.MailServerId);
                if (!existingMailServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MailServerModel>(existingMailServerModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<MailServerModel>("You dont have access to this resource.");
                }

                mailServer.CreatedByUserId = existingMailServerModel.Model.CreatedByUserId;
                mailServer.CreatedDate = existingMailServerModel.Model.CreatedDate;
                mailServer.IsDeleted = existingMailServerModel.Model.IsDeleted;
                mailServer.MailServerCode = existingMailServerModel.Model.MailServerCode;

                var errorList = await IsMailServerModelValidForUpdateAsync(mailServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to update Mail Server", errorList);
                }

                var item = objectMapperService.MailServerUpdateModelToMailServer(mailServer);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateMailServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Mail Server");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.MailServerUpdatedAsync(mailServer.MailServerId, existingMailServerModel.Model, item);

                var view = await systemRepository.GetMailServerByIdAsync(mailServer.MailServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MailServerModel>($"Unable to find the Mail Server", new { mailServer.MailServerId });
                }

                return this.ConvertToItem(view, objectMapperService.MailServerToMailServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<MailServerModel>($"Unexpected error when updating Mail Server", new { mailServer?.MailServerId }, ex);
            }
        }

