        public async Task<List<ReturnErrorItem>> IsMailServerModelValidForAllAsync(bool isCreate, MailServerUpdateModel mailServerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (mailServerModel.MailServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Mail Server Identifier is not valid"));
                }
            }
            else
            {
                if (mailServerModel.MailServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Mail Server Unique Identifier is not valid"));
                }
            }

            if (mailServerModel.MailServerName != null && mailServerModel.MailServerName.Length > MailServerModel.COLUMN_SIZE_MailServerName)
            {
                result.Add(new ReturnErrorItem("MailServerName", $"Mail Server Name size should not exceed {MailServerModel.COLUMN_SIZE_MailServerName}"));
            }
            else if (mailServerModel.MailServerName == null)
            {
                result.Add(new ReturnErrorItem("MailServerName", "Mail Server Name is required "));
            }

            if (mailServerModel.Host != null && mailServerModel.Host.Length > MailServerModel.COLUMN_SIZE_Host)
            {
                result.Add(new ReturnErrorItem("Host", $"Host size should not exceed {MailServerModel.COLUMN_SIZE_Host}"));
            }
            else if (mailServerModel.Host == null)
            {
                result.Add(new ReturnErrorItem("Host", "Host is required "));
            }

            if (mailServerModel.SenderName != null && mailServerModel.SenderName.Length > MailServerModel.COLUMN_SIZE_SenderName)
            {
                result.Add(new ReturnErrorItem("SenderName", $"Sender Name size should not exceed {MailServerModel.COLUMN_SIZE_SenderName}"));
            }

            if (mailServerModel.SenderName == null)
            {
                result.Add(new ReturnErrorItem("SenderName", "Sender Name is required "));
            }

            if (mailServerModel.SenderEmail != null && mailServerModel.SenderEmail.Length > MailServerModel.COLUMN_SIZE_SenderEmail)
            {
                result.Add(new ReturnErrorItem("SenderEmail", $"Sender Email size should not exceed {MailServerModel.COLUMN_SIZE_SenderEmail}"));
            }

            if (mailServerModel.SenderEmail == null)
            {
                result.Add(new ReturnErrorItem("SenderEmail", "Sender Email is required "));
            }

            if (mailServerModel.UserName != null && mailServerModel.UserName.Length > MailServerModel.COLUMN_SIZE_UserName)
            {
                result.Add(new ReturnErrorItem("UserName", $"User Name size should not exceed {MailServerModel.COLUMN_SIZE_UserName}"));
            }

            if (mailServerModel.UserName == null)
            {
                result.Add(new ReturnErrorItem("UserName", "User Name is required "));
            }

            if (mailServerModel.Password != null && mailServerModel.Password.Length > MailServerModel.COLUMN_SIZE_Password)
            {
                result.Add(new ReturnErrorItem("Password", $"Password size should not exceed {MailServerModel.COLUMN_SIZE_Password}"));
            }

            if (await systemRepository.IsMailServerAlreadyExistsByMailServerNameAsync(mailServerModel.MailServerId, mailServerModel.MailServerName))
            {
                result.Add(new ReturnErrorItem("MailServerName", $"Mail Server with same name {mailServerModel.MailServerName} already exists {MailServerModel.COLUMN_SIZE_Password}"));
            }

            var existingDefaultServer = await systemRepository.GetDefaultMailServerAsync();

            if (existingDefaultServer != null && mailServerModel.IsDefault && (existingDefaultServer?.MailServerId ?? 0) != mailServerModel.MailServerId)
            {
                result.Add(new ReturnErrorItem("IsDefault", $"Default Mail Server already exists"));
            }

            return result.Count > 0 ? result : null;
        }

