        public async Task CreateOrUpdateMailServerDependentsAsync(MailServerModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<MailServerXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<MailServerXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetMailServerXYZZYXsByMailServerIdAsync(item.MailServerId);
            if (dbExistingXYZZYX.Result != null && dbExistingMailServer.TotalRows > 0)
            {
                var dbExistingMailServerIds = dbExistingMailServer.Result.SelectToList(x => x.MailServerXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingMailServerIds.Contains(x.MailServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteMailServerXYZZYXByIdAsync(x.MailServerXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingMailServerIds.Contains(x.MailServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.MailServerId = item.MailServerId;
                    var mappedItem = objectMapperService.MailServerXYZZYXModelToMailServerXYZZYXUpdateModel(x);
                    var result = await UpdateMailServerXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.MailServerId = item.MailServerId;
                var result = await CreateMailServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

