        public async Task<ReturnModel<bool>> AssociateXYZZYXWithMailServerAsync(MailServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMailServerWithMailServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("MailServer association is invalid", errorLst);
                }

                if (await systemRepository.DoesMailServerWithXYZZYXAssociationExistsAsync(model.MailServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related MailServer is already associated with the MailServer", new { model.MailServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateMailServerWithXYZZYXAsync(model.MailServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate MailServer with XYZZYX", new { model.MailServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating MailServer with XYZZYX", new { model.MailServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithMailServerAsync(MailServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMailServerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("MailServer association is not valid", errorLst);
                }

                if (!await systemRepository.DoesMailServerWithXYZZYXAssociationExistsAsync(model.MailServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related MailServer is not associated with the MailServer", new { model.MailServerId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateMailServerWithMailServerAsync(model.MailServerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related MailServer with the MailServer", new { model.MailServerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related MailServer with the MailServer", new { model.MailServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsMailServerWithXYZZYXAssociationValidAsync(MailServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.MailServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "MailServer is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related MailServer  is not valid"));
                return result;
            }

            var entity = await GetMailServerForWriteByIdAsync(model.MailServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "MailServer information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "MailServers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportMailServerAsync(MailServerImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("MailServer Info is not provided");
                }

                if (model.MailServers == null || model.MailServers.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("MailServers Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.MailServers)
                {
                    var prod = await wipService.GetMailServerByExternalIdentifierAsync(item.MailServerIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        MailServerCreateModel mailServerCreateModel = new MailServerCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedMailServer = await CreateMailServerAsync(mailServerCreateModel);
                        if (!newlyCreatedMailServer.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedMailServer.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedMailServer.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        MailServerUpdateModel mailServerUpdateModel = new MailServerUpdateModel
                        {
                        };

                        //update product
                        var updatedMailServerModel = await wipService.UpdateMailServerAsync(mailServerUpdateModel);
                        if (!updatedMailServerModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

