        public async Task<ReturnModel<SmsServerModel>> CreateSmsServerAsync(SmsServerCreateModel smsServer)
        {
            try
            {
                if (smsServer == null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to create Sms Server", new ReturnErrorItem("", "Sms Server information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to create Sms Server", new ReturnErrorItem("", "Only super admin can create the Sms Server Configuration"));
                }

                var ignoreCode = false;
                if (smsServer.SmsServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    smsServer.SmsServerCode = StringConstants.PrefixForCode.SmsServer + Guid.NewGuid().ToString();
                }

                //var companyModel = await GetCompanyForReadById(smsServer.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SmsServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(smsServer.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SmsServerModel>(movieModel);
                //}

                var errorList = await IsSmsServerModelValidForCreateAsync(smsServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to create Sms Server", errorList);
                }

                smsServer.IsDeleted = false;

                var item = objectMapperService.SmsServerCreateModelToSmsServer(smsServer);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateSmsServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create smsServer");
                    }

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdateSmsServerCodeAsync(item.SmsServerId, StringConstants.PrefixForCode.SmsServer + item.SmsServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Sms Server Code", item);
                        }
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SmsServerCreatedAsync(item.SmsServerId);

                var view = await systemRepository.GetSmsServerByIdAsync(item.SmsServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to find the Sms Server", new { item.SmsServerId });
                }

                return this.ConvertToItem(view, objectMapperService.SmsServerToSmsServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<SmsServerModel>($"Unexpected error when creating Sms Server", new { smsServer?.SmsServerId }, ex);
            }
        }

        public async Task<ReturnModel<SmsServerModel>> UpdateSmsServerAsync(SmsServerUpdateModel smsServer)
        {
            try
            {
                if (smsServer == null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to update Sms Server", new ReturnErrorItem("", "Sms Server information is not valid"));
                }

                var existingSmsServerModel = await GetSmsServerByIdForWriteAsync(smsServer.SmsServerId);
                if (!existingSmsServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>(existingSmsServerModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<SmsServerModel>("You dont have access to this resource.");
                }

                smsServer.CreatedByUserId = existingSmsServerModel.Model.CreatedByUserId;
                smsServer.CreatedDate = existingSmsServerModel.Model.CreatedDate;
                smsServer.IsDeleted = existingSmsServerModel.Model.IsDeleted;
                smsServer.SmsServerCode = existingSmsServerModel.Model.SmsServerCode;

                var errorList = await IsSmsServerModelValidForUpdateAsync(smsServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to update Sms Server", errorList);
                }

                var item = objectMapperService.SmsServerUpdateModelToSmsServer(smsServer);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateSmsServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Sms Server");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.SmsServerUpdatedAsync(smsServer.SmsServerId, existingSmsServerModel.Model, item);

                var view = await systemRepository.GetSmsServerByIdAsync(smsServer.SmsServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SmsServerModel>($"Unable to find the Sms Server", new { smsServer.SmsServerId });
                }

                return this.ConvertToItem(view, objectMapperService.SmsServerToSmsServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<SmsServerModel>($"Unexpected error when updating Sms Server", new { smsServer?.SmsServerId }, ex);
            }
        }

