        public async Task<List<ReturnErrorItem>> IsSmsServerModelValidForAllAsync(bool isCreate, SmsServerUpdateModel smsServerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (smsServerModel.SmsServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Sms Server Identifier is not valid"));
                }
            }
            else
            {
                if (smsServerModel.SmsServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Sms Server Unique Identifier is not valid"));
                }
            }

            if (smsServerModel.SmsServerName != null && smsServerModel.SmsServerName.Length > SmsServerModel.COLUMN_SIZE_SmsServerName)
            {
                result.Add(new ReturnErrorItem("SmsServerName", $"Sms Server Name size should not exceed {SmsServerModel.COLUMN_SIZE_SmsServerName}"));
            }
            else if (smsServerModel.SmsServerName == null)
            {
                result.Add(new ReturnErrorItem("SmsServerName", "Sms Server Name is required "));
            }

            if (smsServerModel.Host != null && smsServerModel.Host.Length > SmsServerModel.COLUMN_SIZE_Host)
            {
                result.Add(new ReturnErrorItem("Host", $"Host size should not exceed {SmsServerModel.COLUMN_SIZE_Host}"));
            }
            else if (smsServerModel.Host == null)
            {
                result.Add(new ReturnErrorItem("Host", "Host is required "));
            }

            if (smsServerModel.SenderName != null && smsServerModel.SenderName.Length > SmsServerModel.COLUMN_SIZE_SenderName)
            {
                result.Add(new ReturnErrorItem("SenderName", $"Sender Name size should not exceed {SmsServerModel.COLUMN_SIZE_SenderName}"));
            }

            if (smsServerModel.SenderName == null)
            {
                result.Add(new ReturnErrorItem("SenderName", "Sender Name is required "));
            }

            if (smsServerModel.SenderEmail != null && smsServerModel.SenderEmail.Length > SmsServerModel.COLUMN_SIZE_SenderEmail)
            {
                result.Add(new ReturnErrorItem("SenderEmail", $"Sender Email size should not exceed {SmsServerModel.COLUMN_SIZE_SenderEmail}"));
            }

            if (smsServerModel.SenderEmail == null)
            {
                result.Add(new ReturnErrorItem("SenderEmail", "Sender Email is required "));
            }

            if (smsServerModel.UserName != null && smsServerModel.UserName.Length > SmsServerModel.COLUMN_SIZE_UserName)
            {
                result.Add(new ReturnErrorItem("UserName", $"User Name size should not exceed {SmsServerModel.COLUMN_SIZE_UserName}"));
            }

            if (smsServerModel.UserName == null)
            {
                result.Add(new ReturnErrorItem("UserName", "User Name is required "));
            }

            if (smsServerModel.Password != null && smsServerModel.Password.Length > SmsServerModel.COLUMN_SIZE_Password)
            {
                result.Add(new ReturnErrorItem("Password", $"Password size should not exceed {SmsServerModel.COLUMN_SIZE_Password}"));
            }

            if (await systemRepository.IsSmsServerAlreadyExistsBySmsServerNameAsync(smsServerModel.SmsServerId, smsServerModel.SmsServerName))
            {
                result.Add(new ReturnErrorItem("SmsServerName", $"Sms Server with same name {smsServerModel.SmsServerName} already exists {SmsServerModel.COLUMN_SIZE_Password}"));
            }

            var existingDefaultSmsServer = await systemRepository.GetDefaultSmsServerAsync();
            if (existingDefaultSmsServer != null && smsServerModel.IsDefault && (existingDefaultSmsServer?.SmsServerId ?? 0) != smsServerModel.SmsServerId)
            {
                result.Add(new ReturnErrorItem("IsDefault", $"Default Sms Server already exists"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedSmsAndVoiceServerTypes,long>(smsServerModel.PredefinedSmsAndVoiceServerTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedSmsAndVoiceServerTypeId", $"Sms Server Type is not valid"));
            }

            return result.Count > 0 ? result : null;
        }

