        public async Task CreateOrUpdateSmsServerDependentsAsync(SmsServerModel model)
        {
            if (model.NewXYZZYXs == null)
                model.NewXYZZYXs = new List<SmsServerXYZZYXCreateModel>();

            if (model.ExistingXYZZYXs == null)
                model.ExistingXYZZYXs = new List<SmsServerXYZZYXModel>();

            var dbExistingXYZZYX = await systemRepository.GetSmsServerXYZZYXsBySmsServerIdAsync(item.SmsServerId);
            if (dbExistingXYZZYX.Result != null && dbExistingSmsServer.TotalRows > 0)
            {
                var dbExistingSmsServerIds = dbExistingSmsServer.Result.SelectToList(x => x.SmsServerXYZZYXId);

                var xYZZYXItemsToDelete = model.ExistingXYZZYXs.Where(x => !dbExistingSmsServerIds.Contains(x.SmsServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await systemRepository.HardDeleteSmsServerXYZZYXByIdAsync(x.SmsServerXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingXYZZYXs.Where(x => dbExistingSmsServerIds.Contains(x.SmsServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.SmsServerId = item.SmsServerId;
                    var mappedItem = objectMapperService.SmsServerXYZZYXModelToSmsServerXYZZYXUpdateModel(x);
                    var result = await UpdateSmsServerXYZZYXAsync(mappedItem);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in item.NewXYZZYXs)
            {
                x.SmsServerId = item.SmsServerId;
                var result = await CreateSmsServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

