        public async Task<ReturnModel<bool>> AssociateXYZZYXWithSmsServerAsync(SmsServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSmsServerWithSmsServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SmsServer association is invalid", errorLst);
                }

                if (await systemRepository.DoesSmsServerWithXYZZYXAssociationExistsAsync(model.SmsServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related SmsServer is already associated with the SmsServer", new { model.SmsServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateSmsServerWithXYZZYXAsync(model.SmsServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate SmsServer with XYZZYX", new { model.SmsServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating SmsServer with XYZZYX", new { model.SmsServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithSmsServerAsync(SmsServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSmsServerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("SmsServer association is not valid", errorLst);
                }

                if (!await systemRepository.DoesSmsServerWithXYZZYXAssociationExistsAsync(model.SmsServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related SmsServer is not associated with the SmsServer", new { model.SmsServerId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateSmsServerWithSmsServerAsync(model.SmsServerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related SmsServer with the SmsServer", new { model.SmsServerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related SmsServer with the SmsServer", new { model.SmsServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsSmsServerWithXYZZYXAssociationValidAsync(SmsServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.SmsServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "SmsServer is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related SmsServer  is not valid"));
                return result;
            }

            var entity = await GetSmsServerForWriteByIdAsync(model.SmsServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "SmsServer information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "SmsServers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

