        public async Task<ReturnListModel<PushNotificationServerModel>> CreateMultiplePushNotificationServerAsync(MultiplePushNotificationServerCreateModel pushNotificationConfigurations)
        {
            try
            {
                if (pushNotificationConfigurations == null)
                {
                    return log.ErrorAndReturnListModel<PushNotificationServerModel>($"Unable to Create Push Notification Configurations", new ReturnErrorItem("", "Push Notification Configurations information is not valid"));
                }

                if (pushNotificationConfigurations.NewPushNotificationServers.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<PushNotificationServerModel>($"Unable to Create Push Notification Configurations", new ReturnErrorItem("", "Push Notification Configurations information is not provided"));
                }

                var lst = new List<PushNotificationServerModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var pushNotificationConfiguration in pushNotificationConfigurations.NewPushNotificationServers)
                    {
                        var cResult = await CreatePushNotificationServerAsync(pushNotificationConfiguration);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<PushNotificationServerModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<PushNotificationServerModel>($"Unexpected error when creating Push Notification Configurations", new { pushNotificationConfigurations }, ex);
            }
        }

        public async Task<ReturnModel<PushNotificationServerModel>> CreatePushNotificationServerAsync(PushNotificationServerCreateModel pushNotificationConfiguration)
        {
            try
            {
                if (pushNotificationConfiguration == null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to create Push Notification Configuration", new ReturnErrorItem("", "Push Notification Configuration information is not valid"));
                }

                //if (!await permissionService.IsUserSuperAdmin())
                //{
                //    pushNotificationConfiguration.CompanyId = await currentSessionService.GetCurrentCompanyIdAsync() ?? 0;
                //}

                //var companyModel = await companyService.GetCompanyByIdForReadAsync(pushNotificationConfiguration.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<PushNotificationServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieByIdForReadAsync(pushNotificationConfiguration.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<PushNotificationServerModel>(movieModel);
                //}

                var ignoreCode = false;
                if (pushNotificationConfiguration.PushNotificationServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    pushNotificationConfiguration.PushNotificationServerCode = StringConstants.PrefixForCode.PushNotificationServer + Guid.NewGuid().ToString();
                }

                var errorList = await IsPushNotificationServerModelValidForCreateAsync(pushNotificationConfiguration);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to create Push Notification Configuration", errorList);
                }

                pushNotificationConfiguration.IsDeleted = false;

                var item = objectMapperService.PushNotificationServerCreateModelToPushNotificationServer(pushNotificationConfiguration);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreatePushNotificationServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Push Notification Configuration");
                    }

                    //await CreateOrUpdatePushNotificationServerDependentsAsync(pushNotificationConfiguration)

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdatePushNotificationServerCodeAsync(item.PushNotificationServerId, StringConstants.PrefixForCode.PushNotificationServer + item.PushNotificationServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Push Notification Configuration Code", item);
                        }
                    }

                    await trx.CompleteAsync();
                }

                await auditService.PushNotificationServerCreatedAsync(item.PushNotificationServerId);

                var view = await systemRepository.GetPushNotificationServerViewByIdAsync(item.PushNotificationServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to find the Push Notification Configuration", new { item.PushNotificationServerId });
                }

                return this.ConvertToItem(view, objectMapperService.PushNotificationServerViewToPushNotificationServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<PushNotificationServerModel>($"Unexpected error when creating Push Notification Configuration", new { pushNotificationConfiguration?.PushNotificationServerId }, ex);
            }
        }

        public async Task<ReturnModel<PushNotificationServerModel>> UpdatePushNotificationServerAsync(PushNotificationServerUpdateModel pushNotificationConfiguration)
        {
            try
            {
                if (pushNotificationConfiguration == null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to update Push Notification Configuration", new ReturnErrorItem("", "Push Notification Configuration information is not valid"));
                }

                var existingPushNotificationServerModel = await GetPushNotificationServerByIdForWriteAsync(pushNotificationConfiguration.PushNotificationServerId);
                if (!existingPushNotificationServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>(existingPushNotificationServerModel);
                }

                //var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(pushNotificationConfiguration.CompanyId);

                //if (resultValue == false)
                //{
                //    return log.ErrorAndReturnModel<PushNotificationServerModel>(errorStr);
                //}

                //if (canAssign)
                //{
                //    pushNotificationConfiguration.CompanyId = await currentSessionService.GetCurrentCompanyIdAsync() ?? 0;
                //}

                pushNotificationConfiguration.CreatedByUserId = existingPushNotificationServerModel.Model.CreatedByUserId;
                pushNotificationConfiguration.CreatedDate = existingPushNotificationServerModel.Model.CreatedDate;
                pushNotificationConfiguration.IsDeleted = existingPushNotificationServerModel.Model.IsDeleted;
                //pushNotificationConfiguration.CompanyId = existingPushNotificationServerModel.Model.CompanyId;
                //pushNotificationConfiguration.MovieId = existingPushNotificationServerModel.Model.MovieId;
                //pushNotificationConfiguration.ProfileImageActualFileName = existingPushNotificationServerModel.Model.ProfileImageActualFileName;
                //pushNotificationConfiguration.ProfileImageLocation = existingPushNotificationServerModel.Model.ProfileImageLocation;

                var errorList = await IsPushNotificationServerModelValidForUpdateAsync(pushNotificationConfiguration);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to update Push Notification Configuration", errorList);
                }

                var item = objectMapperService.PushNotificationServerUpdateModelToPushNotificationServer(pushNotificationConfiguration);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdatePushNotificationServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Push Notification Configuration");
                    }

                    //await CreateOrUpdatePushNotificationServerDependentsAsync(pushNotificationConfiguration)

                    await trx.CompleteAsync();
                }

                await auditService.PushNotificationServerUpdatedAsync(pushNotificationConfiguration.PushNotificationServerId);

                var view = await systemRepository.GetPushNotificationServerViewByIdAsync(pushNotificationConfiguration.PushNotificationServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unable to find the Push Notification Configuration", new { pushNotificationConfiguration.PushNotificationServerId });
                }

                return this.ConvertToItem(view, objectMapperService.PushNotificationServerViewToPushNotificationServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<PushNotificationServerModel>($"Unexpected error when updating Push Notification Configuration", new { pushNotificationConfiguration?.PushNotificationServerId }, ex);
            }
        }

