        public async Task<List<ReturnErrorItem>> IsPushNotificationServerModelValidForAllAsync(bool isCreate, PushNotificationServerUpdateModel pushNotificationConfigurationModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsPushNotificationServerNameAlreadyExistsForOtherPushNotificationServerAsync(pushNotificationConfigurationModel.PushNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Push Notification Configuration already exists"));
                }

                if (pushNotificationConfigurationModel.PushNotificationServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Push Notification Configuration Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsPushNotificationServerNameAlreadyExistsForOtherPushNotificationServerAsync(pushNotificationConfigurationModel.PushNotificationServerId, pushNotificationConfigurationModel.PushNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Push Notification Configuration already exists"));
                }

                if (pushNotificationConfigurationModel.PushNotificationServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Push Notification Configuration Unique Identifier is not valid"));
                }
            }

            if (!ValidationUtils.IsLongValid(pushNotificationConfigurationModel.PredefinedPushNotificationServerTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedPushNotificationServerTypeId", "PredefinedPushNotificationServerTypeId cannot be empty"));
            }

            //var itemForPushNotificationServiceProviderType = await systemRepository.GetPushNotificationServiceProviderTypeByIdAsync(pushNotificationConfigurationModel.PushNotificationServiceProviderTypeId);
            //if (itemForPushNotificationServiceProviderType == null)
            //{
            //    result.Add(new ReturnErrorItem("PushNotificationServiceProviderTypeId", "PushNotificationServiceProviderType is not available"));
            //}
            //else
            //{
            //    if (itemForPushNotificationServiceProviderType.CompanyId != pushNotificationConfigurationModel.CompanyId)
            //    {
            //        result.Add(new ReturnErrorItem("PushNotificationServiceProviderTypeId", "PushNotificationServiceProviderType does not belong to you."));
            //    }
            //}

            if (pushNotificationConfigurationModel.ProjectId != null && pushNotificationConfigurationModel.ProjectId.Length > PushNotificationServerModel.COLUMN_SIZE_ProjectId)
            {
                result.Add(new ReturnErrorItem("ProjectId", $"ProjectId size should not exceed {PushNotificationServerModel.COLUMN_SIZE_ProjectId}"));
            }

            if (pushNotificationConfigurationModel.ApiKey != null && pushNotificationConfigurationModel.ApiKey.Length > PushNotificationServerModel.COLUMN_SIZE_ApiKey)
            {
                result.Add(new ReturnErrorItem("ApiKey", $"ApiKey size should not exceed {PushNotificationServerModel.COLUMN_SIZE_ApiKey}"));
            }

            if (pushNotificationConfigurationModel.ApiSecret != null && pushNotificationConfigurationModel.ApiSecret.Length > PushNotificationServerModel.COLUMN_SIZE_ApiSecret)
            {
                result.Add(new ReturnErrorItem("ApiSecret", $"ApiSecret size should not exceed {PushNotificationServerModel.COLUMN_SIZE_ApiSecret}"));
            }

            if (pushNotificationConfigurationModel.AppleTeamId != null && pushNotificationConfigurationModel.AppleTeamId.Length > PushNotificationServerModel.COLUMN_SIZE_AppleTeamId)
            {
                result.Add(new ReturnErrorItem("AppleTeamId", $"AppleTeamId size should not exceed {PushNotificationServerModel.COLUMN_SIZE_AppleTeamId}"));
            }

            if (pushNotificationConfigurationModel.AppleKeyId != null && pushNotificationConfigurationModel.AppleKeyId.Length > PushNotificationServerModel.COLUMN_SIZE_AppleKeyId)
            {
                result.Add(new ReturnErrorItem("AppleKeyId", $"AppleKeyId size should not exceed {PushNotificationServerModel.COLUMN_SIZE_AppleKeyId}"));
            }

            if (pushNotificationConfigurationModel.AppleAuthKey != null && pushNotificationConfigurationModel.AppleAuthKey.Length > PushNotificationServerModel.COLUMN_SIZE_AppleAuthKey)
            {
                result.Add(new ReturnErrorItem("AppleAuthKey", $"AppleAuthKey size should not exceed {PushNotificationServerModel.COLUMN_SIZE_AppleAuthKey}"));
            }

            return result.Count > 0 ? result : null;
        }

