            try
            {
                var fileModel = await GetPushNotificationServerFileAsync(pushNotificationConfigurationId);
                if (!fileModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>($"Unexpected error when getting the Push Notification Configuration file", fileModel.ErrorHolder);
                }

                FileUtils.CloseSafely(fileModel.Model.FileData);
                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when getting the Push Notification Configuration file", ex);
            }
        }

        public async Task<ReturnModel<FileStreamModel>> GetPushNotificationServerFileAsync(long pushNotificationConfigurationId)
        {
            try
            {
                var view = await GetPushNotificationServerByIdForReadAsync(pushNotificationConfigurationId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the Push Notification Configuration", new { pushNotificationConfigurationId });
                }

                var fileName = view.Model.SourceStoredFilePath;

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.CompanyId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"PushNotificationServerFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.CompanyId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for Push Notification Configuration ", new { pushNotificationConfigurationId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UploadPushNotificationServerFileAsync(long pushNotificationConfigurationId, FileStreamModel streamModel)
        {
            try
            {
                var pushNotificationConfiguration = await GetPushNotificationServerByIdForWriteAsync(pushNotificationConfigurationId);
                if (!pushNotificationConfiguration.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(pushNotificationConfiguration);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(pushNotificationConfiguration.Model.CompanyId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(pushNotificationConfiguration.Model.CompanyId, pushNotificationConfiguration.Model.PushNotificationServerId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(pushNotificationConfiguration.Model.CompanyId, pushNotificationConfiguration.Model.PushNotificationServerId, streamModel.FileName);
                        await productRepository.UpdatePushNotificationServerFilePathAsync(pushNotificationConfiguration.Model.PushNotificationServerId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(pushNotificationConfiguration.Model.CompanyId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Push Notification Configuration File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearPushNotificationServerFileAsync(long pushNotificationConfigurationId)
        {
            try
            {
                var pushNotificationConfiguration = await GetPushNotificationServerByIdForWriteAsync(pushNotificationConfigurationId);
                if (!pushNotificationConfiguration.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(pushNotificationConfiguration);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearPushNotificationServerFilePathAsync(pushNotificationConfiguration.Model.PushNotificationServerId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(pushNotificationConfiguration.Model.CompanyId, pushNotificationConfiguration.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Push Notification Configuration File", ex);
            }
        }

        public async Task CreateOrUpdatePushNotificationServerDependentsAsync(PushNotificationServerUpdateModel model)
        {
            if (model.NewPushNotificationServerXYZZYXModels == null)
                model.NewPushNotificationServerXYZZYXModels = new List<PushNotificationServerXYZZYXCreateModel>();

            if (model.ExistingPushNotificationServerXYZZYXModels == null)
                model.ExistingPushNotificationServerXYZZYXModels = new List<PushNotificationServerXYZZYXUpdateModel>();

            var dbExistingPushNotificationServers = await systemRepository.GetPushNotificationServerXYZZYXsByPushNotificationServerIdAsync(model.PushNotificationServerId);
            if (!dbExistingPushNotificationServers.IsNullOrEmpty())
            {
                var dbExistingPushNotificationServerIds = dbExistingPushNotificationServers.SelectToList(x => x.PushNotificationServerXYZZYXId);
                var modelExistingPushNotificationServerIds = model.ExistingPushNotificationServerXYZZYXModels.SelectToList(x => x.PushNotificationServerXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingPushNotificationServers.Where(x => !modelExistingPushNotificationServerIds.Contains(x.PushNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkPushNotificationServerXYZZYXAsDeletedByIdAsync(x.PushNotificationServerXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingPushNotificationServerXYZZYXModels.Where(x => dbExistingPushNotificationServerIds.Contains(x.PushNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.PushNotificationServerId = model.PushNotificationServerId;
                    var result = await UpdatePushNotificationServerXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewPushNotificationServerXYZZYXModels)
            {
                x.PushNotificationServerId = model.PushNotificationServerId;
                var result = await CreatePushNotificationServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

