        public async Task<ReturnModel<bool>> AssociateXYZZYXWithPushNotificationServerAsync(PushNotificationServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsPushNotificationServerWithPushNotificationServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Push Notification Configuration association is invalid", errorLst);
                }

                if (await systemRepository.DoesPushNotificationServerWithXYZZYXAssociationExistsAsync(model.PushNotificationServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Push Notification Configuration is already associated with the Push Notification Configuration", new { model.PushNotificationServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociatePushNotificationServerWithXYZZYXAsync(model.PushNotificationServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Push Notification Configuration with XYZZYX", new { model.PushNotificationServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Push Notification Configuration with XYZZYX", new { model.PushNotificationServerId, model.XYZZYXId }, ex);
            }
        }

