        public async Task<List<ReturnErrorItem>> IsPushNotificationServerWithXYZZYXAssociationValidAsync(PushNotificationServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.PushNotificationServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Push Notification Configuration is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Push Notification Configuration  is not valid"));
                return result;
            }

            var entity = await GetPushNotificationServerForWriteByIdAsync(model.PushNotificationServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Push Notification Configuration information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Push Notification Configurations does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

