        public async Task<ReturnListModel<VoiceNotificationServerModel>> CreateMultipleVoiceNotificationServerAsync(MultipleVoiceNotificationServerCreateModel voiceNotificationServers)
        {
            try
            {
                if (voiceNotificationServers == null)
                {
                    return log.ErrorAndReturnListModel<VoiceNotificationServerModel>($"Unable to Create Voice Notification Servers", new ReturnErrorItem("", "Voice Notification Servers information is not valid"));
                }

                if (voiceNotificationServers.NewVoiceNotificationServers.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<VoiceNotificationServerModel>($"Unable to Create Voice Notification Servers", new ReturnErrorItem("", "Voice Notification Servers information is not provided"));
                }

                var lst = new List<VoiceNotificationServerModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var voiceNotificationServer in voiceNotificationServers.NewVoiceNotificationServers)
                    {
                        var cResult = await CreateVoiceNotificationServerAsync(voiceNotificationServer);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<VoiceNotificationServerModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<VoiceNotificationServerModel>($"Unexpected error when creating Voice Notification Servers", new { voiceNotificationServers }, ex);
            }
        }

        public async Task<ReturnModel<VoiceNotificationServerModel>> CreateVoiceNotificationServerAsync(VoiceNotificationServerCreateModel voiceNotificationServer)
        {
            try
            {
                if (voiceNotificationServer == null)
                {
                    return log.ErrorAndReturnModel<VoiceNotificationServerModel>($"Unable to create Voice Notification Server", new ReturnErrorItem("", "Voice Notification Server information is not valid"));
                }

                //if (!await permissionService.IsUserSuperAdmin())
                //{
                //    voiceNotificationServer.CompanyId = await currentSessionService.GetCurrentCompanyIdAsync() ?? 0;
                //}

                //var companyModel = await companyService.GetCompanyByIdForReadAsync(voiceNotificationServer.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<VoiceNotificationServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieByIdForReadAsync(voiceNotificationServer.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<VoiceNotificationServerModel>(movieModel);
                //}

                var ignoreCode = false;
                if (voiceNotificationServer.VoiceNotificationServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    voiceNotificationServer.VoiceNotificationServerCode = StringConstants.PrefixForCode.VoiceNotificationServer + Guid.NewGuid().ToString();
                }

                var errorList = await IsVoiceNotificationServerModelValidForCreateAsync(voiceNotificationServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<VoiceNotificationServerModel>($"Unable to create Voice Notification Server", errorList);
                }

                voiceNotificationServer.IsDeleted = false;

                var item = objectMapperService.VoiceNotificationServerCreateModelToVoiceNotificationServer(voiceNotificationServer);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateVoiceNotificationServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Voice Notification Server");
                    }

                    //await CreateOrUpdateVoiceNotificationServerDependentsAsync(voiceNotificationServer)

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdateVoiceNotificationServerCodeAsync(item.VoiceNotificationServerId, StringConstants.PrefixForCode.VoiceNotificationServer + item.VoiceNotificationServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Voice Notification Server Code", item);
                        }
                    }

                    await trx.CompleteAsync();
                }

                await auditService.VoiceNotificationServerCreatedAsync(item.VoiceNotificationServerId);

                var view = await systemRepository.GetVoiceNotificationServerViewByIdAsync(item.VoiceNotificationServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<VoiceNotificationServerModel>($"Unable to find the Voice Notification Server", new { item.VoiceNotificationServerId });
                }

                return this.ConvertToItem(view, objectMapperService.VoiceNotificationServerViewToVoiceNotificationServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<VoiceNotificationServerModel>($"Unexpected error when creating Voice Notification Server", new { voiceNotificationServer?.VoiceNotificationServerId }, ex);
            }
        }

