        public async Task<List<ReturnErrorItem>> IsVoiceNotificationServerModelValidForAllAsync(bool isCreate, VoiceNotificationServerUpdateModel voiceNotificationServerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsVoiceNotificationServerNameAlreadyExistsForOtherVoiceNotificationServerAsync(voiceNotificationServerModel.VoiceNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Voice Notification Server already exists"));
                }

                if (voiceNotificationServerModel.VoiceNotificationServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Voice Notification Server Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsVoiceNotificationServerNameAlreadyExistsForOtherVoiceNotificationServerAsync(voiceNotificationServerModel.VoiceNotificationServerId, voiceNotificationServerModel.VoiceNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Voice Notification Server already exists"));
                }

                if (voiceNotificationServerModel.VoiceNotificationServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Voice Notification Server Unique Identifier is not valid"));
                }
            }

            if (voiceNotificationServerModel.PredefinedSmsAndVoiceServerTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedSmsAndVoiceServerTypeId", "PredefinedSmsAndVoiceServerTypeId cannot be empty"));
            }

            if (voiceNotificationServerModel.TwilioAccountSid != null && voiceNotificationServerModel.TwilioAccountSid.Length > VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountSid)
            {
                result.Add(new ReturnErrorItem("TwilioAccountSid", $"TwilioAccountSid size should not exceed {VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountSid}"));
            }

            if (voiceNotificationServerModel.TwilioAccountAuthToken != null && voiceNotificationServerModel.TwilioAccountAuthToken.Length > VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountAuthToken)
            {
                result.Add(new ReturnErrorItem("TwilioAccountAuthToken", $"TwilioAccountAuthToken size should not exceed {VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountAuthToken}"));
            }

            if (voiceNotificationServerModel.TwilioAccountPhoneNumber != null && voiceNotificationServerModel.TwilioAccountPhoneNumber.Length > VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountPhoneNumber)
            {
                result.Add(new ReturnErrorItem("TwilioAccountPhoneNumber", $"TwilioAccountPhoneNumber size should not exceed {VoiceNotificationServerModel.COLUMN_SIZE_TwilioAccountPhoneNumber}"));
            }

            return result.Count > 0 ? result : null;
        }

