        public async Task<ReturnModel<bool>> UploadVoiceNotificationServerFileAsync(long voiceNotificationServerId, FileStreamModel streamModel)
        {
            try
            {
                var voiceNotificationServer = await GetVoiceNotificationServerByIdForWriteAsync(voiceNotificationServerId);
                if (!voiceNotificationServer.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(voiceNotificationServer);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(voiceNotificationServer.Model.CompanyId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(voiceNotificationServer.Model.CompanyId, voiceNotificationServer.Model.VoiceNotificationServerId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(voiceNotificationServer.Model.CompanyId, voiceNotificationServer.Model.VoiceNotificationServerId, streamModel.FileName);
                        await productRepository.UpdateVoiceNotificationServerFilePathAsync(voiceNotificationServer.Model.VoiceNotificationServerId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(voiceNotificationServer.Model.CompanyId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Voice Notification Server File", ex);
            }
        }

