        public async Task CreateOrUpdateVoiceNotificationServerDependentsAsync(VoiceNotificationServerUpdateModel model)
        {
            if (model.NewVoiceNotificationServerXYZZYXModels == null)
                model.NewVoiceNotificationServerXYZZYXModels = new List<VoiceNotificationServerXYZZYXCreateModel>();

            if (model.ExistingVoiceNotificationServerXYZZYXModels == null)
                model.ExistingVoiceNotificationServerXYZZYXModels = new List<VoiceNotificationServerXYZZYXUpdateModel>();

            var dbExistingVoiceNotificationServers = await systemRepository.GetVoiceNotificationServerXYZZYXsByVoiceNotificationServerIdAsync(model.VoiceNotificationServerId);
            if (!dbExistingVoiceNotificationServers.IsNullOrEmpty())
            {
                var dbExistingVoiceNotificationServerIds = dbExistingVoiceNotificationServers.SelectToList(x => x.VoiceNotificationServerXYZZYXId);
                var modelExistingVoiceNotificationServerIds = model.ExistingVoiceNotificationServerXYZZYXModels.SelectToList(x => x.VoiceNotificationServerXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingVoiceNotificationServers.Where(x => !modelExistingVoiceNotificationServerIds.Contains(x.VoiceNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkVoiceNotificationServerXYZZYXAsDeletedByIdAsync(x.VoiceNotificationServerXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingVoiceNotificationServerXYZZYXModels.Where(x => dbExistingVoiceNotificationServerIds.Contains(x.VoiceNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.VoiceNotificationServerId = model.VoiceNotificationServerId;
                    var result = await UpdateVoiceNotificationServerXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewVoiceNotificationServerXYZZYXModels)
            {
                x.VoiceNotificationServerId = model.VoiceNotificationServerId;
                var result = await CreateVoiceNotificationServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

