        public async Task<ReturnModel<bool>> AssociateXYZZYXWithVoiceNotificationServerAsync(VoiceNotificationServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVoiceNotificationServerWithVoiceNotificationServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Voice Notification Server association is invalid", errorLst);
                }

                if (await systemRepository.DoesVoiceNotificationServerWithXYZZYXAssociationExistsAsync(model.VoiceNotificationServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Voice Notification Server is already associated with the Voice Notification Server", new { model.VoiceNotificationServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateVoiceNotificationServerWithXYZZYXAsync(model.VoiceNotificationServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Voice Notification Server with XYZZYX", new { model.VoiceNotificationServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Voice Notification Server with XYZZYX", new { model.VoiceNotificationServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithVoiceNotificationServerAsync(VoiceNotificationServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVoiceNotificationServerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Voice Notification Server association is not valid", errorLst);
                }

                if (!await systemRepository.DoesVoiceNotificationServerWithXYZZYXAssociationExistsAsync(model.VoiceNotificationServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Voice Notification Server is not associated with the Voice Notification Server", new { model.VoiceNotificationServerId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateVoiceNotificationServerWithVoiceNotificationServerAsync(model.VoiceNotificationServerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Voice Notification Server with the Voice Notification Server", new { model.VoiceNotificationServerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Voice Notification Server with the Voice Notification Server", new { model.VoiceNotificationServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsVoiceNotificationServerWithXYZZYXAssociationValidAsync(VoiceNotificationServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.VoiceNotificationServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Voice Notification Server is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Voice Notification Server  is not valid"));
                return result;
            }

            var entity = await GetVoiceNotificationServerForWriteByIdAsync(model.VoiceNotificationServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Voice Notification Server information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Voice Notification Servers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportVoiceNotificationServerAsync(VoiceNotificationServerImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Voice Notification Server Import Info is not provided");
                }

                if (model.VoiceNotificationServers == null || model.VoiceNotificationServers.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Voice Notification Servers Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.VoiceNotificationServers)
                {
                    var prod = await wipService.GetVoiceNotificationServerByExternalIdentifierAsync(item.VoiceNotificationServerIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        VoiceNotificationServerCreateModel voiceNotificationServerCreateModel = new VoiceNotificationServerCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedVoiceNotificationServer = await CreateVoiceNotificationServerAsync(voiceNotificationServerCreateModel);
                        if (!newlyCreatedVoiceNotificationServer.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedVoiceNotificationServer.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedVoiceNotificationServer.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        VoiceNotificationServerUpdateModel voiceNotificationServerUpdateModel = new VoiceNotificationServerUpdateModel
                        {
                        };

                        //update product
                        var updatedVoiceNotificationServerModel = await wipService.UpdateVoiceNotificationServerAsync(voiceNotificationServerUpdateModel);
                        if (!updatedVoiceNotificationServerModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModel<ImportStatusModel>("Unexpected error occurred when importing Voice Notification Server Info", ex);
            }
        }

        public async Task<ReturnListModel<VoiceNotificationServerExportModel>> ExportVoiceNotificationServerAsync(VoiceNotificationServerExportParameter filter, bool isTest)
        {
            try
            {
                var voiceNotificationServerCount = await systemRepository.GetVoiceNotificationServerCountAsync(filter);
                if (voiceNotificationServerCount == 0)
                {
                    return log.ErrorAndReturnListModel<VoiceNotificationServerExportModel>("No Voice Notification Server available for export.");
