        public async Task<ReturnListModel<WhatsAppNotificationServerModel>> CreateMultipleWhatsAppNotificationServerAsync(MultipleWhatsAppNotificationServerCreateModel whatsAppNotificationServers)
        {
            try
            {
                if (whatsAppNotificationServers == null)
                {
                    return log.ErrorAndReturnListModel<WhatsAppNotificationServerModel>($"Unable to Create Whats App Notification Servers", new ReturnErrorItem("", "Whats App Notification Servers information is not valid"));
                }

                if (whatsAppNotificationServers.NewWhatsAppNotificationServers.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<WhatsAppNotificationServerModel>($"Unable to Create Whats App Notification Servers", new ReturnErrorItem("", "Whats App Notification Servers information is not provided"));
                }

                var lst = new List<WhatsAppNotificationServerModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var whatsAppNotificationServer in whatsAppNotificationServers.NewWhatsAppNotificationServers)
                    {
                        var cResult = await CreateWhatsAppNotificationServerAsync(whatsAppNotificationServer);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<WhatsAppNotificationServerModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<WhatsAppNotificationServerModel>($"Unexpected error when creating Whats App Notification Servers", new { whatsAppNotificationServers }, ex);
            }
        }

        public async Task<ReturnModel<WhatsAppNotificationServerModel>> CreateWhatsAppNotificationServerAsync(WhatsAppNotificationServerCreateModel whatsAppNotificationServer)
        {
            try
            {
                if (whatsAppNotificationServer == null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to create Whats App Notification Server", new ReturnErrorItem("", "Whats App Notification Server information is not valid"));
                }

                //if (!await permissionService.IsUserSuperAdmin())
                //{
                //    whatsAppNotificationServer.CompanyId = await currentSessionService.GetCurrentCompanyIdAsync() ?? 0;
                //}

                //var companyModel = await companyService.GetCompanyByIdForReadAsync(whatsAppNotificationServer.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieByIdForReadAsync(whatsAppNotificationServer.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>(movieModel);
                //}

                var ignoreCode = false;
                if (whatsAppNotificationServer.WhatsAppNotificationServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    whatsAppNotificationServer.WhatsAppNotificationServerCode = StringConstants.PrefixForCode.WhatsAppNotificationServer + Guid.NewGuid().ToString();
                }

                var errorList = await IsWhatsAppNotificationServerModelValidForCreateAsync(whatsAppNotificationServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to create Whats App Notification Server", errorList);
                }

                whatsAppNotificationServer.IsDeleted = false;

                var item = objectMapperService.WhatsAppNotificationServerCreateModelToWhatsAppNotificationServer(whatsAppNotificationServer);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateWhatsAppNotificationServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Whats App Notification Server");
                    }

                    //await CreateOrUpdateWhatsAppNotificationServerDependentsAsync(whatsAppNotificationServer)

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdateWhatsAppNotificationServerCodeAsync(item.WhatsAppNotificationServerId, StringConstants.PrefixForCode.WhatsAppNotificationServer + item.WhatsAppNotificationServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Whats App Notification Server Code", item);
                        }
                    }

                    await trx.CompleteAsync();
                }

                await auditService.WhatsAppNotificationServerCreatedAsync(item.WhatsAppNotificationServerId);

                var view = await systemRepository.GetWhatsAppNotificationServerViewByIdAsync(item.WhatsAppNotificationServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to find the Whats App Notification Server", new { item.WhatsAppNotificationServerId });
                }

                return this.ConvertToItem(view, objectMapperService.WhatsAppNotificationServerViewToWhatsAppNotificationServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<WhatsAppNotificationServerModel>($"Unexpected error when creating Whats App Notification Server", new { whatsAppNotificationServer?.WhatsAppNotificationServerId }, ex);
            }
        }

        public async Task<ReturnModel<WhatsAppNotificationServerModel>> UpdateWhatsAppNotificationServerAsync(WhatsAppNotificationServerUpdateModel whatsAppNotificationServer)
        {
            try
            {
                if (whatsAppNotificationServer == null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to update Whats App Notification Server", new ReturnErrorItem("", "Whats App Notification Server information is not valid"));
                }

                var existingWhatsAppNotificationServerModel = await GetWhatsAppNotificationServerByIdForWriteAsync(whatsAppNotificationServer.WhatsAppNotificationServerId);
                if (!existingWhatsAppNotificationServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>(existingWhatsAppNotificationServerModel);
                }

                //var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(whatsAppNotificationServer.CompanyId);

                //if (resultValue == false)
                //{
                //    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>(errorStr);
                //}

                //if (canAssign)
                //{
                //    whatsAppNotificationServer.CompanyId = await currentSessionService.GetCurrentCompanyIdAsync() ?? 0;
                //}

                whatsAppNotificationServer.CreatedByUserId = existingWhatsAppNotificationServerModel.Model.CreatedByUserId;
                whatsAppNotificationServer.CreatedDate = existingWhatsAppNotificationServerModel.Model.CreatedDate;
                whatsAppNotificationServer.IsDeleted = existingWhatsAppNotificationServerModel.Model.IsDeleted;
                //whatsAppNotificationServer.CompanyId = existingWhatsAppNotificationServerModel.Model.CompanyId;
                //whatsAppNotificationServer.MovieId = existingWhatsAppNotificationServerModel.Model.MovieId;
                //whatsAppNotificationServer.ProfileImageActualFileName = existingWhatsAppNotificationServerModel.Model.ProfileImageActualFileName;
                //whatsAppNotificationServer.ProfileImageLocation = existingWhatsAppNotificationServerModel.Model.ProfileImageLocation;

                var errorList = await IsWhatsAppNotificationServerModelValidForUpdateAsync(whatsAppNotificationServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to update Whats App Notification Server", errorList);
                }

                var item = objectMapperService.WhatsAppNotificationServerUpdateModelToWhatsAppNotificationServer(whatsAppNotificationServer);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateWhatsAppNotificationServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Whats App Notification Server");
                    }

                    //await CreateOrUpdateWhatsAppNotificationServerDependentsAsync(whatsAppNotificationServer)

                    await trx.CompleteAsync();
                }

                await auditService.WhatsAppNotificationServerUpdatedAsync(whatsAppNotificationServer.WhatsAppNotificationServerId);

                var view = await systemRepository.GetWhatsAppNotificationServerViewByIdAsync(whatsAppNotificationServer.WhatsAppNotificationServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unable to find the Whats App Notification Server", new { whatsAppNotificationServer.WhatsAppNotificationServerId });
                }

                return this.ConvertToItem(view, objectMapperService.WhatsAppNotificationServerViewToWhatsAppNotificationServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<WhatsAppNotificationServerModel>($"Unexpected error when updating Whats App Notification Server", new { whatsAppNotificationServer?.WhatsAppNotificationServerId }, ex);
            }
        }

