        }

        public async Task<List<ReturnErrorItem>> IsWhatsAppNotificationServerModelValidForAllAsync(bool isCreate, WhatsAppNotificationServerUpdateModel whatsAppNotificationServerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsWhatsAppNotificationServerNameAlreadyExistsForOtherWhatsAppNotificationServerAsync(whatsAppNotificationServerModel.WhatsAppNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Whats App Notification Server already exists"));
                }

                if (whatsAppNotificationServerModel.WhatsAppNotificationServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Whats App Notification Server Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsWhatsAppNotificationServerNameAlreadyExistsForOtherWhatsAppNotificationServerAsync(whatsAppNotificationServerModel.WhatsAppNotificationServerId, whatsAppNotificationServerModel.WhatsAppNotificationServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Whats App Notification Server already exists"));
                }

                if (whatsAppNotificationServerModel.WhatsAppNotificationServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Whats App Notification Server Unique Identifier is not valid"));
                }
            }

            if (whatsAppNotificationServerModel.WhatsAppNotificationServerCode != null && whatsAppNotificationServerModel.WhatsAppNotificationServerCode.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_WhatsAppNotificationServerCode)
            {
                result.Add(new ReturnErrorItem("WhatsAppNotificationServerCode", $"WhatsAppNotificationServerCode size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_WhatsAppNotificationServerCode}"));
            }

            if (whatsAppNotificationServerModel.WhatsAppNotificationServerCode == null)
            {
                result.Add(new ReturnErrorItem("WhatsAppNotificationServerCode", "WhatsAppNotificationServerCode is required "));
            }

            if (whatsAppNotificationServerModel.WhatsAppNotificationServerName != null && whatsAppNotificationServerModel.WhatsAppNotificationServerName.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_WhatsAppNotificationServerName)
            {
                result.Add(new ReturnErrorItem("WhatsAppNotificationServerName", $"WhatsAppNotificationServerName size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_WhatsAppNotificationServerName}"));
            }

            if (whatsAppNotificationServerModel.WhatsAppNotificationServerName == null)
            {
                result.Add(new ReturnErrorItem("VoiceNotificationServerName", "VoiceNotificationServerName is required "));
            }

            if (whatsAppNotificationServerModel.PredefinedSmsAndVoiceServerTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedSmsAndVoiceServerTypeId", "PredefinedSmsAndVoiceServerTypeId cannot be empty"));
            }

            if (whatsAppNotificationServerModel.ApiKey != null && whatsAppNotificationServerModel.ApiKey.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_ApiKey)
            {
                result.Add(new ReturnErrorItem("ApiKey", $"ApiKey size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_ApiKey}"));
            }

            if (whatsAppNotificationServerModel.ApiKey == null)
            {
                result.Add(new ReturnErrorItem("ApiKey", "ApiKey is required "));
            }

            if (whatsAppNotificationServerModel.ApiSecret != null && whatsAppNotificationServerModel.ApiSecret.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_ApiSecret)
            {
                result.Add(new ReturnErrorItem("ApiSecret", $"ApiSecret size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_ApiSecret}"));
            }

            if (whatsAppNotificationServerModel.PhoneNumberId != null && whatsAppNotificationServerModel.PhoneNumberId.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_PhoneNumberId)
            {
                result.Add(new ReturnErrorItem("PhoneNumberId", $"PhoneNumberId size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_PhoneNumberId}"));
            }

            if (whatsAppNotificationServerModel.PhoneNumberId == null)
            {
                result.Add(new ReturnErrorItem("PhoneNumberId", "PhoneNumberId is required "));
            }

            if (whatsAppNotificationServerModel.BusinessAccountId != null && whatsAppNotificationServerModel.BusinessAccountId.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_BusinessAccountId)
            {
                result.Add(new ReturnErrorItem("BusinessAccountId", $"BusinessAccountId size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_BusinessAccountId}"));
            }

            if (whatsAppNotificationServerModel.BusinessAccountId == null)
            {
                result.Add(new ReturnErrorItem("BusinessAccountId", "BusinessAccountId is required "));
            }

            if (whatsAppNotificationServerModel.SenderPhoneNumber != null && whatsAppNotificationServerModel.SenderPhoneNumber.Length > WhatsAppNotificationServerModel.COLUMN_SIZE_SenderPhoneNumber)
            {
                result.Add(new ReturnErrorItem("SenderPhoneNumber", $"SenderPhoneNumber size should not exceed {WhatsAppNotificationServerModel.COLUMN_SIZE_SenderPhoneNumber}"));
            }

            return result.Count > 0 ? result : null;
        }

