        public async Task<ReturnModel<bool>> UploadWhatsAppNotificationServerFileAsync(long whatsAppNotificationServerId, FileStreamModel streamModel)
        {
            try
            {
                var whatsAppNotificationServer = await GetWhatsAppNotificationServerByIdForWriteAsync(whatsAppNotificationServerId);
                if (!whatsAppNotificationServer.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(whatsAppNotificationServer);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(whatsAppNotificationServer.Model.CompanyId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(whatsAppNotificationServer.Model.CompanyId, whatsAppNotificationServer.Model.WhatsAppNotificationServerId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(whatsAppNotificationServer.Model.CompanyId, whatsAppNotificationServer.Model.WhatsAppNotificationServerId, streamModel.FileName);
                        await productRepository.UpdateWhatsAppNotificationServerFilePathAsync(whatsAppNotificationServer.Model.WhatsAppNotificationServerId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(whatsAppNotificationServer.Model.CompanyId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Whats App Notification Server File", ex);
            }
        }

