            try
            {
                var whatsAppNotificationServer = await GetWhatsAppNotificationServerByIdForWriteAsync(whatsAppNotificationServerId);
                if (!whatsAppNotificationServer.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(whatsAppNotificationServer);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearWhatsAppNotificationServerFilePathAsync(whatsAppNotificationServer.Model.WhatsAppNotificationServerId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(whatsAppNotificationServer.Model.CompanyId, whatsAppNotificationServer.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Whats App Notification Server File", ex);
            }
        }

        public async Task CreateOrUpdateWhatsAppNotificationServerDependentsAsync(WhatsAppNotificationServerUpdateModel model)
        {
            if (model.NewWhatsAppNotificationServerXYZZYXModels == null)
                model.NewWhatsAppNotificationServerXYZZYXModels = new List<WhatsAppNotificationServerXYZZYXCreateModel>();

            if (model.ExistingWhatsAppNotificationServerXYZZYXModels == null)
                model.ExistingWhatsAppNotificationServerXYZZYXModels = new List<WhatsAppNotificationServerXYZZYXUpdateModel>();

            var dbExistingWhatsAppNotificationServers = await systemRepository.GetWhatsAppNotificationServerXYZZYXsByWhatsAppNotificationServerIdAsync(model.WhatsAppNotificationServerId);
            if (!dbExistingWhatsAppNotificationServers.IsNullOrEmpty())
            {
                var dbExistingWhatsAppNotificationServerIds = dbExistingWhatsAppNotificationServers.SelectToList(x => x.WhatsAppNotificationServerXYZZYXId);
                var modelExistingWhatsAppNotificationServerIds = model.ExistingWhatsAppNotificationServerXYZZYXModels.SelectToList(x => x.WhatsAppNotificationServerXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingWhatsAppNotificationServers.Where(x => !modelExistingWhatsAppNotificationServerIds.Contains(x.WhatsAppNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkWhatsAppNotificationServerXYZZYXAsDeletedByIdAsync(x.WhatsAppNotificationServerXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingWhatsAppNotificationServerXYZZYXModels.Where(x => dbExistingWhatsAppNotificationServerIds.Contains(x.WhatsAppNotificationServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.WhatsAppNotificationServerId = model.WhatsAppNotificationServerId;
                    var result = await UpdateWhatsAppNotificationServerXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewWhatsAppNotificationServerXYZZYXModels)
            {
                x.WhatsAppNotificationServerId = model.WhatsAppNotificationServerId;
                var result = await CreateWhatsAppNotificationServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

