        public async Task<ReturnModel<bool>> AssociateXYZZYXWithWhatsAppNotificationServerAsync(WhatsAppNotificationServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsWhatsAppNotificationServerWithWhatsAppNotificationServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Whats App Notification Server association is invalid", errorLst);
                }

                if (await systemRepository.DoesWhatsAppNotificationServerWithXYZZYXAssociationExistsAsync(model.WhatsAppNotificationServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Whats App Notification Server is already associated with the Whats App Notification Server", new { model.WhatsAppNotificationServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateWhatsAppNotificationServerWithXYZZYXAsync(model.WhatsAppNotificationServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Whats App Notification Server with XYZZYX", new { model.WhatsAppNotificationServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Whats App Notification Server with XYZZYX", new { model.WhatsAppNotificationServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithWhatsAppNotificationServerAsync(WhatsAppNotificationServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsWhatsAppNotificationServerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Whats App Notification Server association is not valid", errorLst);
                }

                if (!await systemRepository.DoesWhatsAppNotificationServerWithXYZZYXAssociationExistsAsync(model.WhatsAppNotificationServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Whats App Notification Server is not associated with the Whats App Notification Server", new { model.WhatsAppNotificationServerId, model.XYZZYXId });
