            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Whats App Notification Server with the Whats App Notification Server", new { model.WhatsAppNotificationServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsWhatsAppNotificationServerWithXYZZYXAssociationValidAsync(WhatsAppNotificationServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.WhatsAppNotificationServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Whats App Notification Server is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Whats App Notification Server  is not valid"));
                return result;
            }

            var entity = await GetWhatsAppNotificationServerForWriteByIdAsync(model.WhatsAppNotificationServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Whats App Notification Server information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Whats App Notification Servers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

