        public async Task<ReturnModel<SingleSignOnServerModel>> CreateSingleSignOnServerAsync(SingleSignOnServerCreateModel singleSignOnServer)
        {
            try
            {
                if (singleSignOnServer == null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to create Single Sign On Server", new ReturnErrorItem("", "Single Sign On Server information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to create Single SignOn Server", new ReturnErrorItem("", "Only super admin can create the Single SignOn Server Configuration"));
                }

                var ignoreCode = false;
                if (singleSignOnServer.SingleSignOnServerCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    singleSignOnServer.SingleSignOnServerCode = StringConstants.PrefixForCode.SingleSignOnServer + Guid.NewGuid().ToString();
                }

                //var companyModel = await GetCompanyForReadById(singleSignOnServer.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SingleSignOnServerModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(singleSignOnServer.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<SingleSignOnServerModel>(movieModel);
                //}

                var errorList = await IsSingleSignOnServerModelValidForCreateAsync(singleSignOnServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to create Single Sign On Server", errorList);
                }

                singleSignOnServer.IsDeleted = false;

                var item = objectMapperService.SingleSignOnServerCreateModelToSingleSignOnServer(singleSignOnServer);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateSingleSignOnServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Single Sign On Server");
                    }

                    if (ignoreCode)
                    {
                        if (!await systemRepository.UpdateSingleSignOnServerCodeAsync(item.SingleSignOnServerId, StringConstants.PrefixForCode.SingleSignOnServer + item.SingleSignOnServerId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the SingleSignOnServer Code", item);
                        }
                    }

                    singleSignOnServer.SingleSignOnServerId = item.SingleSignOnServerId;
                    await CreateOrUpdateSingleSignOnServerDependentsAsync(objectMapperService.SingleSignOnServerCreateModelToSingleSignOnServerModel(singleSignOnServer));

                    await trx.CompleteAsync();
                }

                await auditService.SingleSignOnServerCreatedAsync(item.SingleSignOnServerId);

                var view = await systemRepository.GetSingleSignOnServerViewByIdAsync(item.SingleSignOnServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to find the Single Sign On Server", new { item.SingleSignOnServerId });
                }

                return this.ConvertToItem(view, objectMapperService.SingleSignOnServerViewToSingleSignOnServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<SingleSignOnServerModel>($"Unexpected error when creating Single Sign On Server", new { singleSignOnServer?.SingleSignOnServerId }, ex);
            }
        }

        public async Task<ReturnModel<SingleSignOnServerModel>> UpdateSingleSignOnServerAsync(SingleSignOnServerUpdateModel singleSignOnServer)
        {
            try
            {
                if (singleSignOnServer == null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to update Single Sign On Server", new ReturnErrorItem("", "Single Sign On Server information is not valid"));
                }

                var existingSingleSignOnServerModel = await GetSingleSignOnServerByIdForWriteAsync(singleSignOnServer.SingleSignOnServerId);
                if (!existingSingleSignOnServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>(existingSingleSignOnServerModel);
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to create Single SignOn Server", new ReturnErrorItem("", "Only super admin can create the Single SignOn Server Configuration"));
                }

                singleSignOnServer.CreatedByUserId = existingSingleSignOnServerModel.Model.CreatedByUserId;
                singleSignOnServer.CreatedDate = existingSingleSignOnServerModel.Model.CreatedDate;
                singleSignOnServer.IsDeleted = existingSingleSignOnServerModel.Model.IsDeleted;
                singleSignOnServer.SingleSignOnServerCode = existingSingleSignOnServerModel.Model.SingleSignOnServerCode;

                var errorList = await IsSingleSignOnServerModelValidForUpdateAsync(singleSignOnServer);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to update Single Sign On Server", errorList);
                }

                var item = objectMapperService.SingleSignOnServerUpdateModelToSingleSignOnServer(singleSignOnServer);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateSingleSignOnServerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Single Sign On Server");
                    }

                    await CreateOrUpdateSingleSignOnServerDependentsAsync(objectMapperService.SingleSignOnServerUpdateModelToSingleSignOnServerModel(singleSignOnServer));

                    await trx.CompleteAsync();
                }

                await auditService.SingleSignOnServerUpdatedAsync(singleSignOnServer.SingleSignOnServerId, existingSingleSignOnServerModel.Model, item);

                var view = await systemRepository.GetSingleSignOnServerViewByIdAsync(singleSignOnServer.SingleSignOnServerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unable to find the Single Sign On Server", new { singleSignOnServer.SingleSignOnServerId });
                }

                return this.ConvertToItem(view, objectMapperService.SingleSignOnServerViewToSingleSignOnServerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<SingleSignOnServerModel>($"Unexpected error when updating Single Sign On Server", new { singleSignOnServer?.SingleSignOnServerId }, ex);
            }
        }

        public async Task CreateOrUpdateSingleSignOnServerDependentsAsync(SingleSignOnServerModel model)
        {
            if (model.IsDefault)
            {
                var result = await systemRepository.ResetAllDefaultSingleSignOnServerByTypeAsync(model.PredefinedSingleSignOnServerTypeId, await currentSessionService.GetCurrentUserIdAsync());
                if (!result)
                    throw new RollbackException("Unable to reset default single sign on server");

                result = await systemRepository.SetSingleSignOnServerAsDefaultAsync(model.SingleSignOnServerId, await currentSessionService.GetCurrentUserIdAsync());
                if (!result)
                    throw new RollbackException("Unable to set single sign on server as default");
            }
        }

