        public async Task<ReturnModel<bool>> HardDeleteSingleSignOnServerByAsync(long singleSignOnServerId)
        {
            try
            {
                var existingSingleSignOnServerModel = await GetSingleSignOnServerByIdForWriteAsync(singleSignOnServerId);
                if (!existingSingleSignOnServerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(existingSingleSignOnServerModel);
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    return log.ErrorAndReturnModel<bool>($"Unable to mark Single SignOn Server as deleted", new ReturnErrorItem("", "Only super admin can mark the Single SignOn Server Configuration as deleted"));
                }

                bool result;

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.HardDeleteSingleSignOnServerByIdAsync(singleSignOnServerId);
                    await trx.CompleteAsync();
                }

                await auditService.HardDeleteSingleSignOnServerAsync(singleSignOnServerId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when deleting Single Sign On Server", new { singleSignOnServerId }, ex);
            }
        }

