        public async Task<List<ReturnErrorItem>> IsSingleSignOnServerModelValidForAllAsync(bool isCreate, SingleSignOnServerUpdateModel singleSignOnServerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsSingleSignOnServerNameAlreadyExistsForOtherSingleSignOnServerAsync(singleSignOnServerModel.SingleSignOnServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Single Sign On Server already exists"));
                }

                if (singleSignOnServerModel.SingleSignOnServerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Single Sign On Server Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsSingleSignOnServerNameAlreadyExistsForOtherSingleSignOnServerAsync(singleSignOnServerModel.SingleSignOnServerId, singleSignOnServerModel.SingleSignOnServerName))
                {
                    result.Add(new ReturnErrorItem("", "Another Single Sign On Server already exists"));
                }

                if (singleSignOnServerModel.SingleSignOnServerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Single Sign On Server Unique Identifier is not valid"));
                }
            }

            if (singleSignOnServerModel.SingleSignOnServerName != null && singleSignOnServerModel.SingleSignOnServerName.Length > SingleSignOnServerModel.COLUMN_SIZE_SingleSignOnServerName)
            {
                result.Add(new ReturnErrorItem("SingleSignOnServerName", $"SingleSignOnServerName size should not exceed {SingleSignOnServerModel.COLUMN_SIZE_SingleSignOnServerName}"));
            }

            if (!ValidationUtils.IsLongValid(singleSignOnServerModel.PredefinedSingleSignOnServerTypeId))
            {
                result.Add(new ReturnErrorItem("SingleSignOnServerTypeId", "SingleSignOnServerType cannot be empty"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedSingleSignOnServerTypes, long>(singleSignOnServerModel.PredefinedSingleSignOnServerTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedSingleSignOnServerTypeId", "Single SignOn Server Type is not valid"));
            }

            if (singleSignOnServerModel.Host != null && singleSignOnServerModel.Host.Length > SingleSignOnServerModel.COLUMN_SIZE_Host)
            {
                result.Add(new ReturnErrorItem("Host", $"Host size should not exceed {SingleSignOnServerModel.COLUMN_SIZE_Host}"));
            }

            if (singleSignOnServerModel.ClientId != null && singleSignOnServerModel.ClientId.Length > SingleSignOnServerModel.COLUMN_SIZE_ClientId)
            {
                result.Add(new ReturnErrorItem("ClientId", $"ClientId size should not exceed {SingleSignOnServerModel.COLUMN_SIZE_ClientId}"));
            }

            if (singleSignOnServerModel.ClientSecret != null && singleSignOnServerModel.ClientSecret.Length > SingleSignOnServerModel.COLUMN_SIZE_ClientSecret)
            {
                result.Add(new ReturnErrorItem("ClientSecret", $"ClientSecret size should not exceed {SingleSignOnServerModel.COLUMN_SIZE_ClientSecret}"));
            }

            var existingDefaultSSOServer = await systemRepository.GetDefaultSingleSignOnServerAsync(singleSignOnServerModel.PredefinedSingleSignOnServerTypeId);

            if (existingDefaultSSOServer != null && singleSignOnServerModel.IsDefault && existingDefaultSSOServer.SingleSignOnServerId != singleSignOnServerModel.SingleSignOnServerId)
            {
                result.Add(new ReturnErrorItem("IsDefault", "This Single SignOn Server Type is already set as default"));
            }

            return result.Count > 0 ? result : null;
        }

