        public async Task CreateOrUpdateSingleSignOnServerDependentsAsync(SingleSignOnServerModel model)
        {
            if (model.NewSingleSignOnServerXYZZYXModels == null)
                model.NewSingleSignOnServerXYZZYXModels = new List<SingleSignOnServerXYZZYXCreateModel>();

            if (model.ExistingSingleSignOnServerXYZZYXModels == null)
                model.ExistingSingleSignOnServerXYZZYXModels = new List<SingleSignOnServerXYZZYXUpdateModel>();

            var dbExistingSingleSignOnServers = await systemRepository.GetSingleSignOnServerXYZZYXsBySingleSignOnServerIdAsync(model.SingleSignOnServerId);
            if (!dbExistingSingleSignOnServers.IsNullOrEmpty())
            {
                var dbExistingSingleSignOnServerIds = dbExistingSingleSignOnServers.SelectToList(x => x.SingleSignOnServerXYZZYXId);
                var modelExistingSingleSignOnServerIds = model.ExistingSingleSignOnServerXYZZYXModels.SelectToList(x => x.SingleSignOnServerXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingSingleSignOnServers.Where(x => !modelExistingSingleSignOnServerIds.Contains(x.SingleSignOnServerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await MarkSingleSignOnServerXYZZYXAsDeletedByIdAsync(x.SingleSignOnServerXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingSingleSignOnServerXYZZYXModels.Where(x => dbExistingSingleSignOnServerIds.Contains(x.SingleSignOnServerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.SingleSignOnServerId = model.SingleSignOnServerId;
                    var result = await UpdateSingleSignOnServerXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewSingleSignOnServerXYZZYXModels)
            {
                x.SingleSignOnServerId = model.SingleSignOnServerId;
                var result = await CreateSingleSignOnServerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

