                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.EnableSingleSignOnServerByIdAsync(existingSingleSignOnServerModel.Model.SingleSignOnServerId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
