        public async Task<ReturnModel<bool>> AssociateXYZZYXWithSingleSignOnServerAsync(SingleSignOnServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSingleSignOnServerWithSingleSignOnServerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Single Sign On Server association is invalid", errorLst);
                }

                if (await systemRepository.DoesSingleSignOnServerWithXYZZYXAssociationExistsAsync(model.SingleSignOnServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Single Sign On Server is already associated with the Single Sign On Server", new { model.SingleSignOnServerId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateSingleSignOnServerWithXYZZYXAsync(model.SingleSignOnServerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Single Sign On Server with XYZZYX", new { model.SingleSignOnServerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Single Sign On Server with XYZZYX", new { model.SingleSignOnServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithSingleSignOnServerAsync(SingleSignOnServerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsSingleSignOnServerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Single Sign On Server association is not valid", errorLst);
                }

                if (!await systemRepository.DoesSingleSignOnServerWithXYZZYXAssociationExistsAsync(model.SingleSignOnServerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Single Sign On Server is not associated with the Single Sign On Server", new { model.SingleSignOnServerId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateSingleSignOnServerWithSingleSignOnServerAsync(model.SingleSignOnServerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Single Sign On Server with the Single Sign On Server", new { model.SingleSignOnServerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Single Sign On Server with the Single Sign On Server", new { model.SingleSignOnServerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsSingleSignOnServerWithXYZZYXAssociationValidAsync(SingleSignOnServerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.SingleSignOnServerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Single Sign On Server is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Single Sign On Server  is not valid"));
                return result;
            }

            var entity = await GetSingleSignOnServerForWriteByIdAsync(model.SingleSignOnServerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Single Sign On Server information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Single Sign On Servers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

