        public async Task<ReturnModel<MessageTemplateModel>> CreateMessageTemplateAsync(MessageTemplateCreateModel messageTemplate)
        {
            try
            {
                if (messageTemplate == null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to create Message Template", new ReturnErrorItem("", "Message Template information is not valid"));
                }

                //var companyModel = await GetCompanyForReadById(messageTemplate.CompanyId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MessageTemplateModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieForReadById(messageTemplate.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<MessageTemplateModel>(movieModel);
                //}

                var errorList = await IsMessageTemplateModelValidForCreateAsync(messageTemplate);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to create Message Template", errorList);
                }

                messageTemplate.IsDeleted = false;

                var item = objectMapperService.MessageTemplateCreateModelToMessageTemplate(messageTemplate);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await systemRepository.CreateMessageTemplateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Message Template");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.MessageTemplateCreatedAsync(item.MessageTemplateId);

                var view = await systemRepository.GetMessageTemplateViewByIdAsync(item.MessageTemplateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to find the Message Template", new { item.MessageTemplateId });
                }

                return this.ConvertToItem(view, objectMapperService.MessageTemplateViewToMessageTemplateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<MessageTemplateModel>($"Unexpected error when creating Message Template", new { messageTemplate?.MessageTemplateId }, ex);
            }
        }

        public async Task<ReturnModel<MessageTemplateModel>> UpdateMessageTemplateAsync(MessageTemplateUpdateModel messageTemplate)
        {
            try
            {
                if (messageTemplate == null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to update Message Template", new ReturnErrorItem("", "Message Template information is not valid"));
                }

                var existingMessageTemplateModel = await GetMessageTemplateByIdForWriteAsync(messageTemplate.MessageTemplateId);
                if (!existingMessageTemplateModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>(existingMessageTemplateModel);
                }

                messageTemplate.CreatedByUserId = existingMessageTemplateModel.Model.CreatedByUserId;
                messageTemplate.CreatedDate = existingMessageTemplateModel.Model.CreatedDate;
                messageTemplate.IsDeleted = existingMessageTemplateModel.Model.IsDeleted;
                //messageTemplate.MovieId = existingMessageTemplateModel.Model.MovieId;

                var errorList = await IsMessageTemplateModelValidForUpdateAsync(messageTemplate);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to update Message Template", errorList);
                }

                var item = objectMapperService.MessageTemplateUpdateModelToMessageTemplate(messageTemplate);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await systemRepository.UpdateMessageTemplateAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Message Template");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.MessageTemplateUpdatedAsync(messageTemplate.MessageTemplateId, existingMessageTemplateModel.Model, item);

                var view = await systemRepository.GetMessageTemplateViewByIdAsync(messageTemplate.MessageTemplateId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MessageTemplateModel>($"Unable to find the Message Template", new { messageTemplate.MessageTemplateId });
                }

                return this.ConvertToItem(view, objectMapperService.MessageTemplateViewToMessageTemplateModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<MessageTemplateModel>($"Unexpected error when updating Message Template", new { messageTemplate?.MessageTemplateId }, ex);
            }
        }

