        public async Task<List<ReturnErrorItem>> IsMessageTemplateModelValidForAllAsync(bool isCreate, MessageTemplateUpdateModel messageTemplateModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await systemRepository.IsMessageTemplateNameAlreadyExistsForOtherMessageTemplateAsync(messageTemplateModel.PredefinedMessageTemplateTypeId))
                {
                    result.Add(new ReturnErrorItem("", "Another Message Template already exists"));
                }

                if (messageTemplateModel.MessageTemplateId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Message Template Identifier is not valid"));
                }
            }
            else
            {
                if (await systemRepository.IsMessageTemplateNameAlreadyExistsForOtherMessageTemplateAsync(messageTemplateModel.MessageTemplateId, messageTemplateModel.PredefinedMessageTemplateTypeId))
                {
                    result.Add(new ReturnErrorItem("", "Another Message Template already exists"));
                }

                if (messageTemplateModel.MessageTemplateId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Message Template Unique Identifier is not valid"));
                }
            }

            if (messageTemplateModel.PredefinedMessageTemplateTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedMessageTemplateTypeId", "PredefinedMessageTemplateTypeId cannot be empty"));
            }

            if (messageTemplateModel.EmailSubject != null && messageTemplateModel.EmailSubject.Length > MessageTemplateModel.COLUMN_SIZE_EmailSubject)
            {
                result.Add(new ReturnErrorItem("EmailSubject", $"EmailSubject size should not exceed {MessageTemplateModel.COLUMN_SIZE_EmailSubject}"));
            }

            if (messageTemplateModel.EmailSubject == null)
            {
                result.Add(new ReturnErrorItem("EmailSubject", "EmailSubject is required "));
            }

            if (messageTemplateModel.EmailBody != null && messageTemplateModel.EmailBody.Length > MessageTemplateModel.COLUMN_SIZE_EmailBody)
            {
                result.Add(new ReturnErrorItem("EmailBody", $"EmailBody size should not exceed {MessageTemplateModel.COLUMN_SIZE_EmailBody}"));
            }

            if (messageTemplateModel.EmailBody == null)
            {
                result.Add(new ReturnErrorItem("EmailBody", "EmailBody is required "));
            }

            if (messageTemplateModel.SmsBody != null && messageTemplateModel.SmsBody.Length > MessageTemplateModel.COLUMN_SIZE_SmsBody)
            {
                result.Add(new ReturnErrorItem("SmsBody", $"SmsBody size should not exceed {MessageTemplateModel.COLUMN_SIZE_SmsBody}"));
            }

            if (messageTemplateModel.SmsBody == null)
            {
                result.Add(new ReturnErrorItem("SmsBody", "SmsBody is required "));
            }

            if (messageTemplateModel.AppNotificationSubject != null && messageTemplateModel.AppNotificationSubject.Length > MessageTemplateModel.COLUMN_SIZE_AppNotificationSubject)
            {
                result.Add(new ReturnErrorItem("AppNotificationSubject", $"AppNotificationSubject size should not exceed {MessageTemplateModel.COLUMN_SIZE_AppNotificationSubject}"));
            }

            if (messageTemplateModel.AppNotificationSubject == null)
            {
                result.Add(new ReturnErrorItem("AppNotificationSubject", "AppNotificationSubject is required "));
            }

            if (messageTemplateModel.AppNotificationBody != null && messageTemplateModel.AppNotificationBody.Length > MessageTemplateModel.COLUMN_SIZE_AppNotificationBody)
            {
                result.Add(new ReturnErrorItem("AppNotificationBody", $"AppNotificationBody size should not exceed {MessageTemplateModel.COLUMN_SIZE_AppNotificationBody}"));
            }

            if (messageTemplateModel.AppNotificationBody == null)
            {
                result.Add(new ReturnErrorItem("AppNotificationBody", "AppNotificationBody is required "));
            }

            if (messageTemplateModel.WebNotificationSubject != null && messageTemplateModel.WebNotificationSubject.Length > MessageTemplateModel.COLUMN_SIZE_WebNotificationSubject)
            {
                result.Add(new ReturnErrorItem("WebNotificationSubject", $"WebNotificationSubject size should not exceed {MessageTemplateModel.COLUMN_SIZE_WebNotificationSubject}"));
            }

            if (messageTemplateModel.WebNotificationSubject == null)
            {
                result.Add(new ReturnErrorItem("WebNotificationSubject", "WebNotificationSubject is required "));
            }

            if (messageTemplateModel.WebNotificationBody != null && messageTemplateModel.WebNotificationBody.Length > MessageTemplateModel.COLUMN_SIZE_WebNotificationBody)
            {
                result.Add(new ReturnErrorItem("WebNotificationBody", $"WebNotificationBody size should not exceed {MessageTemplateModel.COLUMN_SIZE_WebNotificationBody}"));
            }

            if (messageTemplateModel.WebNotificationBody == null)
            {
                result.Add(new ReturnErrorItem("WebNotificationBody", "WebNotificationBody is required "));
            }

            if (messageTemplateModel.AdditionalRecipients != null && messageTemplateModel.AdditionalRecipients.Length > MessageTemplateModel.COLUMN_SIZE_AdditionalRecipients)
            {
                result.Add(new ReturnErrorItem("AdditionalRecipients", $"AdditionalRecipients size should not exceed {MessageTemplateModel.COLUMN_SIZE_AdditionalRecipients}"));
            }

            return result.Count > 0 ? result : null;
        }

