        public async Task CreateOrUpdateMessageTemplateDependentsAsync(MessageTemplateModel model)
        {
            if (model.NewMessageTemplateXYZZYXModels == null)
                model.NewMessageTemplateXYZZYXModels = new List<MessageTemplateXYZZYXCreateModel>();

            if (model.ExistingMessageTemplateXYZZYXModels == null)
                model.ExistingMessageTemplateXYZZYXModels = new List<MessageTemplateXYZZYXUpdateModel>();

            var dbExistingMessageTemplates = await systemRepository.GetMessageTemplateXYZZYXsByMessageTemplateIdAsync(model.MessageTemplateId);
            if (!dbExistingMessageTemplates.IsNullOrEmpty())
            {
                var dbExistingMessageTemplateIds = dbExistingMessageTemplates.SelectToList(x => x.MessageTemplateXYZZYXId);
                var modelExistingMessageTemplateIds = model.ExistingMessageTemplateXYZZYXModels.SelectToList(x => x.MessageTemplateXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingMessageTemplates.Where(x => !modelExistingMessageTemplateIds.Contains(x.MessageTemplateXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    await MarkMessageTemplateXYZZYXAsDeletedByIdAsync(x.MessageTemplateXYZZYXId);
                }

                var xYZZYXItemsToUpdate = model.ExistingMessageTemplateXYZZYXModels.Where(x => dbExistingMessageTemplateIds.Contains(x.MessageTemplateXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.MessageTemplateId = model.MessageTemplateId;
                    var result = await UpdateMessageTemplateXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewMessageTemplateXYZZYXModels)
            {
                x.MessageTemplateId = model.MessageTemplateId;
                var result = await CreateMessageTemplateXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

