        public async Task<ReturnModel<bool>> AssociateXYZZYXWithMessageTemplateAsync(MessageTemplateXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMessageTemplateWithMessageTemplateAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Message Template association is invalid", errorLst);
                }

                if (await systemRepository.DoesMessageTemplateWithXYZZYXAssociationExistsAsync(model.MessageTemplateId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Message Template is already associated with the Message Template", new { model.MessageTemplateId, model.XYZZYXId});
                }

                var rValue = await systemRepository.AssociateMessageTemplateWithXYZZYXAsync(model.MessageTemplateId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Message Template with XYZZYX", new { model.MessageTemplateId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Message Template with XYZZYX", new { model.MessageTemplateId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithMessageTemplateAsync(MessageTemplateXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanConfigureCompany(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMessageTemplateWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Message Template association is not valid", errorLst);
                }

                if (!await systemRepository.DoesMessageTemplateWithXYZZYXAssociationExistsAsync(model.MessageTemplateId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Message Template is not associated with the Message Template", new { model.MessageTemplateId, model.XYZZYXId });
                }

                var rValue = await systemRepository.UnAssociateMessageTemplateWithMessageTemplateAsync(model.MessageTemplateId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Message Template with the Message Template", new { model.MessageTemplateId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Message Template with the Message Template", new { model.MessageTemplateId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsMessageTemplateWithXYZZYXAssociationValidAsync(MessageTemplateXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.MessageTemplateId == 0)
            {
                result.Add(new ReturnErrorItem("", "Message Template is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Message Template  is not valid"));
                return result;
            }

            var entity = await GetMessageTemplateForWriteByIdAsync(model.MessageTemplateId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Message Template information is not avialable"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not avialable"));
                return result;
            }

            if (entity.CompanyId != xYZZYX.CompanyId)
            {
                result.Add(new ReturnErrorItem("", "Message Templates does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

