                return Task<ReturnModel<bool>>.FromResult(ReturnModel<bool>.Success(true));
            }
            catch (Exception ex)
            {
                return Task<ReturnModel<bool>>.FromResult(log.ErrorAndReturnModel<bool>("Unexpected error occurred during processing.", ex));
            }
        }

