        public async Task<ReturnModel<bool>> SendNotificationAsync(NotificationModel model, long predefinedMovieShootDayResourceTypeId)
        {
            try
            {
                model.IsNotificationStarted = true;
                ReturnModel<bool> result;

                // voice call notification
                var voiceNotificationConfig = await systemRepository.GetDefaultVoiceNotificationServerAsync();

                if (voiceNotificationConfig == null)
                {
                    model.PredefinedPhoneCallNotificationStatusTypeId = (long)PredefinedPhoneCallNotificationStatusTypes.ServerNotConfigured;
                    result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.VoiceNotification);
                    if (!result.IsSuccess)
                    {
                        return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                    }
                }
                else
                {
                    if (model.PhoneNumber.IsNullOrEmpty())
                    {
                        return log.ErrorAndReturnModel<bool>("Phone number is required to send voice call notification");
                    }

                    var call = await twilioService.InitiateAutomatedCallAsync(model.PhoneNumber, model.MovieShootDayResourceId, predefinedMovieShootDayResourceTypeId, "Hey There...", voiceNotificationConfig.TwilioAccountSid, voiceNotificationConfig.TwilioAccountAuthToken, voiceNotificationConfig.TwilioAccountPhoneNumber);
                    if (call.IsNullOrEmpty())
                    {
                        model.PredefinedPhoneCallNotificationStatusTypeId = (long)PredefinedPhoneCallNotificationStatusTypes.NotificationError;
                        result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.VoiceNotification);
                        if (!result.IsSuccess)
                        {
                            return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                        }
                    }
                }

                // sms notification
                var smsNotificationConfig = await systemRepository.GetDefaultSmsServerAsync();

                if (smsNotificationConfig == null)
                {
                    model.PredefinedSmsNotificationStatusTypeId = (long)PredefinedSMSNotificationStatusTypes.ServerNotConfigured;
                    result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.SMSNotification);
                    if (!result.IsSuccess)
                    {
                        return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                    }
                }
                else
                {
                    if (model.PhoneNumber.IsNullOrEmpty())
                    {
                        return log.ErrorAndReturnModel<bool>("Phone number is required to send sms notification");
                    }

                    var sms = await twilioService.InitiateAutomatedMessageAsync(model.PhoneNumber, model.MovieShootDayResourceId, predefinedMovieShootDayResourceTypeId, "Hey There...", smsNotificationConfig.TwilioAccountSid, smsNotificationConfig.TwilioAccountAuthToken, smsNotificationConfig.TwilioAccountPhoneNumber);
                    if (sms.IsNullOrEmpty())
                    {
                        model.PredefinedSmsNotificationStatusTypeId = (long)PredefinedSMSNotificationStatusTypes.NotificationError;
                        result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.SMSNotification);
                        if (!result.IsSuccess)
                        {
                            return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                        }
                    }
                }

                //mail notification
                var mailNotificationConfig = await systemRepository.GetDefaultMailServerAsync();

                if (mailNotificationConfig == null)
                {
                    model.PredefinedEmailNotificationStatusTypeId = (long)PredefinedEmailNotificationStatusTypes.ServerNotConfigured;
                    result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.EmailNotification);
                    if (!result.IsSuccess)
                    {
                        return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                    }
                }
                else
                {
                    if (model.Email.IsNullOrEmpty())
                    {
                        return log.ErrorAndReturnModel<bool>("Email is required to send email notification");
                    }

                    var email = await emailService.SendAsync(
                        mailNotificationConfig.Host,
                        (int)mailNotificationConfig.Port,
                        mailNotificationConfig.UserName,
                        mailNotificationConfig.Password,
                        true,
                        mailNotificationConfig.SenderName,
                        mailNotificationConfig.SenderEmail,
                        model.Email,
                        model.Email,
                        null,
                        null,
                        "Wakeup Notification",
                        "This is reminder email from Manifest",
                        useMailKit: true);

                    if (!email.IsSuccess)
                    {
                        model.PredefinedEmailNotificationStatusTypeId = (long)PredefinedEmailNotificationStatusTypes.NotificationError;
                        result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.EmailNotification);
                        if (!result.IsSuccess)
                        {
                            return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                        }
                    }
                }

                //WhatsApp notification
                var whatsAppNotificationConfig = await systemRepository.GetWhatsAppNotificationServerByIdAsync(0);

                if (whatsAppNotificationConfig == null)
                {
                    model.PredefinedWhatsAppNotificationStatusTypeId = (long)PredefinedWhatsAppNotificationStatusTypes.ServerNotConfigured;
                    result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.WhatsAppNotification);
                    if (!result.IsSuccess)
                    {
                        return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                    }
                }
                else
                {
                    if (model.PhoneNumber.IsNullOrEmpty())
                    {
                        return log.ErrorAndReturnModel<bool>("Phone number is required to send WhatsApp notification");
                    }

                    var whatsAppMessageModel = new WhatsAppMessageModel
                    {
                        MessagingProduct = "whatsapp",
                        RecipientType = "individual",
                        To = model.PhoneNumber,
                        Type = "text",
                        Text = new WhatsAppTextMessage
                        {
                            Body = "Hey There...",
                            PreviewUrl = false
                        }
                    };

                    var whatsAppNotification = await whatsAppService.SendMessageAsync(whatsAppNotificationConfig.WhatsAppNotificationServerId, whatsAppMessageModel);
                    if (!whatsAppNotification.IsSuccess)
                    {
                        model.PredefinedWhatsAppNotificationStatusTypeId = (long)PredefinedWhatsAppNotificationStatusTypes.NotificationError;
                        result = await UpdateMovieShootDayResourceNotificationStatusAsync(model, predefinedMovieShootDayResourceTypeId, (long)PredefinedNotificationTypes.WhatsAppNotification);
                        if (!result.IsSuccess)
                        {
                            return log.ErrorAndReturnModel<bool>("Failed to update resource status");
                        }
                    }
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>("Unexpected error occurred during processing.", ex);
            }
        }

        public async Task<ReturnModel<bool>> UpdateMovieShootDayResourceNotificationStatusAsync(NotificationModel model, long predefinedMovieShootDayResourceTypeId, long predefinedNotificationTypeId)
        {
