        public long GetNotificationStatusIdFromNotificationModel(NotificationModel model, long notificationTypeId)
        {
            return notificationTypeId switch
            {
                (long)PredefinedNotificationTypes.VoiceNotification => model.PredefinedPhoneCallNotificationStatusTypeId,
                (long)PredefinedNotificationTypes.SMSNotification => model.PredefinedSmsNotificationStatusTypeId,
                (long)PredefinedNotificationTypes.EmailNotification => model.PredefinedEmailNotificationStatusTypeId,
                (long)PredefinedNotificationTypes.PushNotification => model.PredefinedPushNotificationStatusTypeId,
                (long)PredefinedNotificationTypes.WhatsAppNotification => model.PredefinedWhatsAppNotificationStatusTypeId,
                _ => 0
            };
        }

