        #region System Functions

        public async Task<ReturnModel<SystemSummaryModel>> GetSystemSummaryAsync()
        {
            try
            {
                if (await currentSessionService.IsCurrentUserASuperAdminAsync() == false)
                {
                    return log.ErrorAndReturnModel<SystemSummaryModel>("You need to be a Super Admin to make this change");
                }

                var systemSummary = new SystemSummaryModel
                {
                    UsersCount = (long)await companyRepository.GetUserCountAsync(),
                    MessageToSendTotalCount = await systemRepository.GetMessageToSendCountAsync(),
                    MessageToSendSuccessCount = await systemRepository.GetMessageToSendSuccessCountAsync(),
                    MessageToSendErrorCount = await systemRepository.GetMessageToSendErrorCountAsync(),
                    TotalJobCount = await systemRepository.GetJobCountAsync(),
                    CurrentRunningJobsCount = await systemRepository.GetRunningJobCountAsync(),
                    JobSuccessCount = await systemRepository.GetJobSuccessCountAsync(),
                    JobErrorCount = await systemRepository.GetJobErrorCountAsync()
                };

                return ReturnModel<SystemSummaryModel>.Success(systemSummary);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<SystemSummaryModel>($"Unexpected error when consolidating system summaries", ex);
            }
        }

        #endregion
